-- CCN Exam Room: new Day 5 and Day 6 mock exams (200 questions each), October 2026.
-- Harder papers with an ICU calculation section, acid–base/ABG interpretation, mechanical
-- ventilation and clinical scenarios. Run once in the Supabase SQL Editor; safe to run again.
--
--   Section A  ICU calculations (drips, infusions, Parkland, doses, fluids)
--   Section B  Acid–base balance and ABG interpretation
--   Section C  Mechanical ventilation
--   Section D  Critical care clinical scenarios
--
-- The questions are added to the question bank as hidden rows (is_active = false), so they
-- appear only in these exams and not in the app's practice mode. Each exam's question list is
-- then replaced with the new 200 questions, in this order. Times, attempts and other settings
-- are not changed.

drop table if exists d56;
create temporary table d56 (day int, n int, topic text, q text, opts jsonb, ans_idx int, exp text, primary key (day, n));

-- 1. Add the questions that aren't in the bank yet (same wording, options and answer).
select (select coalesce(max(id), 0) from public.questions) + row_number() over (order by d.day, d.n),
       d.topic, case d.day when 5 then 'CCN Mock Exam — Day 5 (calculations, ABG, ventilation, scenarios)' else 'CCN Mock Exam — Day 6 (calculations, ABG, ventilation, scenarios)' end,
       d.q, d.opts, d.ans_idx, d.exp, 'Mock Exam', '📝', false
from d56 d
where not exists (select 1 from public.questions x where x.q = d.q and x.opts = d.opts and x.ans_idx = d.ans_idx);

-- 2. Put them into the Day 5 and Day 6 exams, in order.
update public.exam_exams e
   set question_ids = (select array_agg(x.id order by d.n)
                         from d56 d
                         join lateral (select min(id) id from public.questions q
                                        where q.q = d.q and q.opts = d.opts and q.ans_idx = d.ans_idx) x on true
                        where d.day = case e.title when 'CCN Mock Exam — Day 5 of 7 (200 Questions)' then 5 else 6 end)
 where e.title in ('CCN Mock Exam — Day 5 of 7 (200 Questions)', 'CCN Mock Exam — Day 6 of 7 (200 Questions)');

-- 3. Check: each exam should show 200 questions.
select title, cardinality(question_ids) as questions
from public.exam_exams
where title in ('CCN Mock Exam — Day 5 of 7 (200 Questions)', 'CCN Mock Exam — Day 6 of 7 (200 Questions)')
order by title;

drop table if exists d56;
