insert into d56 (day, n, topic, q, opts, ans_idx, exp) values
(5, 1, 'ICU Calculations', 'A 6 kg child in shock is prescribed a 20 mL/kg bolus of normal saline. What volume should be given?', '["240 mL", "60 mL", "120 mL", "180 mL"]'::jsonb, 2, 'Fluid bolus = 20 mL/kg × 6 kg = 120 mL of isotonic crystalloid, then reassess.'),
(5, 2, 'ICU Calculations', 'A 75 kg man with 35% TBSA burns arrives 1 hour after the injury and has had no IV fluid. Using the Parkland formula, at what rate should the first half of the fluid run?', '["750 mL/hr", "1,500 mL/hr", "656.2 mL/hr", "437.5 mL/hr"]'::jsonb, 0, 'Total = 4 × 75 × 35 = 10,500 mL; half (5,250 mL) is due within 8 hours of the BURN, not of arrival. The patient arrived 1 h after the burn, so 5,250 mL must run over the remaining 7 h = 750 mL/hr.'),
(5, 3, 'ICU Calculations', 'Amoxicillin suspension is available as 250 mg in 5 mL. The prescription is 500 mg. What volume should be given?', '["2 mL", "2.5 mL", "10 mL", "20 mL"]'::jsonb, 2, 'Volume = (dose wanted ÷ dose in stock) × stock volume = (500 ÷ 250) × 5 mL = 10 mL.'),
(5, 4, 'ICU Calculations', 'Using the 4-2-1 rule, what is the hourly maintenance fluid rate for a child weighing 32 kg?', '["82 mL/hr", "72 mL/hr", "128 mL/hr", "64 mL/hr"]'::jsonb, 1, 'Holliday–Segar (4-2-1 rule): 4 mL/kg/hr for the first 10 kg, 2 mL/kg/hr for the next 10 kg, 1 mL/kg/hr for each kg above 20. For 32 kg = 72 mL/hr.'),
(5, 5, 'ICU Calculations', 'An adult has burns to the whole left leg and the perineum. Using the Rule of Nines, what is the TBSA burned?', '["28%", "19%", "23.5%", "10%"]'::jsonb, 1, 'Rule of Nines (adult): the whole left leg 18% + the perineum 1% = 19%.'),
(5, 6, 'ICU Calculations', '1,000 mL of Ringer''s lactate is prescribed to run over 6 hours using a giving set with a drop factor of 10 drops/mL. What is the correct drip rate?', '["28 drops/min", "56 drops/min", "42 drops/min", "167 drops/min"]'::jsonb, 0, 'Drops/min = (volume × drop factor) ÷ time in minutes = (1,000 × 10) ÷ (6 × 60) = 10,000 ÷ 360 = 27.78 ≈ 28 drops/min.'),
(5, 7, 'ICU Calculations', 'A head-injured patient has BP 140/80 mmHg and ICP 30 mmHg. What is the cerebral perfusion pressure (CPP)?', '["110 mmHg", "70 mmHg", "50 mmHg", "130 mmHg"]'::jsonb, 1, 'MAP = (140 + 2 × 80) ÷ 3 ≈ 100 mmHg. CPP = MAP − ICP = 100 − 30 = 70 mmHg, which is adequate (target 60–70 mmHg).'),
(5, 8, 'ICU Calculations', 'A patient weighs 33 lb. A drug is prescribed at 5 mg/kg. What dose should be given?', '["165 mg", "150 mg", "75 mg", "34.1 mg"]'::jsonb, 2, 'Convert first: 33 lb ÷ 2.2 = 15 kg. Dose = 5 mg/kg × 15 kg = 75 mg. Using pounds would give a 2.2× overdose.'),
(5, 9, 'ICU Calculations', 'Cefuroxime 90 mg/kg/day is prescribed in divided doses every 6 hours for an infant weighing 15 kg. How much is each dose?', '["22.5 mg", "1,350 mg", "270 mg", "337.5 mg"]'::jsonb, 3, 'Daily dose = 90 mg/kg/day × 15 kg = 1,350 mg/day. Every 6 hours = 4 doses a day, so each dose = 1,350 ÷ 4 = 337.5 mg.'),
(5, 10, 'ICU Calculations', 'A patient does not open the eyes at all, uses inappropriate words and flexes abnormally to pain (decorticate). What is the Glasgow Coma Scale score?', '["8/15", "9/15", "7/15", "6/15"]'::jsonb, 2, 'Eyes 1 + Verbal 3 + Motor 3 = 7/15. A GCS of 8 or less usually means the airway needs protecting.'),
(5, 11, 'ICU Calculations', '1,000 mL of 5% dextrose is prescribed to run over 8 hours using a giving set with a drop factor of 10 drops/mL. What is the correct drip rate?', '["21 drops/min", "31 drops/min", "42 drops/min", "125 drops/min"]'::jsonb, 0, 'Drops/min = (volume × drop factor) ÷ time in minutes = (1,000 × 10) ÷ (8 × 60) = 10,000 ÷ 480 = 20.83 ≈ 21 drops/min.'),
(5, 12, 'ICU Calculations', '500 mL of normal saline is running at 150 mL/hr. How long will it take to finish?', '["18 h", "3 h 50 min", "3 h 20 min", "4 h 20 min"]'::jsonb, 2, 'Time = volume ÷ rate = 500 ÷ 150 = 3.33 h = 3 h 20 min.'),
(5, 13, 'ICU Calculations', '1,500 mL of 5% dextrose is prescribed to run over 10 hours using a giving set with a drop factor of 20 drops/mL. What is the correct drip rate?', '["150 drops/min", "50 drops/min", "38 drops/min", "100 drops/min"]'::jsonb, 1, 'Drops/min = (volume × drop factor) ÷ time in minutes = (1,500 × 20) ÷ (10 × 60) = 30,000 ÷ 600 = 50 ≈ 50 drops/min.'),
(5, 14, 'ICU Calculations', 'An adult has burns to the back of the trunk, the head and neck and the perineum. Using the Rule of Nines, what is the TBSA burned?', '["32.5%", "19%", "28%", "37%"]'::jsonb, 2, 'Rule of Nines (adult): the back of the trunk 18% + the head and neck 9% + the perineum 1% = 28%.'),
(5, 15, 'ICU Calculations', 'Heparin 20,000 units in 500 mL is ordered at 1,500 units/hour. What rate (mL/hr) should be set on the pump?', '["15 mL/hr", "37.5 mL/hr", "40 mL/hr", "75 mL/hr"]'::jsonb, 1, 'Concentration = 20,000 units ÷ 500 mL = 40 units/mL. Rate = 1500 ÷ 40 = 37.5 mL/hr.'),
(5, 16, 'ICU Calculations', 'Adrenaline (epinephrine) 4 mg is diluted to 250 mL and prescribed at 0.05 mcg/kg/min for a patient weighing 55 kg. At what rate (mL/hr) should the infusion pump be set?', '["10.3 mL/hr", "20.6 mL/hr", "1.9 mL/hr", "0.2 mL/hr"]'::jsonb, 0, 'Concentration = 4 mg ÷ 250 mL = 16 mcg/mL. Dose per hour = 0.05 mcg × 55 kg × 60 min = 165 mcg/hr. Rate = 165 ÷ 16 = 10.3 mL/hr. Common errors: forgetting × 60 (minutes to hours) or leaving out the weight.'),
(5, 17, 'ICU Calculations', 'Dopamine is ordered at 10 mcg/kg/min for a 60 kg patient. What is this dose expressed in mg/hr?', '["36 mg/hr", "60 mg/hr", "3.6 mg/hr", "6 mg/hr"]'::jsonb, 0, 'Dose = 10 mcg/kg/min x 60 kg = 600 mcg/min. Per hour = 600 x 60 = 36,000 mcg/hr = 36 mg/hr.'),
(5, 18, 'ICU Calculations', 'Metronidazole infusion is available as 500 mg in 100 mL. The prescription is 400 mg. What volume should be given?', '["125 mL", "80 mL", "0.8 mL", "160 mL"]'::jsonb, 1, 'Volume = (dose wanted ÷ dose in stock) × stock volume = (400 ÷ 500) × 100 mL = 80 mL.'),
(5, 19, 'ICU Calculations', '1,000 mL of Hartmann''s solution is prescribed to run over 8 hours using a giving set with a drop factor of 15 drops/mL. What is the correct drip rate?', '["42 drops/min", "125 drops/min", "31 drops/min", "62 drops/min"]'::jsonb, 2, 'Drops/min = (volume × drop factor) ÷ time in minutes = (1,000 × 15) ÷ (8 × 60) = 15,000 ÷ 480 = 31.25 ≈ 31 drops/min.'),
(5, 20, 'ICU Calculations', 'A patient''s blood pressure is 138/94 mmHg. What is the mean arterial pressure (MAP)?', '["123 mmHg", "44 mmHg", "109 mmHg", "116 mmHg"]'::jsonb, 2, 'MAP = (SBP + 2 × DBP) ÷ 3 = (138 + 2 × 94) ÷ 3 = 326 ÷ 3 ≈ 109 mmHg. A MAP of at least 65 mmHg is the usual target in shock.'),
(5, 21, 'ICU Calculations', '40 mmol of potassium chloride in 1000 mL normal saline is prescribed over 5 hours. What is the pump rate and how much potassium is given each hour?', '["200 mL/hr, giving 4 mmol K⁺ per hour", "200 mL/hr, giving 8 mmol K⁺ per hour", "400 mL/hr, giving 16 mmol K⁺ per hour", "3.3 mL/hr, giving 8 mmol K⁺ per hour"]'::jsonb, 1, 'Rate = 1000 mL ÷ 5 h = 200 mL/hr. Potassium per hour = 40 mmol ÷ 5 h = 8 mmol/hr (keep ≤ 10 mmol/hr peripherally, on a pump, with cardiac monitoring for faster rates).'),
(5, 22, 'ICU Calculations', 'Ibuprofen is prescribed at 10 mg/kg per dose (maximum single dose 400 mg) for a patient weighing 60 kg. What single dose should be given?', '["200 mg", "660 mg", "400 mg", "600 mg"]'::jsonb, 2, 'Dose = 10 mg/kg × 60 kg = 600 mg, which is above the 400 mg maximum, so give 400 mg.'),
(5, 23, 'ICU Calculations', '20 mmol of potassium chloride in 1000 mL normal saline is prescribed over 4 hours. What is the pump rate and how much potassium is given each hour?', '["250 mL/hr, giving 5 mmol K⁺ per hour", "4.2 mL/hr, giving 5 mmol K⁺ per hour", "500 mL/hr, giving 10 mmol K⁺ per hour", "250 mL/hr, giving 2 mmol K⁺ per hour"]'::jsonb, 0, 'Rate = 1000 mL ÷ 4 h = 250 mL/hr. Potassium per hour = 20 mmol ÷ 4 h = 5 mmol/hr (keep ≤ 10 mmol/hr peripherally, on a pump, with cardiac monitoring for faster rates).'),
(5, 24, 'ICU Calculations', 'A nurse is asked to prepare an infusion so that a patient weighing 90 kg receives dopamine at 3 mcg/kg/min. The available bag is 800 mg in 500 mL D5W. What is the required infusion rate in mL/hr?', '["10.1 mL/hr", "20.3 mL/hr", "8.4 mL/hr", "16.9 mL/hr"]'::jsonb, 0, 'Concentration = 800,000 mcg/500 mL = 1600 mcg/mL. Dose = 3 mcg/kg/min x 90 kg = 270 mcg/min. Rate = 270/1600 = 0.169 mL/min x 60 = 10.1 mL/hr.'),
(5, 25, 'ICU Calculations', 'Over 24 hours a patient received 2,400 mL IV fluid and 300 mL orally. Output was urine 2,200 mL, nasogastric aspirate 0 mL and wound drain 250 mL. What is the 24-hour fluid balance?', '["+5,150 mL", "+250 mL", "+500 mL", "-250 mL"]'::jsonb, 1, 'Input = IV 2,400 + oral 300 = 2,700 mL. Output = urine 2,200 + NG 0 + drain 250 = 2,450 mL. Balance = 2,700 − 2,450 = +250 mL.'),
(5, 26, 'ICU Calculations', 'Soluble insulin 50 units is made up to 50 mL with normal saline. The order is 8 units/hour. What rate should be set?', '["32 mL/hr", "16 mL/hr", "8 mL/hr", "4 mL/hr"]'::jsonb, 2, 'Concentration = 50 units ÷ 50 mL = 1 unit/mL. Rate = 8 ÷ 1 = 8 mL/hr.'),
(5, 27, 'ICU Calculations', 'Ceftazidime 60 mg/kg/day is prescribed in divided doses every 6 hours for an infant weighing 9 kg. How much is each dose?', '["540 mg", "135 mg", "15 mg", "108 mg"]'::jsonb, 1, 'Daily dose = 60 mg/kg/day × 9 kg = 540 mg/day. Every 6 hours = 4 doses a day, so each dose = 540 ÷ 4 = 135 mg.'),
(5, 28, 'ICU Calculations', 'A 65 kg man with 60% TBSA burns arrives 2 hours after the injury and has had no IV fluid. Using the Parkland formula, at what rate should the first half of the fluid run?', '["975 mL/hr", "1,300 mL/hr", "2,600 mL/hr", "650 mL/hr"]'::jsonb, 1, 'Total = 4 × 65 × 60 = 15,600 mL; half (7,800 mL) is due within 8 hours of the BURN, not of arrival. The patient arrived 2 h after the burn, so 7,800 mL must run over the remaining 6 h = 1,300 mL/hr.'),
(5, 29, 'ICU Calculations', '500 mL of normal saline is running at 50 mL/hr. How long will it take to finish?', '["11 h", "6 h", "10 h", "10 h 30 min"]'::jsonb, 2, 'Time = volume ÷ rate = 500 ÷ 50 = 10 h = 10 h.'),
(5, 30, 'ICU Calculations', 'How many grams of glucose are in 50 mL of 10% dextrose?', '["50 g", "2.5 g", "500 g", "5 g"]'::jsonb, 3, '10% means 10 g per 100 mL. 50 mL × 10/100 = 5 g of glucose.'),
(5, 31, 'ICU Calculations', 'An infusion is being given via a microdrip set, where the drop factor is 60 gtt/mL, at a pump-set rate of 45 mL/hr. If the pump failed and this had to be run by gravity, what would the drop rate be in gtt/min?', '["75 gtt/min", "45 gtt/min", "60 gtt/min", "15 gtt/min"]'::jsonb, 1, 'With a 60 gtt/mL microdrip set, mL/hr and gtt/min are numerically equal, so 45 mL/hr = 45 gtt/min.'),
(5, 32, 'ICU Calculations', 'Using the Parkland formula for a 65 kg patient with 35% TBSA burns, how much fluid should be given in the first 8 hours after the burn?', '["9,100 mL", "2,275 mL", "3,033.3 mL", "4,550 mL"]'::jsonb, 3, 'Total = 4 × 65 × 35 = 9,100 mL. Half is given in the first 8 hours from the time of the burn: 4,550 mL.'),
(5, 33, 'ICU Calculations', 'Dopamine 400 mg is diluted to 250 mL and prescribed at 3 mcg/kg/min for a patient weighing 60 kg. At what rate (mL/hr) should the infusion pump be set?', '["1.1 mL/hr", "13.5 mL/hr", "0.1 mL/hr", "6.8 mL/hr"]'::jsonb, 3, 'Concentration = 400 mg ÷ 250 mL = 1,600 mcg/mL. Dose per hour = 3 mcg × 60 kg × 60 min = 10,800 mcg/hr. Rate = 10,800 ÷ 1,600 = 6.8 mL/hr. Common errors: forgetting × 60 (minutes to hours) or leaving out the weight.'),
(5, 34, 'ICU Calculations', 'An adult has burns to the perineum, the whole left arm and the whole right leg. Using the Rule of Nines, what is the TBSA burned?', '["32.5%", "37%", "19%", "28%"]'::jsonb, 3, 'Rule of Nines (adult): the perineum 1% + the whole left arm 9% + the whole right leg 18% = 28%.'),
(5, 35, 'ICU Calculations', 'Over 24 hours a patient received 2,400 mL IV fluid and 300 mL orally. Output was urine 1,500 mL, nasogastric aspirate 400 mL and wound drain 0 mL. What is the 24-hour fluid balance?', '["-800 mL", "+1,200 mL", "+4,600 mL", "+800 mL"]'::jsonb, 3, 'Input = IV 2,400 + oral 300 = 2,700 mL. Output = urine 1,500 + NG 400 + drain 0 = 1,900 mL. Balance = 2,700 − 1,900 = +800 mL.'),
(5, 36, 'ICU Calculations', 'A 70 kg patient with 50% TBSA burns requires fluid resuscitation. The Parkland formula calculates the 24-hour fluid as:', '["14,000 mL", "3,500 mL", "28,000 mL", "7,000 mL"]'::jsonb, 0, 'Parkland formula: 4 mL \times kg \times %TBSA = 4 \times 70 \times 50 = 14,000 mL.'),
(5, 37, 'ICU Calculations', 'An 80 kg patient has passed 240 mL of urine in the last 3 hours. What is the urine output and how is it interpreted?', '["80 mL/kg/hr — adequate", "1 mL/kg/hr — oliguria", "3 mL/kg/hr — adequate", "1 mL/kg/hr — adequate"]'::jsonb, 3, 'Urine output = 240 mL ÷ 3 h ÷ 80 kg = 1 mL/kg/hr, which is adequate (≥ 0.5 mL/kg/hr).'),
(5, 38, 'ICU Calculations', 'Ampicillin 30 mg/kg/day is prescribed in divided doses every 6 hours for an infant weighing 9 kg. How much is each dose?', '["67.5 mg", "270 mg", "7.5 mg", "54 mg"]'::jsonb, 0, 'Daily dose = 30 mg/kg/day × 9 kg = 270 mg/day. Every 6 hours = 4 doses a day, so each dose = 270 ÷ 4 = 67.5 mg.'),
(5, 39, 'ICU Calculations', 'Aminophylline is ordered as a loading dose of 5 mg/kg over 30 minutes for a 60 kg patient, supplied as 250 mg in 100 mL. What volume should be given, and at what rate over the 30 minutes?', '["60 mL total, at a rate of 120 mL/hr", "300 mL total, at a rate of 600 mL/hr", "120 mL total, at a rate of 240 mL/hr", "120 mL total, at a rate of 60 mL/hr"]'::jsonb, 2, 'Total dose = 5 mg/kg x 60 kg = 300 mg. Volume = 300 mg / 250 mg x 100 mL = 120 mL. To give over 30 min (0.5 hr): rate = 120/0.5 = 240 mL/hr.'),
(5, 40, 'ICU Calculations', 'An adult has burns to the whole left leg, the whole right arm, the front of the trunk (chest and abdomen) and the perineum. Using the Rule of Nines, what is the TBSA burned?', '["46%", "37%", "55%", "50.5%"]'::jsonb, 0, 'Rule of Nines (adult): the whole left leg 18% + the whole right arm 9% + the front of the trunk (chest and abdomen) 18% + the perineum 1% = 46%.'),
(5, 41, 'ICU Calculations', 'Dobutamine 250 mg is diluted to 250 mL and prescribed at 2.5 mcg/kg/min for a patient weighing 60 kg. At what rate (mL/hr) should the infusion pump be set?', '["1.5 mL/hr", "0.1 mL/hr", "9 mL/hr", "18 mL/hr"]'::jsonb, 2, 'Concentration = 250 mg ÷ 250 mL = 1,000 mcg/mL. Dose per hour = 2.5 mcg × 60 kg × 60 min = 9,000 mcg/hr. Rate = 9,000 ÷ 1,000 = 9 mL/hr. Common errors: forgetting × 60 (minutes to hours) or leaving out the weight.'),
(5, 42, 'ICU Calculations', 'Glyceryl trinitrate (GTN) 50 mg in 500 mL is ordered at 8 mcg/min. What pump rate (mL/hr) will deliver this dose?', '["0.1 mL/hr", "2.4 mL/hr", "4.8 mL/hr", "9.6 mL/hr"]'::jsonb, 2, 'Concentration = 50 mg in 500 mL = 100 mcg/mL. 8 mcg/min × 60 = 480 mcg/hr. 480 ÷ 100 = 4.8 mL/hr.'),
(5, 43, 'ICU Calculations', '750 mL of normal saline is running at 125 mL/hr. How long will it take to finish?', '["6 h", "10 h", "6 h 30 min", "7 h"]'::jsonb, 0, 'Time = volume ÷ rate = 750 ÷ 125 = 6 h = 6 h.'),
(5, 44, 'ICU Calculations', 'Propofol (10 mg/mL) is ordered at 30 mcg/kg/min for an 80 kg patient. What infusion rate in mL/hr should be programmed?', '["24 mL/hr", "7.2 mL/hr", "28.8 mL/hr", "14.4 mL/hr"]'::jsonb, 3, 'Dose = 30 mcg/kg/min x 80 kg = 2400 mcg/min = 2.4 mg/min = 144 mg/hr. Rate = 144 mg/hr / 10 mg/mL = 14.4 mL/hr.'),
(5, 45, 'ICU Calculations', 'A 50 kg man with 40% TBSA burns arrives 4 hours after the injury and has had no IV fluid. Using the Parkland formula, at what rate should the first half of the fluid run?', '["333.3 mL/hr", "1,000 mL/hr", "500 mL/hr", "2,000 mL/hr"]'::jsonb, 1, 'Total = 4 × 50 × 40 = 8,000 mL; half (4,000 mL) is due within 8 hours of the BURN, not of arrival. The patient arrived 4 h after the burn, so 4,000 mL must run over the remaining 4 h = 1,000 mL/hr.'),
(5, 46, 'ICU Calculations', 'A 50 kg patient has passed 200 mL of urine in the last 3 hours. What is the urine output and how is it interpreted?', '["1.33 mL/kg/hr — adequate", "4 mL/kg/hr — adequate", "1.33 mL/kg/hr — oliguria", "66.7 mL/kg/hr — adequate"]'::jsonb, 0, 'Urine output = 200 mL ÷ 3 h ÷ 50 kg = 1.33 mL/kg/hr, which is adequate (≥ 0.5 mL/kg/hr).'),
(5, 47, 'ICU Calculations', 'A 60 kg man with 20% TBSA burns arrives 1 hour after the injury and has had no IV fluid. Using the Parkland formula, at what rate should the first half of the fluid run?', '["342.9 mL/hr", "685.7 mL/hr", "300 mL/hr", "200 mL/hr"]'::jsonb, 0, 'Total = 4 × 60 × 20 = 4,800 mL; half (2,400 mL) is due within 8 hours of the BURN, not of arrival. The patient arrived 1 h after the burn, so 2,400 mL must run over the remaining 7 h = 342.9 mL/hr.'),
(5, 48, 'ICU Calculations', 'Hydrocortisone (reconstituted) is available as 100 mg in 2 mL. The prescription is 50 mg. What volume should be given?', '["0.5 mL", "2 mL", "4 mL", "1 mL"]'::jsonb, 3, 'Volume = (dose wanted ÷ dose in stock) × stock volume = (50 ÷ 100) × 2 mL = 1 mL.'),
(5, 49, 'ICU Calculations', 'Dobutamine is mixed as 250 mg in 250 mL D5W and prescribed at 5 mcg/kg/min for an 80 kg patient. What infusion rate in mL/hr should be set?', '["24 mL/hr", "12 mL/hr", "48 mL/hr", "20 mL/hr"]'::jsonb, 0, 'Concentration = 250,000 mcg/250 mL = 1000 mcg/mL (1 mg/mL). Dose = 5 mcg/kg/min x 80 kg = 400 mcg/min. Rate = 400/1000 = 0.4 mL/min x 60 = 24 mL/hr.'),
(5, 50, 'ICU Calculations', 'Noradrenaline 8 mg in 250 mL is ordered at 5 mcg/min. What pump rate (mL/hr) will deliver this dose?', '["0.2 mL/hr", "4.7 mL/hr", "9.4 mL/hr", "18.8 mL/hr"]'::jsonb, 2, 'Concentration = 8 mg in 250 mL = 32 mcg/mL. 5 mcg/min × 60 = 300 mcg/hr. 300 ÷ 32 = 9.4 mL/hr.'),
(5, 51, 'ICU Calculations', 'Digoxin loading (digitalizing) dose is calculated as 10 mcg/kg for a 68 kg patient, with 50% given as the first dose and the remainder split into two further doses. What is the total loading dose, and what is the first dose given?', '["Total 340 mcg; first dose 170 mcg", "Total 680 mcg; first dose 680 mcg", "Total 680 mcg; first dose 340 mcg", "Total 680 mcg; first dose 170 mcg"]'::jsonb, 2, 'Total loading dose = 10 mcg/kg x 68 kg = 680 mcg. The first dose (50%) = 340 mcg, with the remaining 340 mcg split into two doses of 170 mcg each.'),
(5, 52, 'ICU Calculations', 'Ceftriaxone (reconstituted) is available as 1,000 mg in 10 mL. The prescription is 250 mg. What volume should be given?', '["0.2 mL", "2.5 mL", "5 mL", "40 mL"]'::jsonb, 1, 'Volume = (dose wanted ÷ dose in stock) × stock volume = (250 ÷ 1,000) × 10 mL = 2.5 mL.'),
(5, 53, 'ICU Calculations', 'A 12 kg child in shock is prescribed a 20 mL/kg bolus of normal saline. What volume should be given?', '["360 mL", "480 mL", "240 mL", "120 mL"]'::jsonb, 2, 'Fluid bolus = 20 mL/kg × 12 kg = 240 mL of isotonic crystalloid, then reassess.'),
(5, 54, 'ICU Calculations', 'An oxygen cylinder contains 1,360 litres of oxygen. The patient needs 5 L/min during transfer. Approximately how long will it last?', '["About 272 minutes", "About 113 minutes", "About 45 minutes", "About 544 minutes"]'::jsonb, 0, 'Duration = cylinder content ÷ flow = 1,360 L ÷ 5 L/min = 272 minutes (≈ 4.5 h). Always keep a reserve and check the gauge.'),
(5, 55, 'ICU Calculations', 'A head-injured patient has BP 100/55 mmHg and ICP 10 mmHg. What is the cerebral perfusion pressure (CPP)?', '["60 mmHg", "90 mmHg", "80 mmHg", "45 mmHg"]'::jsonb, 0, 'MAP = (100 + 2 × 55) ÷ 3 ≈ 70 mmHg. CPP = MAP − ICP = 70 − 10 = 60 mmHg, which is adequate (target 60–70 mmHg).'),
(5, 56, 'ICU Calculations', 'Soluble insulin 100 units is made up to 100 mL with normal saline. The order is 6 units/hour. What rate should be set?', '["12 mL/hr", "3 mL/hr", "6 mL/hr", "24 mL/hr"]'::jsonb, 2, 'Concentration = 100 units ÷ 100 mL = 1 unit/mL. Rate = 6 ÷ 1 = 6 mL/hr.'),
(5, 57, 'ICU Calculations', 'What is the 24-hour maintenance fluid requirement for a child weighing 28 kg (Holliday–Segar method)?', '["2,800 mL", "1,400 mL", "1,860 mL", "1,660 mL"]'::jsonb, 3, 'Holliday–Segar: 100 mL/kg/day for the first 10 kg, 50 mL/kg/day for the next 10 kg, 20 mL/kg/day for each kg above 20. For 28 kg = 1,660 mL/day.'),
(5, 58, 'ICU Calculations', 'A patient''s blood pressure is 176/56 mmHg. What is the mean arterial pressure (MAP)?', '["136 mmHg", "96 mmHg", "116 mmHg", "120 mmHg"]'::jsonb, 1, 'MAP = (SBP + 2 × DBP) ÷ 3 = (176 + 2 × 56) ÷ 3 = 288 ÷ 3 ≈ 96 mmHg. A MAP of at least 65 mmHg is the usual target in shock.'),
(5, 59, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient on high-dose furosemide with a low potassium pH 7.50, PaCO2 54 mmHg, HCO3⁻ 38 mmol/L. What is the correct interpretation?', '["Uncompensated metabolic acidosis", "Mixed respiratory and metabolic acidosis", "Uncompensated metabolic alkalosis", "Partially compensated metabolic alkalosis"]'::jsonb, 3, 'Step 1: pH 7.50 shows alkalaemia (pH > 7.45). Step 2: PaCO2 54 mmHg is high (> 45). Step 3: HCO3⁻ 38 mmol/L is high (> 26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives partially compensated metabolic alkalosis. The other system is moving in the compensating direction but the pH is still abnormal, so compensation is partial.'),
(5, 60, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient who has been at high altitude for several days pH 7.48, PaCO2 26 mmHg, HCO3⁻ 17 mmol/L. What is the correct interpretation?', '["Fully compensated respiratory acidosis", "Uncompensated metabolic alkalosis", "Partially compensated respiratory alkalosis", "Uncompensated respiratory alkalosis"]'::jsonb, 2, 'Step 1: pH 7.48 shows alkalaemia (pH > 7.45). Step 2: PaCO2 26 mmHg is low (< 35). Step 3: HCO3⁻ 17 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives partially compensated respiratory alkalosis. The other system is moving in the compensating direction but the pH is still abnormal, so compensation is partial.'),
(5, 61, 'Acid–Base Balance & ABG', 'Which acid–base disturbance is most likely to result from the following? Over-ventilation on a mechanical ventilator.', '["Respiratory acidosis", "Metabolic acidosis", "Metabolic alkalosis", "Respiratory alkalosis"]'::jsonb, 3, 'Over-ventilation on a mechanical ventilator: respiratory alkalosis. Excess minute ventilation removes too much CO2.'),
(5, 62, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with septic shock who is now exhausted and hypoventilating pH 7.10, PaCO2 56 mmHg, HCO3⁻ 14 mmol/L. What is the correct interpretation?', '["Partially compensated metabolic acidosis", "Uncompensated respiratory alkalosis", "Mixed respiratory and metabolic acidosis", "Uncompensated metabolic alkalosis"]'::jsonb, 2, 'Step 1: pH 7.10 shows acidaemia (pH < 7.35). Step 2: PaCO2 56 mmHg is high (> 45). Step 3: HCO3⁻ 14 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives mixed respiratory and metabolic acidosis. Both PaCO2 (high) and HCO3⁻ (low) push the pH down together, so it is a mixed acidosis, not compensation.'),
(5, 63, 'Acid–Base Balance & ABG', 'Which condition can cause a high anion gap metabolic acidosis?', '["Hyperchloremic acidosis", "Renal tubular acidosis", "Lactic acidosis", "Vomiting"]'::jsonb, 2, 'Lactic acid is an unmeasured anion, so lactic acidosis widens the anion gap. Hyperchloraemic and renal tubular acidosis have a normal gap; vomiting causes alkalosis.'),
(5, 64, 'Acid–Base Balance & ABG', 'A patient''s arterial blood gas shows a metabolic acidosis with a raised anion gap in the setting of acute kidney injury. This is best explained by:', '["No relationship between AKI and acid-base status", "Loss of bicarbonate through the kidneys alone with no other cause", "Excess bicarbonate production", "Accumulation of unmeasured acids (e.g. sulfates, phosphates) that the failing kidneys cannot excrete"]'::jsonb, 3, 'AKI classically causes a high anion gap metabolic acidosis due to retention of unmeasured acid anions that the kidneys would normally excrete.'),
(5, 65, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient on continuous nasogastric suction for 3 days pH 7.53, PaCO2 37 mmHg, HCO3⁻ 38 mmol/L. What is the correct interpretation?', '["Uncompensated metabolic alkalosis", "Fully compensated metabolic acidosis", "Partially compensated metabolic alkalosis", "Partially compensated metabolic acidosis"]'::jsonb, 0, 'Step 1: pH 7.53 shows alkalaemia (pH > 7.45). Step 2: PaCO2 37 mmHg is normal (35–45). Step 3: HCO3⁻ 38 mmol/L is high (> 26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated metabolic alkalosis. The other value is still normal, so there is no compensation yet.'),
(5, 66, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with acute severe asthma who is now tiring with a quiet chest pH 7.31, PaCO2 65 mmHg, HCO3⁻ 26 mmol/L. What is the correct interpretation?', '["Uncompensated metabolic alkalosis", "Partially compensated respiratory acidosis", "Uncompensated respiratory acidosis", "Partially compensated metabolic acidosis"]'::jsonb, 2, 'Step 1: pH 7.31 shows acidaemia (pH < 7.35). Step 2: PaCO2 65 mmHg is high (> 45). Step 3: HCO3⁻ 26 mmol/L is normal (22–26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated respiratory acidosis. The other value is still normal, so there is no compensation yet.'),
(5, 67, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient admitted minutes ago after a prolonged seizure pH 7.26, PaCO2 40 mmHg, HCO3⁻ 18 mmol/L. What is the correct interpretation?', '["Fully compensated respiratory acidosis", "Uncompensated respiratory acidosis", "Fully compensated metabolic acidosis", "Uncompensated metabolic acidosis"]'::jsonb, 3, 'Step 1: pH 7.26 shows acidaemia (pH < 7.35). Step 2: PaCO2 40 mmHg is normal (35–45). Step 3: HCO3⁻ 18 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated metabolic acidosis. The other value is still normal, so there is no compensation yet.'),
(5, 68, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient admitted minutes ago after a prolonged seizure pH 7.24, PaCO2 41 mmHg, HCO3⁻ 13 mmol/L. What is the correct interpretation?', '["Uncompensated metabolic acidosis", "Fully compensated metabolic acidosis", "Partially compensated metabolic alkalosis", "Fully compensated respiratory acidosis"]'::jsonb, 0, 'Step 1: pH 7.24 shows acidaemia (pH < 7.35). Step 2: PaCO2 41 mmHg is normal (35–45). Step 3: HCO3⁻ 13 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated metabolic acidosis. The other value is still normal, so there is no compensation yet.'),
(5, 69, 'Acid–Base Balance & ABG', 'A patient with metabolic acidosis has HCO3⁻ 10 mmol/L and PaCO2 31 mmHg. Using Winter''s formula, what does this show?', '["Appropriate respiratory compensation — a pure metabolic acidosis", "PaCO2 is lower than expected — an added respiratory alkalosis", "The kidneys are compensating for a respiratory acidosis", "PaCO2 is higher than expected — an added respiratory acidosis"]'::jsonb, 3, 'Winter''s formula: expected PaCO2 = (1.5 × HCO3⁻) + 8 ± 2 = (1.5 × 10) + 8 = 23 (range 21–25). The measured PaCO2 is 31, so: paCO2 is higher than expected — an added respiratory acidosis.'),
(5, 70, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with septic shock who is now exhausted and hypoventilating pH 7.07, PaCO2 68 mmHg, HCO3⁻ 14 mmol/L. What is the correct interpretation?', '["Partially compensated metabolic alkalosis", "Uncompensated respiratory acidosis", "Uncompensated metabolic acidosis", "Mixed respiratory and metabolic acidosis"]'::jsonb, 3, 'Step 1: pH 7.07 shows acidaemia (pH < 7.35). Step 2: PaCO2 68 mmHg is high (> 45). Step 3: HCO3⁻ 14 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives mixed respiratory and metabolic acidosis. Both PaCO2 (high) and HCO3⁻ (low) push the pH down together, so it is a mixed acidosis, not compensation.'),
(5, 71, 'Acid–Base Balance & ABG', 'For a patient with an acute COPD exacerbation presenting with respiratory acidosis (pH 7.30, PaCO2 60 mmHg) but still conscious and able to protect the airway, which intervention is generally tried before invasive intubation?', '["High-dose intravenous sedation to reduce work of breathing", "Non-invasive positive pressure ventilation (e.g., BiPAP)", "Immediate elective tracheostomy", "Therapeutic bronchoalveolar lavage"]'::jsonb, 1, 'Non-invasive ventilation (BiPAP) reduces work of breathing and improves gas exchange in COPD exacerbations with respiratory acidosis in an alert, cooperative patient, and can prevent the need for invasive intubation.'),
(5, 72, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with liver cirrhosis who has been tachypnoeic for days pH 7.47, PaCO2 29 mmHg, HCO3⁻ 19 mmol/L. What is the correct interpretation?', '["Uncompensated respiratory alkalosis", "Partially compensated respiratory alkalosis", "Mixed respiratory and metabolic acidosis", "Partially compensated metabolic acidosis"]'::jsonb, 1, 'Step 1: pH 7.47 shows alkalaemia (pH > 7.45). Step 2: PaCO2 29 mmHg is low (< 35). Step 3: HCO3⁻ 19 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives partially compensated respiratory alkalosis. The other system is moving in the compensating direction but the pH is still abnormal, so compensation is partial.'),
(5, 73, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with chronic kidney disease on the renal ward pH 7.36, PaCO2 27 mmHg, HCO3⁻ 16 mmol/L. What is the correct interpretation?', '["Fully compensated metabolic acidosis", "Partially compensated respiratory acidosis", "Uncompensated respiratory acidosis", "Partially compensated metabolic acidosis"]'::jsonb, 0, 'Step 1: pH 7.36 shows a pH within the normal range (7.35–7.45). Step 2: PaCO2 27 mmHg is low (< 35). Step 3: HCO3⁻ 16 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives fully compensated metabolic acidosis. Both values are abnormal but the pH is back within range, so compensation is full.'),
(5, 74, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient who has been vomiting for a week pH 7.46, PaCO2 53 mmHg, HCO3⁻ 38 mmol/L. What is the correct interpretation?', '["Uncompensated respiratory acidosis", "Uncompensated metabolic alkalosis", "Uncompensated respiratory alkalosis", "Partially compensated metabolic alkalosis"]'::jsonb, 3, 'Step 1: pH 7.46 shows alkalaemia (pH > 7.45). Step 2: PaCO2 53 mmHg is high (> 45). Step 3: HCO3⁻ 38 mmol/L is high (> 26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives partially compensated metabolic alkalosis. The other system is moving in the compensating direction but the pH is still abnormal, so compensation is partial.'),
(5, 75, 'Acid–Base Balance & ABG', 'Renal compensation for chronic respiratory alkalosis involves:', '["Increased hydrogen ion secretion", "Increased ammoniagenesis", "Increased bicarbonate reabsorption", "Decreased renal bicarbonate reabsorption, increasing bicarbonate excretion to lower serum bicarbonate"]'::jsonb, 3, 'In chronic respiratory alkalosis, the kidney reduces bicarbonate reabsorption, allowing more bicarbonate to be excreted and lowering plasma bicarbonate toward normal.'),
(5, 76, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with septic shock who is now exhausted and hypoventilating pH 7.09, PaCO2 64 mmHg, HCO3⁻ 18 mmol/L. What is the correct interpretation?', '["Uncompensated respiratory alkalosis", "Mixed respiratory and metabolic acidosis", "Partially compensated metabolic acidosis", "Partially compensated respiratory acidosis"]'::jsonb, 1, 'Step 1: pH 7.09 shows acidaemia (pH < 7.35). Step 2: PaCO2 64 mmHg is high (> 45). Step 3: HCO3⁻ 18 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives mixed respiratory and metabolic acidosis. Both PaCO2 (high) and HCO3⁻ (low) push the pH down together, so it is a mixed acidosis, not compensation.'),
(5, 77, 'Acid–Base Balance & ABG', 'A patient with metabolic acidosis has HCO3⁻ 10 mmol/L and PaCO2 15 mmHg. Using Winter''s formula, what does this show?', '["Appropriate respiratory compensation — a pure metabolic acidosis", "PaCO2 is higher than expected — an added respiratory acidosis", "PaCO2 is lower than expected — an added respiratory alkalosis", "The kidneys are compensating for a respiratory acidosis"]'::jsonb, 2, 'Winter''s formula: expected PaCO2 = (1.5 × HCO3⁻) + 8 ± 2 = (1.5 × 10) + 8 = 23 (range 21–25). The measured PaCO2 is 15, so: paCO2 is lower than expected — an added respiratory alkalosis.'),
(5, 78, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with chronic kidney disease on the renal ward pH 7.36, PaCO2 26 mmHg, HCO3⁻ 18 mmol/L. What is the correct interpretation?', '["Fully compensated respiratory acidosis", "Partially compensated respiratory acidosis", "Fully compensated metabolic acidosis", "Mixed respiratory and metabolic acidosis"]'::jsonb, 2, 'Step 1: pH 7.36 shows a pH within the normal range (7.35–7.45). Step 2: PaCO2 26 mmHg is low (< 35). Step 3: HCO3⁻ 18 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives fully compensated metabolic acidosis. Both values are abnormal but the pH is back within range, so compensation is full.'),
(5, 79, 'Acid–Base Balance & ABG', 'Type II (hypercapnic) respiratory failure, defined by PaCO2 above about 45-50 mmHg with acidaemia, is most typically caused by:', '["Alveolar hypoventilation, such as in COPD, neuromuscular disease, or CNS depression", "Isolated diffusion impairment from pulmonary fibrosis alone", "A pure right-to-left cardiac shunt", "High-altitude exposure alone"]'::jsonb, 0, 'Type II respiratory failure results from inadequate alveolar ventilation, seen in conditions that reduce the drive to breathe (CNS depression), impair respiratory muscle function (neuromuscular disease), or increase airway obstruction/dead space (COPD).'),
(5, 80, 'Acid–Base Balance & ABG', 'A patient with metabolic acidosis has HCO3⁻ 18 mmol/L and PaCO2 43 mmHg. Using Winter''s formula, what does this show?', '["Appropriate respiratory compensation — a pure metabolic acidosis", "PaCO2 is lower than expected — an added respiratory alkalosis", "The kidneys are compensating for a respiratory acidosis", "PaCO2 is higher than expected — an added respiratory acidosis"]'::jsonb, 3, 'Winter''s formula: expected PaCO2 = (1.5 × HCO3⁻) + 8 ± 2 = (1.5 × 18) + 8 = 35 (range 33–37). The measured PaCO2 is 43, so: paCO2 is higher than expected — an added respiratory acidosis.'),
(5, 81, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with severe diarrhoea who has just arrived pH 7.22, PaCO2 43 mmHg, HCO3⁻ 15 mmol/L. What is the correct interpretation?', '["Fully compensated metabolic acidosis", "Uncompensated metabolic acidosis", "Uncompensated metabolic alkalosis", "Fully compensated respiratory acidosis"]'::jsonb, 1, 'Step 1: pH 7.22 shows acidaemia (pH < 7.35). Step 2: PaCO2 43 mmHg is normal (35–45). Step 3: HCO3⁻ 15 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated metabolic acidosis. The other value is still normal, so there is no compensation yet.'),
(5, 82, 'Acid–Base Balance & ABG', 'Results: Na⁺ 130, Cl⁻ 97, HCO3⁻ 14 mmol/L. What is the anion gap and its interpretation?', '["33 mmol/L — raised (high anion gap)", "19 mmol/L — normal", "47 mmol/L — raised (high anion gap)", "19 mmol/L — raised (high anion gap)"]'::jsonb, 3, 'Anion gap = Na⁺ − (Cl⁻ + HCO3⁻) = 130 − (97 + 14) = 19 mmol/L (normal about 8–12). A raised gap suggests MUDPILES causes such as lactic acidosis, ketoacidosis, renal failure or poisoning.'),
(5, 83, 'Acid–Base Balance & ABG', 'A patient with metabolic acidosis has HCO3⁻ 16 mmol/L and PaCO2 24 mmHg. Using Winter''s formula, what does this show?', '["PaCO2 is higher than expected — an added respiratory acidosis", "PaCO2 is lower than expected — an added respiratory alkalosis", "The kidneys are compensating for a respiratory acidosis", "Appropriate respiratory compensation — a pure metabolic acidosis"]'::jsonb, 1, 'Winter''s formula: expected PaCO2 = (1.5 × HCO3⁻) + 8 ± 2 = (1.5 × 16) + 8 = 32 (range 30–34). The measured PaCO2 is 24, so: paCO2 is lower than expected — an added respiratory alkalosis.'),
(5, 84, 'Acid–Base Balance & ABG', 'Arterial blood gas for a ventilated patient whose set rate is too high pH 7.57, PaCO2 30 mmHg, HCO3⁻ 25 mmol/L. What is the correct interpretation?', '["Uncompensated metabolic alkalosis", "Uncompensated respiratory alkalosis", "Fully compensated metabolic acidosis", "Partially compensated respiratory alkalosis"]'::jsonb, 1, 'Step 1: pH 7.57 shows alkalaemia (pH > 7.45). Step 2: PaCO2 30 mmHg is low (< 35). Step 3: HCO3⁻ 25 mmol/L is normal (22–26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated respiratory alkalosis. The other value is still normal, so there is no compensation yet.'),
(5, 85, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with chronic kidney disease on the renal ward pH 7.36, PaCO2 26 mmHg, HCO3⁻ 15 mmol/L. What is the correct interpretation?', '["Fully compensated metabolic acidosis", "Partially compensated metabolic alkalosis", "Uncompensated metabolic alkalosis", "Partially compensated metabolic acidosis"]'::jsonb, 0, 'Step 1: pH 7.36 shows a pH within the normal range (7.35–7.45). Step 2: PaCO2 26 mmHg is low (< 35). Step 3: HCO3⁻ 15 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives fully compensated metabolic acidosis. Both values are abnormal but the pH is back within range, so compensation is full.'),
(5, 86, 'Acid–Base Balance & ABG', 'Which acid–base disturbance is most likely to result from the following? Prolonged vomiting with loss of gastric acid.', '["Respiratory acidosis", "Respiratory alkalosis", "Metabolic acidosis", "Metabolic alkalosis"]'::jsonb, 3, 'Prolonged vomiting with loss of gastric acid: metabolic alkalosis. Loss of HCl from the stomach raises plasma bicarbonate.'),
(5, 87, 'Acid–Base Balance & ABG', 'When titrating CRRT replacement fluid and dialysate flow rates for a patient with severe metabolic acidosis, the priority nursing consideration is:', '["Using a bicarbonate- or lactate-buffered replacement fluid to help correct the acidosis gradually", "Rapidly correcting the entire acid-base deficit within the first hour", "Using only solutions with no buffer", "Avoiding any buffer to prevent alkalosis"]'::jsonb, 0, 'Bicarbonate- or lactate-buffered CRRT replacement/dialysate fluids help gradually correct metabolic acidosis as part of therapy; correction should occur gradually, and lactate-buffered solutions require adequate hepatic function to be metabolized.'),
(5, 88, 'Acid–Base Balance & ABG', 'A patient in acute respiratory failure has ABG results: pH 7.28, PaCO2 60 mmHg, HCO3 26 mEq/L, PaO2 55 mmHg. This is best interpreted as:', '["Fully compensated respiratory acidosis", "Compensated metabolic alkalosis", "Acute metabolic acidosis", "Acute (uncompensated) respiratory acidosis with hypoxemia"]'::jsonb, 3, 'A low pH with elevated PaCO2 and a near-normal HCO3 indicates an acute respiratory acidosis without significant renal compensation yet, alongside hypoxemia, consistent with acute Type II respiratory failure.'),
(5, 89, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with chronic kyphoscoliosis who feels well pH 7.37, PaCO2 65 mmHg, HCO3⁻ 35 mmol/L. What is the correct interpretation?', '["Fully compensated respiratory acidosis", "Uncompensated respiratory alkalosis", "Partially compensated metabolic alkalosis", "Uncompensated respiratory acidosis"]'::jsonb, 0, 'Step 1: pH 7.37 shows a pH within the normal range (7.35–7.45). Step 2: PaCO2 65 mmHg is high (> 45). Step 3: HCO3⁻ 35 mmol/L is high (> 26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives fully compensated respiratory acidosis. Both values are abnormal but the pH is back within range, so compensation is full.'),
(5, 90, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with septic shock and a lactate of 6 mmol/L pH 7.19, PaCO2 26 mmHg, HCO3⁻ 10 mmol/L. What is the correct interpretation?', '["Fully compensated metabolic acidosis", "Uncompensated respiratory alkalosis", "Uncompensated respiratory acidosis", "Partially compensated metabolic acidosis"]'::jsonb, 3, 'Step 1: pH 7.19 shows acidaemia (pH < 7.35). Step 2: PaCO2 26 mmHg is low (< 35). Step 3: HCO3⁻ 10 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives partially compensated metabolic acidosis. The other system is moving in the compensating direction but the pH is still abnormal, so compensation is partial.'),
(5, 91, 'Acid–Base Balance & ABG', 'Results: Na⁺ 130, Cl⁻ 107, HCO3⁻ 12 mmol/L. What is the anion gap and its interpretation?', '["35 mmol/L — raised (high anion gap)", "11 mmol/L — raised (high anion gap)", "23 mmol/L — raised (high anion gap)", "11 mmol/L — normal"]'::jsonb, 3, 'Anion gap = Na⁺ − (Cl⁻ + HCO3⁻) = 130 − (107 + 12) = 11 mmol/L (normal about 8–12). A normal-gap acidosis suggests bicarbonate loss (diarrhoea) or saline excess.'),
(5, 92, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with septic shock who is now exhausted and hypoventilating pH 7.16, PaCO2 62 mmHg, HCO3⁻ 19 mmol/L. What is the correct interpretation?', '["Mixed respiratory and metabolic acidosis", "Fully compensated respiratory acidosis", "Uncompensated respiratory acidosis", "Partially compensated metabolic acidosis"]'::jsonb, 0, 'Step 1: pH 7.16 shows acidaemia (pH < 7.35). Step 2: PaCO2 62 mmHg is high (> 45). Step 3: HCO3⁻ 19 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives mixed respiratory and metabolic acidosis. Both PaCO2 (high) and HCO3⁻ (low) push the pH down together, so it is a mixed acidosis, not compensation.'),
(5, 93, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient on high-dose furosemide with a low potassium pH 7.51, PaCO2 53 mmHg, HCO3⁻ 39 mmol/L. What is the correct interpretation?', '["Fully compensated respiratory acidosis", "Uncompensated metabolic acidosis", "Uncompensated metabolic alkalosis", "Partially compensated metabolic alkalosis"]'::jsonb, 3, 'Step 1: pH 7.51 shows alkalaemia (pH > 7.45). Step 2: PaCO2 53 mmHg is high (> 45). Step 3: HCO3⁻ 39 mmol/L is high (> 26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives partially compensated metabolic alkalosis. The other system is moving in the compensating direction but the pH is still abnormal, so compensation is partial.'),
(5, 94, 'Acid–Base Balance & ABG', 'Results: Na⁺ 143, Cl⁻ 95, HCO3⁻ 24 mmol/L. What is the anion gap and its interpretation?', '["48 mmol/L — raised (high anion gap)", "24 mmol/L — normal", "72 mmol/L — raised (high anion gap)", "24 mmol/L — raised (high anion gap)"]'::jsonb, 3, 'Anion gap = Na⁺ − (Cl⁻ + HCO3⁻) = 143 − (95 + 24) = 24 mmol/L (normal about 8–12). A raised gap suggests MUDPILES causes such as lactic acidosis, ketoacidosis, renal failure or poisoning.'),
(5, 95, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with chronic kidney disease on the renal ward pH 7.36, PaCO2 26 mmHg, HCO3⁻ 14 mmol/L. What is the correct interpretation?', '["Partially compensated respiratory alkalosis", "Fully compensated metabolic acidosis", "Partially compensated respiratory acidosis", "Partially compensated metabolic acidosis"]'::jsonb, 1, 'Step 1: pH 7.36 shows a pH within the normal range (7.35–7.45). Step 2: PaCO2 26 mmHg is low (< 35). Step 3: HCO3⁻ 14 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives fully compensated metabolic acidosis. Both values are abnormal but the pH is back within range, so compensation is full.'),
(5, 96, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with chronic kyphoscoliosis who feels well pH 7.38, PaCO2 62 mmHg, HCO3⁻ 34 mmol/L. What is the correct interpretation?', '["Fully compensated respiratory acidosis", "Fully compensated metabolic acidosis", "Partially compensated respiratory acidosis", "Uncompensated metabolic alkalosis"]'::jsonb, 0, 'Step 1: pH 7.38 shows a pH within the normal range (7.35–7.45). Step 2: PaCO2 62 mmHg is high (> 45). Step 3: HCO3⁻ 34 mmol/L is high (> 26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives fully compensated respiratory acidosis. Both values are abnormal but the pH is back within range, so compensation is full.'),
(5, 97, 'Acid–Base Balance & ABG', 'Which ABG indicates uncompensated respiratory alkalosis?', '["pH 7.50, PaCO2 50 mmHg, HCO3- 30 mEq/L", "pH 7.30, PaCO2 50 mmHg, HCO3- 26 mEq/L", "pH 7.40, PaCO2 30 mmHg, HCO3- 18 mEq/L", "pH 7.50, PaCO2 30 mmHg, HCO3- 24 mEq/L"]'::jsonb, 3, 'Uncompensated respiratory alkalosis: high pH (7.50), low PaCO2 (30) and a normal HCO3⁻ (24), so the kidneys have not yet compensated.'),
(5, 98, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient on continuous nasogastric suction for 3 days pH 7.48, PaCO2 40 mmHg, HCO3⁻ 33 mmol/L. What is the correct interpretation?', '["Partially compensated metabolic acidosis", "Fully compensated respiratory acidosis", "Uncompensated metabolic alkalosis", "Partially compensated metabolic alkalosis"]'::jsonb, 2, 'Step 1: pH 7.48 shows alkalaemia (pH > 7.45). Step 2: PaCO2 40 mmHg is normal (35–45). Step 3: HCO3⁻ 33 mmol/L is high (> 26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated metabolic alkalosis. The other value is still normal, so there is no compensation yet.'),
(5, 99, 'Mechanical Ventilation', 'During a spontaneous breathing trial a patient breathes at 16/min with a tidal volume of 500 mL. What is the rapid shallow breathing index (RSBI)?', '["8 — likely to fail weaning", "32 — likely to wean successfully", "32 — likely to fail weaning", "31 — likely to wean successfully"]'::jsonb, 1, 'RSBI = respiratory rate ÷ tidal volume in litres = 16 ÷ 0.5 = 32 breaths/min/L. Below 105 predicts successful weaning; above 105 suggests rapid shallow breathing and likely failure.'),
(5, 100, 'Mechanical Ventilation', 'A patient''s endotracheal tube cuff, inflated with air, is left in place during a prolonged case using nitrous oxide. A recognized risk of this combination is:', '["Reduced cuff pressure requiring frequent reinflation", "Cuff deflation over time", "Progressive cuff overinflation as nitrous oxide diffuses into the cuff, risking tracheal mucosal ischaemia", "Cuff material degradation"]'::jsonb, 2, 'Nitrous oxide diffuses into the air-filled cuff faster than air (mainly nitrogen) diffuses out, causing cuff pressure and volume to rise progressively during prolonged use, which can compress the tracheal mucosa and cause ischaemic injury.'),
(5, 101, 'Mechanical Ventilation', 'A ventilated ARDS patient has a plateau pressure of 15 cmH2O and PEEP of 5 cmH2O. What is the driving pressure?', '["10 cmH2O — too high (> 15), increasing the risk of lung injury", "20 cmH2O — too high (> 15), increasing the risk of lung injury", "10 cmH2O — within the safe target (≤ 15)", "15 cmH2O — within the safe target (≤ 15)"]'::jsonb, 2, 'Driving pressure = plateau pressure − PEEP = 15 − 5 = 10 cmH2O. Aim for ≤ 15 cmH2O (and plateau ≤ 30) to protect the lungs.'),
(5, 102, 'Mechanical Ventilation', 'A potential complication of Assist-Control ventilation in a patient who is tachypneic from anxiety or pain is:', '["Inability to trigger any breaths", "Hypoventilation and hypercapnia", "Respiratory alkalosis from hyperventilation, along with breath stacking and auto-PEEP", "Automatic apnea"]'::jsonb, 2, 'Because every triggered breath in AC delivers the full tidal volume, a rapid respiratory rate can cause hyperventilation and insufficient expiratory time, leading to breath stacking and auto-PEEP.'),
(5, 103, 'Mechanical Ventilation', 'A female patient with ARDS is 170 cm tall and weighs 87 kg. Using lung-protective ventilation at 6 mL/kg predicted body weight, what tidal volume should be set?', '["About 369 mL", "About 522 mL", "About 492 mL", "About 615 mL"]'::jsonb, 0, 'Predicted (ideal) body weight for a female: 45.5 + 0.91 × (height − 152.4) = 45.5 + 0.91 × 17.6 = 61.5 kg. Tidal volume = 6 mL/kg × 61.5 = 369 mL. Use PREDICTED, not actual (87 kg), weight — lung size depends on height.'),
(5, 104, 'Mechanical Ventilation', 'For a hemodynamically unstable ARDS patient requiring precise control of airway pressures to minimize barotrauma risk while sedated, which mode is often preferred initially?', '["T-piece trial", "CPAP alone", "Pressure Control Ventilation, or volume control with a plateau pressure limit, with controlled mandatory breaths", "Pressure Support Ventilation with a low backup rate"]'::jsonb, 2, 'A fully controlled mode ensures guaranteed ventilation and precise pressure or volume limits appropriate for a sedated, unstable ARDS patient who cannot reliably trigger effective spontaneous breaths.'),
(5, 105, 'Mechanical Ventilation', 'What is the recommended action if a ventilated patient''s exhaled tidal volume suddenly drops significantly with a normal peak pressure and an audible air leak at the mouth?', '["Increase sedation", "Suspect cuff leak or partial tube displacement and assess cuff pressure and tube position immediately", "Increase PEEP", "Assume mucus plug and suction aggressively"]'::jsonb, 1, 'A sudden volume loss with an audible leak suggests cuff deflation or tube malposition; the nurse should assess cuff pressure and tube position urgently.'),
(5, 106, 'Mechanical Ventilation', 'The mode of Mechanical Ventilation which does not allow the patient to take spontaneous breaths is:', '["AC Mode (Assist Control Mode)", "CMV (Control Mandatory Ventilation)", "SIMV (Synchronous intermittent Mandatory Ventilation)", "PCV (Pressure Control Mode)"]'::jsonb, 1, 'Control Mandatory Ventilation delivers only preset breaths with no room for spontaneous effort.'),
(5, 107, 'Mechanical Ventilation', 'A sudden high-pressure alarm accompanied by absent chest rise, difficulty bagging, and inability to pass a suction catheter most strongly suggests:', '["Endotracheal tube obstruction (e.g., mucus plug, kinking, biting)", "Correct tube placement with normal function", "Ventilator circuit disconnection", "Tension pneumothorax with hyperresonance"]'::jsonb, 0, 'Absent chest rise with high resistance to bagging and inability to pass a suction catheter through the tube are classic signs of complete or near-complete ETT obstruction.'),
(5, 108, 'Mechanical Ventilation', 'A key nursing assessment component specific to a patient receiving neuromuscular blockade for ventilator synchrony is:', '["Discontinuing all monitoring since the patient cannot move", "Assessing verbal pain reports", "Allowing the patient to ambulate", "Using a peripheral nerve stimulator, such as train-of-four, to monitor level of blockade and ensuring adequate concurrent sedation and analgesia"]'::jsonb, 3, 'Paralyzed patients cannot demonstrate pain or awareness behaviorally, so train-of-four monitoring guides blockade depth, and adequate sedation and analgesia must be ensured since paralytics have no sedative or analgesic effect.'),
(5, 109, 'Mechanical Ventilation', 'When preoxygenating a trauma patient with facial injuries before intubation, the nurse should be cautious with bag-valve-mask ventilation because:', '["It improves cervical spine stability", "Excessive ventilation pressure can cause gastric insufflation and increase aspiration risk, and may worsen facial injuries", "It has no risks", "It always causes hypoxemia"]'::jsonb, 1, 'Aggressive bag-mask ventilation increases the risk of gastric insufflation, raising aspiration risk, and mask seal may be complicated by facial trauma.'),
(5, 110, 'Mechanical Ventilation', 'A ventilated patient develops a new cardiac dysrhythmia, such as new atrial fibrillation with rapid ventricular response, along with desaturation. The nurse should:', '["Wait for the next scheduled assessment", "Decrease FiO2", "Treat this as an isolated cardiac issue unrelated to ventilation", "Assess for hypoxemia or ventilatory causes contributing to the dysrhythmia and notify the physician promptly given the combined instability"]'::jsonb, 3, 'Hypoxemia is a common trigger for new dysrhythmias in critically ill patients; the combination of new dysrhythmia and desaturation reflects significant compromise requiring urgent notification.'),
(5, 111, 'Mechanical Ventilation', 'A male patient with ARDS is 185 cm tall and weighs 125 kg. Using lung-protective ventilation at 8 mL/kg predicted body weight, what tidal volume should be set?', '["About 1000 mL", "About 637 mL", "About 797 mL", "About 478 mL"]'::jsonb, 1, 'Predicted (ideal) body weight for a male: 50 + 0.91 × (height − 152.4) = 50 + 0.91 × 32.6 = 79.7 kg. Tidal volume = 8 mL/kg × 79.7 = 637 mL. Use PREDICTED, not actual (125 kg), weight — lung size depends on height.'),
(5, 112, 'Mechanical Ventilation', 'The DOPE mnemonic used to rapidly assess a deteriorating ventilated patient stands for:', '["Distress, Obstruction, Pain, Emergency", "Displacement, Obstruction, Pneumothorax, Equipment failure", "Dislodgement, Oxygen, Pressure, Extubation", "Displacement, Overventilation, Pneumonia, Edema"]'::jsonb, 1, 'DOPE is a structured mnemonic for the most common reversible causes of sudden deterioration in a ventilated patient: Displacement, Obstruction, Pneumothorax, and Equipment failure.'),
(5, 113, 'Mechanical Ventilation', 'A patient with severe asthma on the ventilator develops sudden hypotension and difficulty bagging. The nurse should consider disconnecting the patient from the ventilator briefly to allow full exhalation, since this presentation may reflect:', '["Normal ventilator function", "Improved lung compliance", "An unrelated cardiac event only", "Severe auto-PEEP/breath stacking causing dynamic hyperinflation and reduced venous return"]'::jsonb, 3, 'Severe dynamic hyperinflation from breath stacking/auto-PEEP can cause obstructive shock-like physiology (reduced venous return, hypotension) — a brief ventilator disconnect allows full exhalation and can rapidly improve haemodynamics.'),
(5, 114, 'Mechanical Ventilation', 'A male patient with ARDS is 170 cm tall and weighs 101 kg. Using lung-protective ventilation at 8 mL/kg predicted body weight, what tidal volume should be set?', '["About 660 mL", "About 528 mL", "About 808 mL", "About 396 mL"]'::jsonb, 1, 'Predicted (ideal) body weight for a male: 50 + 0.91 × (height − 152.4) = 50 + 0.91 × 17.6 = 66 kg. Tidal volume = 8 mL/kg × 66 = 528 mL. Use PREDICTED, not actual (101 kg), weight — lung size depends on height.'),
(5, 115, 'Mechanical Ventilation', 'Auto-PEEP (intrinsic PEEP), sometimes seen in patients with severe airflow obstruction on a ventilator, occurs when:', '["PEEP is set too low", "Incomplete exhalation traps air in the lungs before the next breath, causing progressive hyperinflation", "There is no relationship to ventilator settings", "The patient fully exhales before the next breath is delivered"]'::jsonb, 1, 'Auto-PEEP occurs when the expiratory time is insufficient for complete exhalation (common in severe airflow obstruction), causing air trapping and progressive hyperinflation with each breath.'),
(5, 116, 'Mechanical Ventilation', 'During a spontaneous breathing trial a patient breathes at 28/min with a tidal volume of 250 mL. What is the rapid shallow breathing index (RSBI)?', '["7 — likely to fail weaning", "9 — likely to wean successfully", "112 — likely to wean successfully", "112 — likely to fail weaning"]'::jsonb, 3, 'RSBI = respiratory rate ÷ tidal volume in litres = 28 ÷ 0.25 = 112 breaths/min/L. Below 105 predicts successful weaning; above 105 suggests rapid shallow breathing and likely failure.'),
(5, 117, 'Mechanical Ventilation', 'A ventilated ARDS patient has a plateau pressure of 28 cmH2O and PEEP of 12 cmH2O. What is the driving pressure?', '["16 cmH2O — within the safe target (≤ 15)", "16 cmH2O — too high (> 15), increasing the risk of lung injury", "28 cmH2O — too high (> 15), increasing the risk of lung injury", "40 cmH2O — too high (> 15), increasing the risk of lung injury"]'::jsonb, 1, 'Driving pressure = plateau pressure − PEEP = 28 − 12 = 16 cmH2O. Aim for ≤ 15 cmH2O (and plateau ≤ 30) to protect the lungs.'),
(5, 118, 'Mechanical Ventilation', 'Which mode of mechanical ventilation delivers a preset volume/pressure with every breath, whether patient-triggered or machine-triggered, providing full support?', '["Assist-Control (AC)", "CPAP with no additional support", "Pressure Support Ventilation alone at low levels", "T-piece trial"]'::jsonb, 0, 'Assist-Control ventilation delivers a full preset breath for every triggered or mandatory breath, providing complete ventilatory support.'),
(5, 119, 'Mechanical Ventilation', 'Pressure support ventilation (PSV) requires which patient characteristic to function safely?', '["Presence of a tracheostomy only", "Complete absence of spontaneous breathing", "Intact spontaneous respiratory drive", "Paralysis from neuromuscular blockade"]'::jsonb, 2, 'PSV augments each spontaneous breath but provides no guaranteed mandatory breaths, so the patient must have a reliable spontaneous respiratory drive.'),
(5, 120, 'Mechanical Ventilation', 'A ventilated patient develops sudden respiratory distress, high-pressure alarm, and coarse rhonchi audible without a stethoscope. The most appropriate first nursing action is:', '["Sedate the patient more deeply", "Immediately call for tube reintubation without assessment", "Increase the FiO2 only", "Attempt suctioning to clear the airway"]'::jsonb, 3, 'Audible coarse rhonchi with a high-pressure alarm strongly suggests secretions are the cause; suctioning is the appropriate initial intervention before more invasive measures.'),
(5, 121, 'Mechanical Ventilation', 'A mechanically ventilated patient''s arterial blood gas shows respiratory alkalosis (low PaCO2, high pH). This most likely indicates:', '["Hyperventilation from excessive minute ventilation (rate/tidal volume too high) or patient-driven tachypnea", "Metabolic acidosis compensation", "Underventilation", "Correct ventilator settings requiring no change"]'::jsonb, 0, 'A low PaCO2 with elevated pH indicates the patient is being overventilated, whether from excessive ventilator settings or the patient''s own tachypnea, and settings should be reassessed.'),
(5, 122, 'Mechanical Ventilation', 'In SIMV (Synchronized Intermittent Mandatory Ventilation) mode, compared to Assist-Control, the patient:', '["Receives full ventilator support for every single breath", "Can take spontaneous breaths between mandatory synchronized breaths, at their own tidal volume", "Cannot breathe spontaneously at all", "Is always fully paralysed"]'::jsonb, 1, 'SIMV delivers a set number of synchronized mandatory breaths while allowing the patient to breathe spontaneously (often with pressure support) between them, unlike Assist-Control, which fully supports every breath the patient triggers.'),
(5, 123, 'Mechanical Ventilation', 'A hypovolaemic patient becomes hypotensive after intubation and positive-pressure ventilation mainly because:', '["Heart rate falls", "Contractility increases", "Afterload falls to zero", "Increased intrathoracic pressure reduces venous return"]'::jsonb, 3, 'Positive-pressure ventilation and PEEP raise intrathoracic pressure, reduce venous return (preload) and may cause hypotension, especially after intubation in hypovolaemic patients.'),
(5, 124, 'Mechanical Ventilation', 'When planning nutrition for a mechanically ventilated COPD patient with difficulty weaning, which principle is important?', '["Provide the highest possible carbohydrate load to maximise energy delivery", "Restrict all protein intake to reduce respiratory workload", "Avoid overfeeding, particularly excess carbohydrate, since it increases CO2 production and ventilatory demand", "Nutrition has no effect on ventilatory demand in COPD"]'::jsonb, 2, 'Excess carbohydrate calories increase the respiratory quotient and CO2 production, increasing ventilatory demand and potentially hindering weaning in patients with limited respiratory reserve.'),
(5, 125, 'Mechanical Ventilation', 'Current ICU sedation guidelines generally favor propofol or dexmedetomidine over benzodiazepine infusions for most mechanically ventilated adults primarily because benzodiazepines are associated with:', '["Higher rates of ICU delirium", "Lower cost and easier titration", "Faster awakening times", "Reduced risk of hypotension"]'::jsonb, 0, 'Benzodiazepine-based sedation has been associated with higher rates of ICU delirium and longer time to extubation compared with propofol or dexmedetomidine, leading current guidelines to favor non-benzodiazepine sedation strategies where feasible.'),
(5, 126, 'Mechanical Ventilation', 'A ventilated patient becomes agitated and is pulling at the endotracheal tube. The nurse''s priority assessment is to:', '["Immediately extubate the patient", "Assess for a treatable cause of agitation such as hypoxia, pain, or ventilator asynchrony before increasing restraint or sedation alone", "Increase the ventilator rate", "Apply four-point restraints without further assessment"]'::jsonb, 1, 'Agitation in a ventilated patient often has a reversible cause (hypoxia, pain, asynchrony, full bladder); this should be assessed before escalating restraint or sedation.'),
(5, 127, 'Mechanical Ventilation', 'When caring for a patient on Pressure Control Ventilation (PCV) for ARDS, the nurse should closely monitor:', '["Only respiratory rate", "FiO2 alone", "Only the set pressure, since volume is irrelevant", "Exhaled tidal volume, since it varies with changes in lung compliance and resistance"]'::jsonb, 3, 'In PCV the clinician sets pressure and inspiratory time; tidal volume is a dependent variable that fluctuates with the patient''s compliance and airway resistance, so it must be monitored continuously.'),
(5, 128, 'Mechanical Ventilation', 'Using EtCO2 to guide ventilator adjustments in a patient managed with permissive hypercapnia, such as an ARDS lung-protective strategy, provides the benefit of:', '["Allowing noninvasive, continuous trending of ventilation adequacy to help balance lung-protective settings against acceptable CO2 elevation", "Forcing normalization of PaCO2 at all times", "Preventing any hypercapnia from occurring", "Eliminating the need to check arterial blood gases entirely"]'::jsonb, 0, 'Continuous EtCO2 trending helps the care team monitor the degree of hypercapnia noninvasively and in real time while implementing lung-protective ventilation, complementing periodic blood gas checks.'),
(5, 129, 'Mechanical Ventilation', 'A mechanically ventilated patient''s high-pressure alarm sounds repeatedly. On assessment, breath sounds are decreased on the right with tracheal deviation to the left and hyper-resonance on percussion. The nurse should suspect:', '["Mucus plug in the right main bronchus", "Pulmonary oedema", "Normal ventilator function", "Tension pneumothorax on the right"]'::jsonb, 3, 'Decreased breath sounds, tracheal deviation away from the affected side, and hyper-resonance are classic signs of tension pneumothorax — a life-threatening emergency requiring immediate needle decompression.'),
(5, 130, 'Mechanical Ventilation', 'Stress ulcer (gastrointestinal) prophylaxis is routinely recommended for mechanically ventilated patients because:', '["It prevents ventilator-associated pneumonia directly", "It replaces the need for enteral nutrition", "Critical illness and mechanical ventilation increase risk of stress-related mucosal bleeding", "Ventilated patients are at no increased GI bleeding risk"]'::jsonb, 2, 'Mechanical ventilation beyond 48 hours (and coagulopathy) are recognized risk factors for stress-related mucosal disease, making stress ulcer prophylaxis a standard part of ICU care bundles.'),
(5, 131, 'Mechanical Ventilation', 'A patient came to the ER with Difficulty in breathing; He was intubated and placed on Mechanical ventilation. His ABGs report showed that his PCO2 is 55 mm Hg. To wash out CO2 which of the following parameter(s) should be adjusted:', '["Vt and PEEP", "Vt and R/R", "Fio2 and R/R", "PEEP and FiO2"]'::jsonb, 1, 'Washing out CO2 means increasing minute ventilation — adjusting tidal volume and respiratory rate.'),
(5, 132, 'Mechanical Ventilation', 'A patient with COPD exacerbation and cardiogenic pulmonary edema who is alert, cooperative, and hemodynamically stable may first be tried on which form of ventilatory support before invasive intubation?', '["Immediate invasive mechanical ventilation", "High-frequency oscillatory ventilation", "Negative pressure ventilation", "Noninvasive positive pressure ventilation (BiPAP)"]'::jsonb, 3, 'Alert, cooperative, hemodynamically stable patients with COPD exacerbation or cardiogenic pulmonary edema are appropriate candidates for a trial of noninvasive positive pressure ventilation before invasive intubation.'),
(5, 133, 'Mechanical Ventilation', 'The mode of Mechanical Ventilation in which there is a Preset Breath rate and tidal volume but the patient is able to initiate extra breath which is assisted by the ventilator is called:', '["ACV", "CMV", "PSV", "SIMV"]'::jsonb, 0, 'Preset rate/volume with the ability to trigger extra ventilator-assisted breaths describes Assist-Control Ventilation.'),
(5, 134, 'Mechanical Ventilation', 'During a spontaneous breathing trial a patient breathes at 16/min with a tidal volume of 400 mL. What is the rapid shallow breathing index (RSBI)?', '["25 — likely to wean successfully", "6.4 — likely to fail weaning", "40 — likely to fail weaning", "40 — likely to wean successfully"]'::jsonb, 3, 'RSBI = respiratory rate ÷ tidal volume in litres = 16 ÷ 0.4 = 40 breaths/min/L. Below 105 predicts successful weaning; above 105 suggests rapid shallow breathing and likely failure.'),
(5, 135, 'Mechanical Ventilation', 'A patient on PEEP (Positive End-Expiratory Pressure) develops sudden hypotension after the PEEP level is increased. The most likely explanation is:', '["An allergic reaction to the ventilator tubing", "PEEP has no cardiovascular effects", "Increased intrathoracic pressure reducing venous return and cardiac output", "Coincidental, unrelated hypotension"]'::jsonb, 2, 'High PEEP increases intrathoracic pressure, which can reduce venous return to the heart and subsequently lower cardiac output and blood pressure.'),
(5, 136, 'Mechanical Ventilation', 'A ventilated patient has a tidal volume of 350 mL and a rate of 24 breaths/min. What is the minute ventilation?', '["14.58 L/min", "10.8 L/min", "8.4 L/min", "84 L/min"]'::jsonb, 2, 'Minute ventilation = tidal volume × rate = 350 mL × 24 = 8,400 mL/min = 8.4 L/min (normal about 5–8 L/min).'),
(5, 137, 'Mechanical Ventilation', 'A patient is extubated successfully but develops increasing stridor and respiratory distress within an hour. The nurse should anticipate:', '["Post-extubation laryngeal oedema/airway swelling, potentially requiring nebulised adrenaline, steroids, or reintubation", "No specific concern, since extubation was successful", "No monitoring is needed for the next several hours", "Discharge planning"]'::jsonb, 0, 'Post-extubation stridor suggests laryngeal oedema — management may include nebulised adrenaline and steroids, with close monitoring and readiness for reintubation if it worsens.'),
(5, 138, 'Mechanical Ventilation', 'A ventilated patient with bilateral infiltrates on PEEP 10 cmH2O has PaO2 75 mmHg on FiO2 1.0. Using the P/F ratio, how is this classified?', '["Severe ARDS", "Mild ARDS", "Normal oxygenation (no ARDS)", "Moderate ARDS"]'::jsonb, 0, 'P/F ratio = PaO2 ÷ FiO2 = 75 ÷ 1.0 = 75. Berlin definition (with PEEP ≥ 5): mild 201–300, moderate 101–200, severe ≤ 100. So this is Severe ARDS.'),
(5, 139, 'Mechanical Ventilation', 'A patient with pulmonary oedema is started on BiPAP. What is the expected physiological benefit?', '["Increases preload to improve cardiac output", "Eliminates the need for diuretic therapy", "Increases venous return to the right heart", "Reduces work of breathing and improves alveolar recruitment via positive pressure"]'::jsonb, 3, 'Positive pressure ventilation recruits collapsed, fluid-filled alveoli, decreases work of breathing, and reduces preload/afterload, improving oxygenation in cardiogenic pulmonary oedema.'),
(5, 140, 'Mechanical Ventilation', 'A mechanically ventilated patient in status asthmaticus develops sudden hypotension and increased peak airway pressures. The nurse should first suspect:', '["Hypoglycemia", "Auto-PEEP causing decreased venous return (breath stacking)", "Ventilator-associated pneumonia", "A normal expected ventilator finding"]'::jsonb, 1, 'Air trapping/auto-PEEP increases intrathoracic pressure, reducing venous return and cardiac output, causing hypotension, often managed by briefly disconnecting the ventilator to allow exhalation.'),
(5, 141, 'Mechanical Ventilation', 'A ventilated patient has tidal volume 400 mL, plateau pressure 22 cmH2O and PEEP 12 cmH2O. What is the static lung compliance?', '["25 mL/cmH2O", "18.2 mL/cmH2O", "40 mL/cmH2O", "11.8 mL/cmH2O"]'::jsonb, 2, 'Static compliance = tidal volume ÷ (plateau pressure − PEEP) = 400 ÷ (22 − 12) = 40 mL/cmH2O. Normal is about 50–100; low compliance means stiff lungs (e.g. ARDS, pulmonary oedema).'),
(5, 142, 'Mechanical Ventilation', 'A ventilator is set at 10 breaths/min with an inspiratory time of 1.2 seconds. What is the I:E ratio?', '["1:0.8", "4:1", "1:6", "1:4"]'::jsonb, 3, 'Each breath lasts 60 ÷ 10 = 6 s. Expiratory time = 6 − 1.2 = 4.8 s. I:E = 1.2 : 4.8 = 1:4.'),
(5, 143, 'Mechanical Ventilation', 'A patient with a severe traumatic brain injury requires sedation for ventilator tolerance. The team performs a ''neuro wake-up'' assessment periodically. The primary purpose of this is to:', '["Discharge the patient sooner regardless of status", "Allow accurate ongoing neurological assessment despite the need for sedation", "Increase sedation requirements", "Reduce the need for any imaging"]'::jsonb, 1, 'Periodic sedation interruption (''neuro wake-up'') allows the team to perform an accurate neurological exam, balancing the competing needs of sedation and neurological monitoring.'),
(5, 144, 'Critical Care Scenarios', 'A patient with a subarachnoid haemorrhage is prescribed nimodipine. The rationale for this medication is primarily to:', '["Lower blood pressure aggressively as the main goal", "Reduce the risk of cerebral vasospasm and secondary ischaemic injury", "Reduce intracranial pressure directly", "Treat infection"]'::jsonb, 1, 'Nimodipine, a calcium channel blocker, is used after subarachnoid haemorrhage specifically to reduce the risk of cerebral vasospasm, a major cause of secondary ischaemic injury in this condition.'),
(5, 145, 'Critical Care Scenarios', 'A patient with known oesophageal varices develops sudden haematemesis and hypotension. The nurse''s priority actions include:', '["Secure IV access, prepare for fluid/blood resuscitation, and avoid over-transfusion which can raise portal pressure", "Encourage oral fluids immediately", "Give a laxative to clear the bowel", "Discharge home with outpatient follow-up"]'::jsonb, 0, 'Variceal bleeding requires prompt resuscitation with IV access and blood products, but over-transfusion is avoided since it can raise portal pressure and worsen bleeding.'),
(5, 146, 'Critical Care Scenarios', 'A patient in labour has premature rupture of membranes with meconium-stained liquor. This finding is significant because it may indicate:', '["Possible fetal distress, requiring closer fetal monitoring", "A sign of maternal infection only", "A completely normal, reassuring finding with no significance", "Definite fetal death, requiring no further action"]'::jsonb, 0, 'Meconium-stained liquor can indicate fetal distress and requires closer fetal monitoring and preparation for potential neonatal complications at delivery.'),
(5, 147, 'Critical Care Scenarios', 'A patient with acute respiratory failure requires emergent intubation. Which pre-intubation nursing action is most important to optimize outcomes?', '["Sedate the patient heavily without any oxygen supplementation", "Pre-oxygenate with high-flow oxygen or bag-valve-mask prior to intubation", "Delay intubation until the patient is fully alert", "Withhold oxygen until the tube is placed to avoid hyperoxia"]'::jsonb, 1, 'Adequate pre-oxygenation extends the safe apnea time during intubation attempts, reducing the risk of severe desaturation and cardiac arrest during the peri-intubation period.'),
(5, 148, 'Critical Care Scenarios', 'A patient on long-term corticosteroid therapy for a chronic condition is admitted critically ill. The nurse should anticipate the need for:', '["Switching immediately to an unrelated drug class", "No special consideration regarding steroid dosing", "Continued (often increased ''stress-dose'') steroid coverage, since abrupt withdrawal risks adrenal crisis", "Abrupt discontinuation of steroids immediately"]'::jsonb, 2, 'Patients on long-term steroids have suppressed adrenal function — abrupt withdrawal during acute illness risks adrenal crisis, so continued (often stress-dose) steroid coverage is needed.'),
(5, 149, 'Critical Care Scenarios', 'A patient with a suspected overdose of unknown substance is unconscious with a GCS of 6 and shallow, slow respirations. What is the most immediate nursing priority?', '["Prepare for airway protection (e.g., positioning, suction, possible intubation) and provide ventilatory support", "Send the patient for an urgent CT scan of the head", "Administer activated charcoal orally", "Obtain a detailed medication history from family"]'::jsonb, 0, 'A GCS of 8 or less generally indicates the patient cannot protect their own airway; securing the airway and supporting ventilation is the immediate life-saving priority before any decontamination or diagnostic procedure.'),
(5, 150, 'Critical Care Scenarios', 'A patient''s renal function tests show a rising creatinine and urea with oliguria following a major surgery complicated by hypotension. This presentation is most consistent with:', '["Acute kidney injury, likely pre-renal from hypoperfusion", "Diabetes insipidus", "Chronic kidney disease of long standing", "Normal post-operative recovery"]'::jsonb, 0, 'Rising creatinine/urea with oliguria after a hypotensive episode is characteristic of acute kidney injury, commonly pre-renal in origin from reduced renal perfusion.'),
(5, 151, 'Critical Care Scenarios', 'A patient receiving IV nitroglycerin for cardiogenic pulmonary oedema develops a blood pressure of 82/50 mmHg. What is the nurse''s priority action?', '["Administer a fluid bolus and continue the infusion unchanged", "Switch to sublingual nitroglycerin", "Increase the infusion rate to improve cardiac output", "Stop or slow the infusion and reassess blood pressure"]'::jsonb, 3, 'Nitroglycerin causes venodilation and arterial dilation and can precipitate hypotension; the infusion should be slowed or stopped and blood pressure reassessed to prevent hypoperfusion.'),
(5, 152, 'Critical Care Scenarios', 'A patient''s SpO2 reads 99% but the patient appears cyanotic, confused, and has recently been exposed to carbon monoxide. The nurse should recognise that:', '["The SpO2 reading is definitely accurate and reassuring", "No further assessment is needed given the good SpO2", "Cyanosis always confirms the oximeter is broken", "Standard pulse oximetry cannot distinguish oxyhaemoglobin from carboxyhaemoglobin, so a falsely reassuring high reading is possible in CO poisoning"]'::jsonb, 3, 'Standard pulse oximeters cannot differentiate oxyhaemoglobin from carboxyhaemoglobin, so SpO2 can read falsely normal/high in CO poisoning despite severe functional hypoxia — clinical suspicion must override a reassuring number.'),
(5, 153, 'Critical Care Scenarios', 'A patient recovering from a head injury is assessed to have decerebrate posturing (extension of all four limbs) in response to painful stimuli. This indicates:', '["More severe brainstem dysfunction, generally a worse prognosis than decorticate posturing", "A better prognosis than decorticate posturing", "Normal neurological function", "No clinical relevance"]'::jsonb, 0, 'Decerebrate (extensor) posturing indicates more severe brainstem involvement and generally carries a worse prognosis than decorticate (flexor) posturing.'),
(5, 154, 'Critical Care Scenarios', 'A patient receiving an intra-aortic balloon pump (IABP) suddenly develops a cold, pulseless left leg. The nurse should suspect:', '["Limb ischaemia from the IABP catheter, requiring urgent assessment and intervention", "An allergic reaction to the dressing", "Normal side effect requiring no action", "A simple positioning issue with no urgency"]'::jsonb, 0, 'IABP insertion carries a risk of distal limb ischaemia — a cold, pulseless limb after insertion is a vascular emergency requiring urgent assessment.'),
(5, 155, 'Critical Care Scenarios', 'A patient''s coagulation panel shows a markedly prolonged PT/INR with normal aPTT. This pattern most specifically suggests an abnormality in:', '["The intrinsic coagulation pathway only", "Platelet function only", "No coagulation abnormality", "The extrinsic coagulation pathway (e.g. Factor VII deficiency or warfarin effect)"]'::jsonb, 3, 'An isolated prolonged PT/INR with normal aPTT points toward the extrinsic pathway (Factor VII), classically seen with warfarin therapy or early vitamin K deficiency.'),
(5, 156, 'Critical Care Scenarios', 'A patient develops new left-sided facial droop, arm weakness, and slurred speech that resolves completely within 20 minutes. This presentation is most consistent with:', '["Normal ageing", "A migraine with no further evaluation needed", "A Transient Ischaemic Attack (TIA), which still requires urgent evaluation given high subsequent stroke risk", "A completed stroke with permanent deficit"]'::jsonb, 2, 'Fully resolving neurological symptoms suggest TIA, which carries a significant risk of subsequent full stroke and requires urgent evaluation and secondary prevention, not reassurance.'),
(5, 157, 'Critical Care Scenarios', 'A patient with an infected surgical wound has cultures growing Pseudomonas aeruginosa resistant to multiple antibiotics. The nurse should anticipate:', '["Contact precautions in addition to standard precautions, given the multidrug-resistant organism", "Standard precautions alone are sufficient with no additional measures", "No precautions are necessary since it is only a wound infection", "Airborne precautions specifically"]'::jsonb, 0, 'Multidrug-resistant organisms typically require contact precautions (gown/gloves) in addition to standard precautions to prevent transmission to other patients.'),
(5, 158, 'Critical Care Scenarios', 'A patient in the PACU has a pulse oximetry reading of 90% on room air, with shallow respirations and drowsiness after opioid analgesia. The nurse''s priority action is to:', '["Increase the opioid dose to help the patient rest", "Stimulate the patient, apply supplemental oxygen, and consider naloxone per protocol while notifying the anaesthetist", "Discharge the patient to the ward immediately", "Document and reassess in one hour"]'::jsonb, 1, 'Hypoxaemia with drowsiness and shallow breathing after opioids suggests opioid-induced respiratory depression, requiring prompt stimulation, oxygen, possible naloxone, and physician notification.'),
(5, 159, 'Critical Care Scenarios', 'A patient with suspected mushroom poisoning develops severe gastroenteritis 6-24 hours after ingestion, followed by signs of liver failure over the next several days. Which type of mushroom toxin is most likely responsible?', '["Ibotenic acid-containing mushrooms", "Muscarine-containing mushrooms", "Amatoxin-containing mushrooms (e.g., Amanita phalloides)", "Psilocybin-containing mushrooms"]'::jsonb, 2, 'Amatoxins cause a delayed onset of severe gastroenteritis followed by progressive hepatotoxicity and potential fulminant liver failure over several days, a pattern distinct from the rapid-onset toxidromes of other mushroom toxins.'),
(5, 160, 'Critical Care Scenarios', 'Primary hyperaldosteronism (Conn syndrome) classically presents with which combination of findings?', '["Hypotension, hyperkalemia, and metabolic acidosis with elevated renin", "Hypertension, hypokalemia, and metabolic alkalosis with suppressed plasma renin", "Hypertension with elevated renin and elevated aldosterone", "Normal blood pressure with hyperkalemia"]'::jsonb, 1, 'Autonomous aldosterone excess causes sodium/water retention (hypertension), renal potassium wasting (hypokalemia), and hydrogen ion loss (metabolic alkalosis), while the elevated aldosterone suppresses renin via negative feedback, producing a low renin-to-aldosterone ratio.'),
(5, 161, 'Critical Care Scenarios', 'A patient with acute severe asthma has a silent chest on auscultation. The nurse should interpret this as:', '["Normal findings for an asthmatic patient", "An ominous sign of minimal air movement/impending respiratory failure", "A sign of over-treatment with bronchodilators", "A reassuring sign that the asthma is resolving"]'::jsonb, 1, 'A silent chest means almost no air is moving due to severe airway obstruction — this is an extremely dangerous sign requiring urgent escalation, not reassurance.'),
(5, 162, 'Critical Care Scenarios', 'A patient with acute cardiogenic pulmonary oedema presents with pink frothy sputum, orthopnea, and bilateral crackles. Which hemodynamic mechanism best explains the fluid accumulation?', '["Increased pulmonary capillary permeability from sepsis", "Increased pulmonary capillary hydrostatic pressure from left ventricular failure", "Decreased plasma oncotic pressure from hypoalbuminemia", "Lymphatic obstruction from mediastinal malignancy"]'::jsonb, 1, 'Cardiogenic pulmonary oedema results from elevated left atrial and pulmonary capillary hydrostatic pressure due to LV failure, forcing fluid into the alveoli.'),
(5, 163, 'Critical Care Scenarios', 'A patient presents with dry flushed skin, dilated pupils, urinary retention, hyperthermia, tachycardia, and confusion after ingesting an unknown substance. This presentation is most consistent with which toxidrome?', '["Anticholinergic toxidrome", "Cholinergic toxidrome", "Sedative-hypnotic toxidrome", "Opioid toxidrome"]'::jsonb, 0, 'The mnemonic ''red as a beet, dry as a bone, blind as a bat, mad as a hatter, hot as a hare'' describes the anticholinergic toxidrome: flushed dry skin, mydriasis, urinary retention, hyperthermia, and delirium.'),
(5, 164, 'Critical Care Scenarios', 'A patient with severe acute pancreatitis has hypocalcaemia. This is primarily explained by:', '["Calcium being consumed in saponification (fat necrosis) reactions within the abdomen", "A pre-existing unrelated condition", "Excess dietary calcium intake", "Overactive parathyroid glands"]'::jsonb, 0, 'In severe pancreatitis, released pancreatic enzymes cause fat necrosis, and calcium is consumed in the resulting saponification process, contributing to hypocalcaemia.'),
(5, 165, 'Critical Care Scenarios', 'A patient presents with poisoning from ingestion of a substance containing methanol found in illicitly distilled alcohol (''moonshine''). Which clinical feature is a classic warning sign of methanol toxicity?', '["Excessive salivation and lacrimation", "Bright red skin discolouration", "Pinpoint pupils", "Visual disturbances or blindness due to optic nerve toxicity from formic acid accumulation"]'::jsonb, 3, 'Methanol is metabolised to formic acid, which is particularly toxic to the retina and optic nerve, classically causing blurred vision, blindness, and a metabolic acidosis with a raised anion and osmolar gap.'),
(5, 166, 'Critical Care Scenarios', 'A patient with heart failure receiving digoxin has a potassium level of 3.0mmol/L. The nurse should recognise this combination as significant because it:', '["Reduces the risk of digoxin toxicity", "Only affects blood pressure, not cardiac rhythm", "Increases the risk of digoxin toxicity and arrhythmia", "Has no bearing on digoxin''s effect"]'::jsonb, 2, 'Hypokalaemia increases myocardial sensitivity to digoxin, raising the risk of toxicity and arrhythmia even at otherwise therapeutic digoxin levels.'),
(5, 167, 'Critical Care Scenarios', 'A patient with cardiac tamponade would be expected to show which combination of findings (Beck''s Triad)?', '["Fever, cough, wheeze", "Polyuria, polydipsia, weight loss", "Hypotension, jugular venous distension, muffled heart sounds", "Hypertension, bradycardia, loud heart sounds"]'::jsonb, 2, 'Beck''s Triad — hypotension, elevated JVP, and muffled/distant heart sounds — is classic for cardiac tamponade.'),
(5, 168, 'Critical Care Scenarios', 'A patient six hours post-thyroidectomy develops increasing neck swelling and stridor. The nurse''s priority action is to:', '["Call for immediate help, sit the patient upright, give high-flow oxygen, and prepare for emergency wound release if instructed", "Reassure the patient this is normal post-operative swelling with no action needed", "Discharge the patient home for outpatient follow-up", "Apply a tight neck dressing to control swelling"]'::jsonb, 0, 'Post-thyroidectomy airway compression from a wound haematoma is a life-threatening emergency requiring immediate escalation and, if instructed, bedside opening of the wound to release the haematoma.'),
(5, 169, 'Critical Care Scenarios', 'A patient''s spinal cord injury results in preserved diaphragmatic breathing but loss of intercostal muscle function and all function below the upper chest. This is most consistent with an injury at approximately which level?', '["C1-C2", "C6-C8/T1", "T12-L1", "S2-S4"]'::jsonb, 1, 'An injury around the lower cervical to upper thoracic level (C6-T1) spares the phrenic nerve (C3-C5) so diaphragmatic breathing continues, but intercostal muscle function (innervated by thoracic nerves) and function below the injury level are lost.'),
(5, 170, 'Critical Care Scenarios', 'A patient with severe liver disease develops ascites and peripheral oedema. The nurse understands this is partly explained by the liver''s reduced synthesis of:', '["Insulin only", "Red blood cells", "Albumin, reducing plasma oncotic pressure and allowing fluid to shift into tissues/peritoneal cavity", "White blood cells"]'::jsonb, 2, 'The liver normally synthesises albumin, which maintains plasma oncotic pressure — reduced albumin in liver disease allows fluid to shift out of the vasculature, contributing to ascites and oedema.'),
(5, 171, 'Critical Care Scenarios', 'Primary hyperparathyroidism, most commonly caused by a solitary parathyroid adenoma, classically presents with which laboratory pattern?', '["Low serum calcium with low PTH", "Elevated serum calcium with elevated or inappropriately normal PTH", "Elevated serum calcium with suppressed PTH", "Low serum calcium with elevated PTH"]'::jsonb, 1, 'In primary hyperparathyroidism, autonomous PTH secretion (usually from an adenoma) causes hypercalcemia, and PTH is either frankly elevated or inappropriately normal despite the elevated calcium, distinguishing it from other causes of hypercalcemia.'),
(5, 172, 'Critical Care Scenarios', 'A patient with a severe brain injury is noted to have a rising temperature unrelated to infection. The nurse understands this can occur due to:', '["Simple dehydration only", "No relationship between brain injury and temperature regulation", "Always indicates infection with no other cause possible", "Hypothalamic dysfunction from the injury itself, sometimes called ''central fever''"]'::jsonb, 3, 'Severe brain injury can disrupt hypothalamic thermoregulation, causing ''central fever'' unrelated to infection, though infection must still be actively excluded.'),
(5, 173, 'Critical Care Scenarios', 'A patient''s angina is unrelieved after 3 sublingual nitroglycerin tablets taken 5 minutes apart. The priority nursing action is to:', '["Administer a 4th tablet and wait 15 more minutes", "Notify the provider/activate emergency response and evaluate for acute MI", "Encourage the patient to walk to reduce anxiety", "Document and reassess in 1 hour"]'::jsonb, 1, 'Pain unrelieved after 3 nitroglycerin doses suggests evolving MI and requires immediate escalation, ECG, and biomarker evaluation.'),
(5, 174, 'Critical Care Scenarios', 'A patient with clear fluid draining from the nose after head trauma should be assessed for:', '["No clinical significance", "Cerebrospinal fluid rhinorrhoea, a sign of possible skull base fracture with dural tear", "A common cold unrelated to the trauma", "Simple allergic rhinitis with no further concern"]'::jsonb, 1, 'Clear fluid drainage from the nose after head trauma raises concern for CSF rhinorrhoea from a skull base fracture with dural tear, which can be confirmed with specific testing (e.g. halo sign, beta-2 transferrin).'),
(5, 175, 'Critical Care Scenarios', 'A 55 year old male patient is admitted with a massive GI bleed. The patient is at risk for what type of acute kidney injury?', '["Intrinsic renal", "Intra-renal", "Pre-renal", "Post-renal"]'::jsonb, 2, 'Massive GI bleeding causing hypovolaemia is a classic pre-renal cause of AKI.'),
(5, 176, 'Critical Care Scenarios', 'A patient on CRRT (Continuous Renal Replacement Therapy) develops a sudden drop in filter/circuit pressure with visible clotting in the circuit. The nurse''s priority action is to:', '["Disconnect the patient permanently from all renal support", "Continue therapy unchanged", "Assess anticoagulation status, notify the team, and prepare for circuit change per protocol, since a clotted circuit stops effective filtration", "Increase the blood flow rate significantly without assessment"]'::jsonb, 2, 'Circuit clotting on CRRT requires prompt assessment (often anticoagulation adequacy) and circuit change, since a clotted circuit is no longer providing effective renal replacement therapy.'),
(5, 177, 'Critical Care Scenarios', 'A patient with a history of asthma receiving nebulized acetylcysteine should be monitored closely for:', '["Bronchospasm", "Hypertension", "Hyperkalemia", "Serotonin syndrome"]'::jsonb, 0, 'Acetylcysteine can irritate the airway and precipitate bronchospasm, particularly in patients with reactive airway disease; a bronchodilator should be available or co-administered.'),
(5, 178, 'Critical Care Scenarios', 'A patient with pneumonia develops persistent fever, pleuritic chest pain, and a loculated pleural fluid collection with low pH and low glucose on pleural fluid analysis. This is most consistent with:', '["Pulmonary embolism", "A simple transudative effusion from heart failure", "Chronic bronchitis", "Empyema (infected pleural effusion)"]'::jsonb, 3, 'Empyema is a complicated, infected pleural effusion characterised by turbid/purulent fluid, low pH, and low glucose, and often requires drainage in addition to antibiotics.'),
(5, 179, 'Critical Care Scenarios', 'A patient with a suspected benzodiazepine overdose is being considered for flumazenil administration. Which condition makes flumazenil relatively contraindicated?', '["Normal renal function", "Mild drowsiness without respiratory compromise", "Chronic benzodiazepine use or co-ingestion with a pro-convulsant drug such as a tricyclic antidepressant, due to seizure risk", "Known allergy to opioids"]'::jsonb, 2, 'In patients who are benzodiazepine-dependent or who have co-ingested a proconvulsant (e.g., TCAs), abruptly reversing GABA-mediated sedation with flumazenil can precipitate seizures that may be difficult to treat.'),
(5, 180, 'Critical Care Scenarios', 'A patient with a newly inserted temporary transvenous pacemaker shows pacer spikes with no captured QRS complex at times, worsening when the patient takes a deep breath. This is most likely due to:', '["Battery failure only", "Improved lead contact", "Normal pacemaker function with no concern", "Lead micro-displacement affecting capture with patient movement/position change, requiring evaluation"]'::jsonb, 3, 'Positional variation in capture suggests possible lead micro-displacement, which can worsen with movement/breathing — this requires prompt evaluation and possible repositioning.'),
(5, 181, 'Critical Care Scenarios', 'A patient with suspected food poisoning from Clostridium botulinum presents with descending paralysis, diplopia, and dysphagia, with a clear sensorium. What is the priority nursing concern?', '["Administering activated charcoal, since this is the priority treatment", "Close monitoring of respiratory function, as respiratory muscle paralysis can develop and require ventilatory support", "Reassuring the patient that no monitoring is required since consciousness is preserved", "Restricting fluids to prevent worsening symptoms"]'::jsonb, 1, 'Botulinum toxin causes a descending flaccid paralysis that can progress to respiratory failure; vigilant monitoring of respiratory effort and vital capacity is essential, with early consideration of ventilatory support.'),
(5, 182, 'Critical Care Scenarios', 'A patient with a subarachnoid haemorrhage develops new confusion and weakness on day 7, distinct from their baseline post-bleed status. The nurse should have a high suspicion for:', '["Normal recovery progress", "An unrelated finding", "Delayed cerebral ischaemia from vasospasm, a recognised complication in the days following subarachnoid haemorrhage", "Improvement in neurological status"]'::jsonb, 2, 'Vasospasm-related delayed cerebral ischaemia classically presents with new neurological deterioration around days 4-14 after subarachnoid haemorrhage and requires urgent evaluation and management.'),
(5, 183, 'Critical Care Scenarios', 'A patient is admitted 8 hours after a large intentional paracetamol (acetaminophen) overdose. Which investigation is essential to guide treatment decisions?', '["A random blood glucose only", "A serum paracetamol level plotted on the treatment nomogram against time since ingestion", "A chest X-ray", "A urine drug screen for opioids"]'::jsonb, 1, 'Serum paracetamol concentration plotted against time post-ingestion on the paracetamol treatment nomogram determines whether N-acetylcysteine therapy is indicated.'),
(5, 184, 'Critical Care Scenarios', 'A woman in active labour develops a sudden onset of severe abdominal pain, vaginal bleeding, and a change in fetal heart rate pattern to bradycardia after a previous caesarean section. This should raise suspicion for:', '["Braxton Hicks contractions", "Uterine rupture at the site of the previous caesarean scar", "Simple round ligament pain", "Normal labour progress"]'::jsonb, 1, 'Sudden severe pain, bleeding and fetal distress in a labouring patient with a prior caesarean section raises urgent concern for uterine rupture, an obstetric emergency.'),
(5, 185, 'Critical Care Scenarios', 'A patient who has been admitted with a gastric ulcer now develops severe epigastric pain that spreads over the entire abdomen. He is very pale and is lying on his side. What should be the nurse''s immediate action?', '["Reposition the patient In Semi-Fowler''s Position.", "Perform deep palpations on the abdomen.", "Notify the doctor and check the vitals.", "Immediately administer opioids."]'::jsonb, 2, 'Sudden generalised abdominal pain, pallor and guarding in a patient with a peptic ulcer suggests perforation. Check vital signs for shock and inform the doctor immediately; do not give opioids or palpate deeply first.'),
(5, 186, 'Critical Care Scenarios', 'A patient with beta-blocker overdose presents with severe bradycardia and hypotension refractory to atropine. Which agent is most appropriate as a specific treatment?', '["Naloxone", "Flumazenil", "High-dose insulin with glucose (hyperinsulinaemia-euglycaemia therapy) and/or glucagon", "Activated charcoal given IV"]'::jsonb, 2, 'Glucagon bypasses the blocked beta-receptor to increase intracellular cAMP, improving heart rate and contractility, and high-dose insulin/glucose therapy improves myocardial energy utilisation in severe beta-blocker toxicity.'),
(5, 187, 'Critical Care Scenarios', 'A woman with an ectopic pregnancy presents with unilateral lower abdominal pain, vaginal bleeding, and signs of hypovolaemic shock. This presentation should be treated as:', '["A life-threatening gynaecological emergency requiring urgent assessment and likely surgical intervention", "A urinary tract infection", "Normal early pregnancy discomfort", "A routine outpatient concern"]'::jsonb, 0, 'A ruptured ectopic pregnancy is a life-threatening cause of intra-abdominal haemorrhage and hypovolaemic shock, requiring urgent surgical management.'),
(5, 188, 'Critical Care Scenarios', 'A patient develops sudden chest pain and dyspnoea after central line insertion. A chest X-ray shows a hyperlucent area with absent lung markings on the same side. This confirms:', '["Successful catheter placement with no complication", "Pleural effusion", "Pneumothorax, a recognised complication of central line insertion", "Normal post-procedure findings"]'::jsonb, 2, 'A hyperlucent area with absent lung markings after central line insertion confirms pneumothorax, a well-recognised procedural complication requiring prompt management.'),
(5, 189, 'Critical Care Scenarios', 'A farm worker presents with excessive salivation, lacrimation, urination, diarrhoea, GI cramps, emesis (SLUDGE), miosis, bradycardia, and muscle fasciculations after exposure to a crop spray. Which class of toxin is most likely responsible?', '["Anticholinergic poisoning", "Organophosphate (cholinergic) poisoning", "Opioid overdose", "Sympathomimetic overdose"]'::jsonb, 1, 'SLUDGE symptoms plus miosis, bradycardia, and fasciculations reflect excess acetylcholine at muscarinic and nicotinic receptors, the hallmark of organophosphate/cholinergic toxicity.'),
(5, 190, 'Critical Care Scenarios', 'A patient with a large pleural effusion undergoes therapeutic thoracentesis. As a general safety principle, fluid removal in a single session is often limited to approximately:', '["Around 1–1.5 litres, to reduce the risk of re-expansion pulmonary oedema", "10 litres", "No limit at all, regardless of volume", "Only 10ml"]'::jsonb, 0, 'Large-volume thoracentesis is generally limited (often to around 1–1.5L per session) to reduce the risk of re-expansion pulmonary oedema and hypotension.'),
(5, 191, 'Critical Care Scenarios', 'A patient with a PAC develops a new PA waveform that shows no dicrotic notch and looks like a damped, flattened line even with the balloon deflated. The FIRST nursing action should be to check:', '["The patient''s temperature", "The pacemaker settings", "The patient''s oral intake", "The transducer connections, tubing for air/clots, and confirm the stopcocks are positioned correctly before escalating"]'::jsonb, 3, 'Basic troubleshooting of the monitoring system (connections, air, clots, stopcock position) should be completed first, as these are the most common and easily corrected causes.'),
(5, 192, 'Critical Care Scenarios', 'A client on propylthiouracil develops a sore throat and fever. What should the nurse suspect?', '["Thyroid storm", "Agranulocytosis", "Myxoedema", "Hypocalcaemia"]'::jsonb, 1, 'Agranulocytosis (low neutrophils causing sore throat/fever) is the serious, classic side effect to watch for with propylthiouracil/carbimazole.'),
(5, 193, 'Critical Care Scenarios', 'A patient with increased intracranial pressure is being nursed. Which positioning is generally recommended to help reduce ICP?', '["Prone position", "Trendelenburg (head down) position", "Head of bed flat, neck flexed", "Head of bed elevated 30 degrees, head in neutral alignment"]'::jsonb, 3, 'Elevating the head of bed to about 30 degrees with the head in neutral alignment promotes venous drainage and helps reduce intracranial pressure.'),
(5, 194, 'Critical Care Scenarios', 'A patient with methanol or ethylene glycol poisoning is being managed. Which agent competitively inhibits alcohol dehydrogenase and is used as an antidote?', '["Atropine", "Naloxone", "Flumazenil", "Fomepizole (or ethanol as an alternative)"]'::jsonb, 3, 'Fomepizole blocks alcohol dehydrogenase, preventing the metabolism of methanol/ethylene glycol into their toxic metabolites (formic acid / glycolic and oxalic acid); ethanol can be used similarly where fomepizole is unavailable.'),
(5, 195, 'Critical Care Scenarios', 'A patient with tetanus develops trismus (lockjaw) as an early symptom. The nurse understands this occurs because tetanus toxin:', '["Blocks inhibitory neurotransmitters (glycine and GABA), causing sustained, uncontrolled muscle contraction", "Only affects the peripheral sensory nerves", "Directly paralyses the diaphragm first", "Causes generalised sedation"]'::jsonb, 0, 'Tetanus toxin blocks inhibitory neurotransmission (glycine/GABA), removing the normal ''brakes'' on muscle contraction and causing sustained rigidity, classically starting with trismus.'),
(5, 196, 'Critical Care Scenarios', 'A patient with obstructive uropathy from bilateral ureteral stones is treated with nephrostomy tube placement. What immediate postobstructive complication should the nurse monitor for?', '["Post-obstructive diuresis with large fluid and electrolyte losses", "Spontaneous resolution of chronic kidney disease", "Immediate anuria", "Hypertension crisis only"]'::jsonb, 0, 'After relief of urinary tract obstruction, tubules may transiently lose concentrating ability, producing marked post-obstructive diuresis that can cause significant volume and electrolyte depletion if not monitored and replaced.'),
(5, 197, 'Critical Care Scenarios', 'A patient with severe cirrhosis of the liver develops hepatorenal syndrome. Which of the following nursing assessment data would support this?', '["Oliguria and azotemia", "Metabolic alkalosis", "Decreased urinary concentration", "Weight gain of less than 1kg per week"]'::jsonb, 0, 'Oliguria with rising nitrogenous waste (azotaemia) is the hallmark of hepatorenal syndrome.'),
(5, 198, 'Critical Care Scenarios', 'A patient under spinal anaesthesia for a caesarean section develops sudden hypotension and nausea. The nurse should recognise this as likely due to:', '["An allergic reaction requiring adrenaline", "A sign of successful anaesthesia with no action needed", "Sympathetic blockade from the spinal anaesthesia causing vasodilation, typically managed with fluids and/or vasopressors", "Unrelated cardiac disease"]'::jsonb, 2, 'Spinal anaesthesia blocks sympathetic tone, commonly causing vasodilation and hypotension — managed with IV fluids and vasopressors (e.g. phenylephrine/ephedrine) as needed.'),
(5, 199, 'Critical Care Scenarios', 'A patient with severe theophylline toxicity develops refractory seizures and life-threatening arrhythmias. Beyond supportive care and multiple-dose activated charcoal, which additional treatment may be indicated in severe cases?', '["Discontinuation of all monitoring", "Oral rehydration therapy alone", "Induced vomiting", "Haemodialysis or haemoperfusion"]'::jsonb, 3, 'In severe, life-threatening theophylline toxicity with seizures or arrhythmias refractory to supportive measures, extracorporeal removal via haemodialysis or haemoperfusion may be necessary.'),
(5, 200, 'Critical Care Scenarios', 'A patient with a pulmonary artery catheter (PAC) in place develops a persistently wedged waveform. The nurse''s most appropriate immediate action is to:', '["Inflate the balloon further to confirm the wedge", "Ignore it since PAC waveforms fluctuate normally", "Deflate the balloon immediately and reposition/notify the physician, as a permanently wedged catheter risks pulmonary infarction", "Increase the IV fluid rate"]'::jsonb, 2, 'A persistently wedged PAC risks pulmonary artery rupture or infarction — the balloon must be deflated immediately and the catheter position addressed.'),
(6, 1, 'ICU Calculations', 'Amiodarone is given as a 150 mg IV bolus over 10 minutes, followed by a maintenance infusion of 1 mg/min for 6 hours, then 0.5 mg/min for the next 18 hours. What is the total dose of amiodarone infused over the full 24-hour period (including the bolus)?', '["1050 mg", "660 mg", "900 mg", "1200 mg"]'::jsonb, 0, 'Bolus = 150 mg. First phase = 1 mg/min x 360 min = 360 mg. Second phase = 0.5 mg/min x 1080 min = 540 mg. Total = 150 + 360 + 540 = 1050 mg.'),
(6, 2, 'ICU Calculations', 'Diazepam injection is available as 10 mg in 2 mL. The prescription is 7.5 mg. What volume should be given?', '["1.5 mL", "0.8 mL", "2.7 mL", "3 mL"]'::jsonb, 0, 'Volume = (dose wanted ÷ dose in stock) × stock volume = (7.5 ÷ 10) × 2 mL = 1.5 mL.'),
(6, 3, 'ICU Calculations', 'Soluble insulin 50 units is made up to 50 mL with normal saline. The order is 5 units/hour. What rate should be set?', '["20 mL/hr", "2.5 mL/hr", "10 mL/hr", "5 mL/hr"]'::jsonb, 3, 'Concentration = 50 units ÷ 50 mL = 1 unit/mL. Rate = 5 ÷ 1 = 5 mL/hr.'),
(6, 4, 'ICU Calculations', 'Vancomycin is prescribed at 15 mg/kg per dose for a patient weighing 80 kg. What single dose should be given?', '["600 mg", "1,200 mg", "1,350 mg", "1,320 mg"]'::jsonb, 1, 'Dose = 15 mg/kg × 80 kg = 1,200 mg.'),
(6, 5, 'ICU Calculations', 'Using the Parkland formula for a 70 kg patient with 40% TBSA burns, how much fluid should be given in the first 8 hours after the burn?', '["3,733.3 mL", "5,600 mL", "2,800 mL", "11,200 mL"]'::jsonb, 1, 'Total = 4 × 70 × 40 = 11,200 mL. Half is given in the first 8 hours from the time of the burn: 5,600 mL.'),
(6, 6, 'ICU Calculations', 'A patient weighs 55 lb. A drug is prescribed at 10 mg/kg. What dose should be given?', '["113.6 mg", "250 mg", "500 mg", "550 mg"]'::jsonb, 1, 'Convert first: 55 lb ÷ 2.2 = 25 kg. Dose = 10 mg/kg × 25 kg = 250 mg. Using pounds would give a 2.2× overdose.'),
(6, 7, 'ICU Calculations', '500 mL of Hartmann''s solution is prescribed to run over 8 hours using a giving set with a drop factor of 15 drops/mL. What is the correct drip rate?', '["32 drops/min", "16 drops/min", "62 drops/min", "21 drops/min"]'::jsonb, 1, 'Drops/min = (volume × drop factor) ÷ time in minutes = (500 × 15) ÷ (8 × 60) = 7,500 ÷ 480 = 15.62 ≈ 16 drops/min.'),
(6, 8, 'ICU Calculations', 'Dopamine 400 mg is diluted to 250 mL and prescribed at 12 mcg/kg/min for a patient weighing 75 kg. At what rate (mL/hr) should the infusion pump be set?', '["4.5 mL/hr", "0.6 mL/hr", "67.5 mL/hr", "33.8 mL/hr"]'::jsonb, 3, 'Concentration = 400 mg ÷ 250 mL = 1,600 mcg/mL. Dose per hour = 12 mcg × 75 kg × 60 min = 54,000 mcg/hr. Rate = 54,000 ÷ 1,600 = 33.8 mL/hr. Common errors: forgetting × 60 (minutes to hours) or leaving out the weight.'),
(6, 9, 'ICU Calculations', 'Ceftazidime 40 mg/kg/day is prescribed in divided doses every 8 hours for an infant weighing 10 kg. How much is each dose?', '["100 mg", "133.3 mg", "400 mg", "13.3 mg"]'::jsonb, 1, 'Daily dose = 40 mg/kg/day × 10 kg = 400 mg/day. Every 8 hours = 3 doses a day, so each dose = 400 ÷ 3 = 133.3 mg.'),
(6, 10, 'ICU Calculations', 'A patient opens the eyes to voice, is fully orientated and localises to pain. What is the Glasgow Coma Scale score?', '["14/15", "12/15", "13/15", "15/15"]'::jsonb, 2, 'Eyes 3 + Verbal 5 + Motor 5 = 13/15.'),
(6, 11, 'ICU Calculations', 'Heparin 25,000 units in 500 mL is ordered at 800 units/hour. What rate (mL/hr) should be set on the pump?', '["50 mL/hr", "32 mL/hr", "16 mL/hr", "8 mL/hr"]'::jsonb, 2, 'Concentration = 25,000 units ÷ 500 mL = 50 units/mL. Rate = 800 ÷ 50 = 16 mL/hr.'),
(6, 12, 'ICU Calculations', '500 mL of 5% dextrose is prescribed to run over 24 hours using a giving set with a drop factor of 10 drops/mL. What is the correct drip rate?', '["21 drops/min", "6 drops/min", "5 drops/min", "3 drops/min"]'::jsonb, 3, 'Drops/min = (volume × drop factor) ÷ time in minutes = (500 × 10) ÷ (24 × 60) = 5,000 ÷ 1440 = 3.47 ≈ 3 drops/min.'),
(6, 13, 'ICU Calculations', 'A 50 year old patient weighing 60kg with 36% secondary degree burns needs fluid replacement therapy in ICU. Using Parkland formula, calculate the total fluid he will need in 24 hours?', '["4320ml", "8640ml", "2160ml", "12000ml"]'::jsonb, 1, 'Parkland formula: 4 x 60kg x 36% = 8,640ml total over 24 hours.'),
(6, 14, 'ICU Calculations', 'A patient has burns to the anterior trunk, entire right arm, and anterior left leg. Using the Rule of Nines, the TBSA burned is:', '["27%", "54%", "36%", "45%"]'::jsonb, 2, 'Anterior trunk (18%) + right arm (9%) + anterior left leg (9%) = 36%. Anterior leg is 9% (each leg is 18%, so anterior half is 9%).'),
(6, 15, 'ICU Calculations', 'Dobutamine 500 mg is diluted to 250 mL and prescribed at 5 mcg/kg/min for a patient weighing 60 kg. At what rate (mL/hr) should the infusion pump be set?', '["18 mL/hr", "1.5 mL/hr", "9 mL/hr", "0.1 mL/hr"]'::jsonb, 2, 'Concentration = 500 mg ÷ 250 mL = 2,000 mcg/mL. Dose per hour = 5 mcg × 60 kg × 60 min = 18,000 mcg/hr. Rate = 18,000 ÷ 2,000 = 9 mL/hr. Common errors: forgetting × 60 (minutes to hours) or leaving out the weight.'),
(6, 16, 'ICU Calculations', 'How many grams of glucose are in 1000 mL of 10% dextrose?', '["100 g", "50 g", "10,000 g", "1,000 g"]'::jsonb, 0, '10% means 10 g per 100 mL. 1000 mL × 10/100 = 100 g of glucose.'),
(6, 17, 'ICU Calculations', 'A head-injured patient has BP 120/60 mmHg and ICP 35 mmHg. What is the cerebral perfusion pressure (CPP)?', '["25 mmHg", "85 mmHg", "45 mmHg", "115 mmHg"]'::jsonb, 2, 'MAP = (120 + 2 × 60) ÷ 3 ≈ 80 mmHg. CPP = MAP − ICP = 80 − 35 = 45 mmHg, which is too low — below the 60 mmHg target, so cerebral ischaemia is a risk.'),
(6, 18, 'ICU Calculations', 'An adult has burns to the whole left leg, the whole left arm and the head and neck. Using the Rule of Nines, what is the TBSA burned?', '["36%", "40.5%", "45%", "27%"]'::jsonb, 0, 'Rule of Nines (adult): the whole left leg 18% + the whole left arm 9% + the head and neck 9% = 36%.'),
(6, 19, 'ICU Calculations', 'A 90 kg man with 45% TBSA burns arrives 2 hours after the injury and has had no IV fluid. Using the Parkland formula, at what rate should the first half of the fluid run?', '["2,700 mL/hr", "675 mL/hr", "1,350 mL/hr", "1,012.5 mL/hr"]'::jsonb, 2, 'Total = 4 × 90 × 45 = 16,200 mL; half (8,100 mL) is due within 8 hours of the BURN, not of arrival. The patient arrived 2 h after the burn, so 8,100 mL must run over the remaining 6 h = 1,350 mL/hr.'),
(6, 20, 'ICU Calculations', 'Glyceryl trinitrate (nitroglycerin) is mixed as 50 mg in 250 mL D5W and ordered to infuse at 20 mcg/min. What rate should the pump deliver, in mL/hr?', '["3 mL/hr", "24 mL/hr", "6 mL/hr", "12 mL/hr"]'::jsonb, 2, 'Concentration = 50,000 mcg/250 mL = 200 mcg/mL. Rate = 20 mcg/min / 200 mcg/mL = 0.1 mL/min x 60 = 6 mL/hr.'),
(6, 21, 'ICU Calculations', 'An oxygen cylinder contains 460 litres of oxygen. The patient needs 15 L/min during transfer. Approximately how long will it last?', '["About 61 minutes", "About 31 minutes", "About 115 minutes", "About 5 minutes"]'::jsonb, 1, 'Duration = cylinder content ÷ flow = 460 L ÷ 15 L/min = 31 minutes (≈ 0.5 h). Always keep a reserve and check the gauge.'),
(6, 22, 'ICU Calculations', 'A loading dose of phenytoin at 18 mg/kg is ordered for a 70 kg patient. What is the total loading dose in milligrams?', '["1400 mg", "700 mg", "980 mg", "1260 mg"]'::jsonb, 3, 'Dose = 18 mg/kg x 70 kg = 1260 mg.'),
(6, 23, 'ICU Calculations', 'What is the 24-hour maintenance fluid requirement for a child weighing 22 kg (Holliday–Segar method)?', '["1,540 mL", "2,200 mL", "1,100 mL", "1,740 mL"]'::jsonb, 0, 'Holliday–Segar: 100 mL/kg/day for the first 10 kg, 50 mL/kg/day for the next 10 kg, 20 mL/kg/day for each kg above 20. For 22 kg = 1,540 mL/day.'),
(6, 24, 'ICU Calculations', 'Over 24 hours a patient received 2,400 mL IV fluid and 0 mL orally. Output was urine 1,500 mL, nasogastric aspirate 0 mL and wound drain 100 mL. What is the 24-hour fluid balance?', '["+4,000 mL", "+900 mL", "+800 mL", "-800 mL"]'::jsonb, 2, 'Input = IV 2,400 + oral 0 = 2,400 mL. Output = urine 1,500 + NG 0 + drain 100 = 1,600 mL. Balance = 2,400 − 1,600 = +800 mL.'),
(6, 25, 'ICU Calculations', 'Using the 4-2-1 rule, what is the hourly maintenance fluid rate for a child weighing 12 kg?', '["48 mL/hr", "24 mL/hr", "44 mL/hr", "54 mL/hr"]'::jsonb, 2, 'Holliday–Segar (4-2-1 rule): 4 mL/kg/hr for the first 10 kg, 2 mL/kg/hr for the next 10 kg, 1 mL/kg/hr for each kg above 20. For 12 kg = 44 mL/hr.'),
(6, 26, 'ICU Calculations', '1,500 mL of Hartmann''s solution is prescribed to run over 12 hours using a giving set with a drop factor of 10 drops/mL. What is the correct drip rate?', '["21 drops/min", "125 drops/min", "31 drops/min", "42 drops/min"]'::jsonb, 0, 'Drops/min = (volume × drop factor) ÷ time in minutes = (1,500 × 10) ÷ (12 × 60) = 15,000 ÷ 720 = 20.83 ≈ 21 drops/min.'),
(6, 27, 'ICU Calculations', 'Noradrenaline (norepinephrine) 8 mg is diluted to 250 mL and prescribed at 0.15 mcg/kg/min for a patient weighing 60 kg. At what rate (mL/hr) should the infusion pump be set?', '["0.3 mL/hr", "16.9 mL/hr", "33.8 mL/hr", "2.8 mL/hr"]'::jsonb, 1, 'Concentration = 8 mg ÷ 250 mL = 32 mcg/mL. Dose per hour = 0.15 mcg × 60 kg × 60 min = 540 mcg/hr. Rate = 540 ÷ 32 = 16.9 mL/hr. Common errors: forgetting × 60 (minutes to hours) or leaving out the weight.'),
(6, 28, 'ICU Calculations', 'An adrenaline (epinephrine) infusion is mixed as 4 mg in 500 mL D5W and ordered to run at 0.1 mcg/kg/min for a 75 kg patient. What is the correct infusion rate in mL/hr?', '["56.25 mL/hr", "7.5 mL/hr", "112.5 mL/hr", "28.1 mL/hr"]'::jsonb, 0, 'Concentration = 4,000,000 mcg/500 mL = 8 mcg/mL. Dose = 0.1 mcg/kg/min x 75 kg = 7.5 mcg/min. Rate = 7.5/8 = 0.9375 mL/min x 60 = 56.25 mL/hr.'),
(6, 29, 'ICU Calculations', 'Dobutamine 500 mg is diluted to 250 mL and prescribed at 15 mcg/kg/min for a patient weighing 60 kg. At what rate (mL/hr) should the infusion pump be set?', '["4.5 mL/hr", "27 mL/hr", "54 mL/hr", "0.5 mL/hr"]'::jsonb, 1, 'Concentration = 500 mg ÷ 250 mL = 2,000 mcg/mL. Dose per hour = 15 mcg × 60 kg × 60 min = 54,000 mcg/hr. Rate = 54,000 ÷ 2,000 = 27 mL/hr. Common errors: forgetting × 60 (minutes to hours) or leaving out the weight.'),
(6, 30, 'ICU Calculations', 'Glyceryl trinitrate (GTN) 50 mg in 500 mL is ordered at 10 mcg/min. What pump rate (mL/hr) will deliver this dose?', '["12 mL/hr", "3 mL/hr", "0.1 mL/hr", "6 mL/hr"]'::jsonb, 3, 'Concentration = 50 mg in 500 mL = 100 mcg/mL. 10 mcg/min × 60 = 600 mcg/hr. 600 ÷ 100 = 6 mL/hr.'),
(6, 31, 'ICU Calculations', 'Dobutamine 250 mg is diluted to 250 mL and prescribed at 10 mcg/kg/min for a patient weighing 60 kg. At what rate (mL/hr) should the infusion pump be set?', '["72 mL/hr", "36 mL/hr", "0.6 mL/hr", "6 mL/hr"]'::jsonb, 1, 'Concentration = 250 mg ÷ 250 mL = 1,000 mcg/mL. Dose per hour = 10 mcg × 60 kg × 60 min = 36,000 mcg/hr. Rate = 36,000 ÷ 1,000 = 36 mL/hr. Common errors: forgetting × 60 (minutes to hours) or leaving out the weight.'),
(6, 32, 'ICU Calculations', 'Over 24 hours a patient received 2,500 mL IV fluid and 800 mL orally. Output was urine 1,500 mL, nasogastric aspirate 600 mL and wound drain 350 mL. What is the 24-hour fluid balance?', '["+1,800 mL", "+850 mL", "+5,750 mL", "-850 mL"]'::jsonb, 1, 'Input = IV 2,500 + oral 800 = 3,300 mL. Output = urine 1,500 + NG 600 + drain 350 = 2,450 mL. Balance = 3,300 − 2,450 = +850 mL.'),
(6, 33, 'ICU Calculations', '20 mmol of potassium chloride in 500 mL normal saline is prescribed over 4 hours. What is the pump rate and how much potassium is given each hour?', '["125 mL/hr, giving 5 mmol K⁺ per hour", "125 mL/hr, giving 4 mmol K⁺ per hour", "2.1 mL/hr, giving 5 mmol K⁺ per hour", "250 mL/hr, giving 10 mmol K⁺ per hour"]'::jsonb, 0, 'Rate = 500 mL ÷ 4 h = 125 mL/hr. Potassium per hour = 20 mmol ÷ 4 h = 5 mmol/hr (keep ≤ 10 mmol/hr peripherally, on a pump, with cardiac monitoring for faster rates).'),
(6, 34, 'ICU Calculations', 'One litre of IV fluid is to infuse over 10 hours using a macrodrip set with a drop factor of 10 gtt/mL. What is the correct rate in drops per minute?', '["100 gtt/min", "17 gtt/min", "25 gtt/min", "10 gtt/min"]'::jsonb, 1, 'mL/hr = 1000/10 = 100 mL/hr. gtt/min = (100 x 10)/60 = 16.7, rounded to 17 gtt/min.'),
(6, 35, 'ICU Calculations', 'An adult has burns to the whole right leg and the perineum. Using the Rule of Nines, what is the TBSA burned?', '["28%", "23.5%", "19%", "10%"]'::jsonb, 2, 'Rule of Nines (adult): the whole right leg 18% + the perineum 1% = 19%.'),
(6, 36, 'ICU Calculations', 'A patient''s blood pressure is 164/58 mmHg. What is the mean arterial pressure (MAP)?', '["93 mmHg", "129 mmHg", "106 mmHg", "111 mmHg"]'::jsonb, 0, 'MAP = (SBP + 2 × DBP) ÷ 3 = (164 + 2 × 58) ÷ 3 = 280 ÷ 3 ≈ 93 mmHg. A MAP of at least 65 mmHg is the usual target in shock.'),
(6, 37, 'ICU Calculations', '250 mL of normal saline is running at 63 mL/hr. How long will it take to finish?', '["15 h", "4 h 58 min", "3 h 58 min", "3 h 28 min"]'::jsonb, 2, 'Time = volume ÷ rate = 250 ÷ 63 = 3.97 h = 3 h 58 min.'),
(6, 38, 'ICU Calculations', 'Morphine injection is available as 10 mg in 1 mL. The prescription is 2.5 mg. What volume should be given?', '["0.5 mL", "4 mL", "0.25 mL", "0.2 mL"]'::jsonb, 2, 'Volume = (dose wanted ÷ dose in stock) × stock volume = (2.5 ÷ 10) × 1 mL = 0.25 mL.'),
(6, 39, 'ICU Calculations', 'Amoxicillin suspension is available as 250 mg in 5 mL. The prescription is 750 mg. What volume should be given?', '["30 mL", "3 mL", "1.7 mL", "15 mL"]'::jsonb, 3, 'Volume = (dose wanted ÷ dose in stock) × stock volume = (750 ÷ 250) × 5 mL = 15 mL.'),
(6, 40, 'ICU Calculations', 'An oxygen cylinder contains 680 litres of oxygen. The patient needs 4 L/min during transfer. Approximately how long will it last?', '["About 45 minutes", "About 170 minutes", "About 340 minutes", "About 28 minutes"]'::jsonb, 1, 'Duration = cylinder content ÷ flow = 680 L ÷ 4 L/min = 170 minutes (≈ 2.8 h). Always keep a reserve and check the gauge.'),
(6, 41, 'ICU Calculations', 'Norepinephrine is mixed as 4 mg in 250 mL D5W and ordered at 8 mcg/min. What infusion rate in mL/hr should be programmed on the pump?', '["30 mL/hr", "60 mL/hr", "8 mL/hr", "15 mL/hr"]'::jsonb, 0, 'Concentration = 4000 mcg/250 mL = 16 mcg/mL. Rate = 8 mcg/min / 16 mcg/mL = 0.5 mL/min x 60 = 30 mL/hr.'),
(6, 42, 'ICU Calculations', 'Phenobarbital injection is available as 200 mg in 1 mL. The prescription is 150 mg. What volume should be given?', '["1.5 mL", "0.8 mL", "1.3 mL", "0.75 mL"]'::jsonb, 3, 'Volume = (dose wanted ÷ dose in stock) × stock volume = (150 ÷ 200) × 1 mL = 0.75 mL.'),
(6, 43, 'ICU Calculations', 'An adult has burns to the perineum and the whole left arm. Using the Rule of Nines, what is the TBSA burned?', '["14.5%", "10%", "1%", "19%"]'::jsonb, 1, 'Rule of Nines (adult): the perineum 1% + the whole left arm 9% = 10%.'),
(6, 44, 'ICU Calculations', 'A 14 kg child in shock is prescribed a 20 mL/kg bolus of normal saline. What volume should be given?', '["420 mL", "280 mL", "140 mL", "560 mL"]'::jsonb, 1, 'Fluid bolus = 20 mL/kg × 14 kg = 280 mL of isotonic crystalloid, then reassess.'),
(6, 45, 'ICU Calculations', 'An adult has burns to the whole left arm and the whole right leg. Using the Rule of Nines, what is the TBSA burned?', '["31.5%", "36%", "27%", "18%"]'::jsonb, 2, 'Rule of Nines (adult): the whole left arm 9% + the whole right leg 18% = 27%.'),
(6, 46, 'ICU Calculations', '1,000 mL of 5% dextrose is prescribed to run over 12 hours using a giving set with a drop factor of 15 drops/mL. What is the correct drip rate?', '["42 drops/min", "21 drops/min", "28 drops/min", "83 drops/min"]'::jsonb, 1, 'Drops/min = (volume × drop factor) ÷ time in minutes = (1,000 × 15) ÷ (12 × 60) = 15,000 ÷ 720 = 20.83 ≈ 21 drops/min.'),
(6, 47, 'ICU Calculations', 'An adult has burns to the front of the right arm and the front of the left leg. Using the Rule of Nines, what is the TBSA burned?', '["18%", "22.5%", "13.5%", "4.5%"]'::jsonb, 2, 'Rule of Nines (adult): the front of the right arm 4.5% + the front of the left leg 9% = 13.5%.'),
(6, 48, 'ICU Calculations', 'An adult has burns to the front of the right leg, the front of the trunk (chest and abdomen) and the back of the trunk. Using the Rule of Nines, what is the TBSA burned?', '["45%", "36%", "54%", "49.5%"]'::jsonb, 0, 'Rule of Nines (adult): the front of the right leg 9% + the front of the trunk (chest and abdomen) 18% + the back of the trunk 18% = 45%.'),
(6, 49, 'ICU Calculations', 'A 70 kg patient has passed 120 mL of urine in the last 6 hours. What is the urine output and how is it interpreted?', '["20 mL/kg/hr — adequate", "1.71 mL/kg/hr — adequate", "0.29 mL/kg/hr — oliguria", "0.29 mL/kg/hr — adequate"]'::jsonb, 2, 'Urine output = 120 mL ÷ 6 h ÷ 70 kg = 0.29 mL/kg/hr, which is oliguria (< 0.5 mL/kg/hr) — report and assess for hypovolaemia/AKI.'),
(6, 50, 'ICU Calculations', 'Glyceryl trinitrate (GTN) 50 mg in 500 mL is ordered at 15 mcg/min. What pump rate (mL/hr) will deliver this dose?', '["4.5 mL/hr", "9 mL/hr", "18 mL/hr", "0.1 mL/hr"]'::jsonb, 1, 'Concentration = 50 mg in 500 mL = 100 mcg/mL. 15 mcg/min × 60 = 900 mcg/hr. 900 ÷ 100 = 9 mL/hr.'),
(6, 51, 'ICU Calculations', '40 mmol of potassium chloride in 1000 mL normal saline is prescribed over 4 hours. What is the pump rate and how much potassium is given each hour?', '["250 mL/hr, giving 4 mmol K⁺ per hour", "250 mL/hr, giving 10 mmol K⁺ per hour", "4.2 mL/hr, giving 10 mmol K⁺ per hour", "500 mL/hr, giving 20 mmol K⁺ per hour"]'::jsonb, 1, 'Rate = 1000 mL ÷ 4 h = 250 mL/hr. Potassium per hour = 40 mmol ÷ 4 h = 10 mmol/hr (keep ≤ 10 mmol/hr peripherally, on a pump, with cardiac monitoring for faster rates).'),
(6, 52, 'ICU Calculations', 'A patient''s blood pressure is 126/84 mmHg. What is the mean arterial pressure (MAP)?', '["98 mmHg", "112 mmHg", "105 mmHg", "42 mmHg"]'::jsonb, 0, 'MAP = (SBP + 2 × DBP) ÷ 3 = (126 + 2 × 84) ÷ 3 = 294 ÷ 3 ≈ 98 mmHg. A MAP of at least 65 mmHg is the usual target in shock.'),
(6, 53, 'ICU Calculations', 'Using the 4-2-1 rule, what is the hourly maintenance fluid rate for a child weighing 25 kg?', '["100 mL/hr", "50 mL/hr", "75 mL/hr", "65 mL/hr"]'::jsonb, 3, 'Holliday–Segar (4-2-1 rule): 4 mL/kg/hr for the first 10 kg, 2 mL/kg/hr for the next 10 kg, 1 mL/kg/hr for each kg above 20. For 25 kg = 65 mL/hr.'),
(6, 54, 'ICU Calculations', 'A patient weighs 154 lb. A drug is prescribed at 10 mg/kg. What dose should be given?', '["318.2 mg", "1,400 mg", "700 mg", "1,540 mg"]'::jsonb, 2, 'Convert first: 154 lb ÷ 2.2 = 70 kg. Dose = 10 mg/kg × 70 kg = 700 mg. Using pounds would give a 2.2× overdose.'),
(6, 55, 'ICU Calculations', 'A 55 kg man with 30% TBSA burns arrives 3 hours after the injury and has had no IV fluid. Using the Parkland formula, at what rate should the first half of the fluid run?', '["660 mL/hr", "412.5 mL/hr", "275 mL/hr", "1,320 mL/hr"]'::jsonb, 0, 'Total = 4 × 55 × 30 = 6,600 mL; half (3,300 mL) is due within 8 hours of the BURN, not of arrival. The patient arrived 3 h after the burn, so 3,300 mL must run over the remaining 5 h = 660 mL/hr.'),
(6, 56, 'ICU Calculations', 'Using the 4-2-1 rule, what is the hourly maintenance fluid rate for a child weighing 22 kg?', '["44 mL/hr", "72 mL/hr", "62 mL/hr", "88 mL/hr"]'::jsonb, 2, 'Holliday–Segar (4-2-1 rule): 4 mL/kg/hr for the first 10 kg, 2 mL/kg/hr for the next 10 kg, 1 mL/kg/hr for each kg above 20. For 22 kg = 62 mL/hr.'),
(6, 57, 'ICU Calculations', 'Ibuprofen is prescribed at 10 mg/kg per dose (maximum single dose 400 mg) for a patient weighing 70 kg. What single dose should be given?', '["700 mg", "233.3 mg", "400 mg", "770 mg"]'::jsonb, 2, 'Dose = 10 mg/kg × 70 kg = 700 mg, which is above the 400 mg maximum, so give 400 mg.'),
(6, 58, 'ICU Calculations', 'A 90 kg man with 30% TBSA burns arrives 1 hour after the injury and has had no IV fluid. Using the Parkland formula, at what rate should the first half of the fluid run?', '["771.4 mL/hr", "450 mL/hr", "675 mL/hr", "1,542.9 mL/hr"]'::jsonb, 0, 'Total = 4 × 90 × 30 = 10,800 mL; half (5,400 mL) is due within 8 hours of the BURN, not of arrival. The patient arrived 1 h after the burn, so 5,400 mL must run over the remaining 7 h = 771.4 mL/hr.'),
(6, 59, 'ICU Calculations', 'Magnesium sulfate is available as 40 g in 1000 mL. A loading dose of 4 g is ordered to be infused over 20 minutes. How many millilitres are needed, and at what pump rate (mL/hr)?', '["100 mL needed, at a rate of 300 mL/hr", "40 mL needed, at a rate of 120 mL/hr", "400 mL needed, at a rate of 1200 mL/hr", "100 mL needed, at a rate of 200 mL/hr"]'::jsonb, 0, 'Concentration = 40 g/1000 mL = 40 mg/mL. Volume for 4 g (4000 mg) = 4000/40 = 100 mL. To infuse 100 mL in 20 minutes (1/3 hour): rate = 100 / (20/60) = 300 mL/hr.'),
(6, 60, 'Acid–Base Balance & ABG', 'Which acid–base disturbance is most likely to result from the following? Hypokalaemia from diuretics.', '["Respiratory alkalosis", "Metabolic acidosis", "Respiratory acidosis", "Metabolic alkalosis"]'::jsonb, 3, 'Hypokalaemia from diuretics: metabolic alkalosis. Diuretics cause loss of H⁺ and K⁺ and contraction alkalosis.'),
(6, 61, 'Acid–Base Balance & ABG', 'Arterial blood gas for an anxious young woman who is hyperventilating and has tingling around her mouth pH 7.50, PaCO2 22 mmHg, HCO3⁻ 24 mmol/L. What is the correct interpretation?', '["Fully compensated metabolic acidosis", "Uncompensated respiratory acidosis", "Uncompensated respiratory alkalosis", "Partially compensated respiratory alkalosis"]'::jsonb, 2, 'Step 1: pH 7.50 shows alkalaemia (pH > 7.45). Step 2: PaCO2 22 mmHg is low (< 35). Step 3: HCO3⁻ 24 mmol/L is normal (22–26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated respiratory alkalosis. The other value is still normal, so there is no compensation yet.'),
(6, 62, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with severe diarrhoea who has just arrived pH 7.29, PaCO2 42 mmHg, HCO3⁻ 17 mmol/L. What is the correct interpretation?', '["Uncompensated metabolic acidosis", "Fully compensated metabolic acidosis", "Fully compensated respiratory acidosis", "Partially compensated metabolic alkalosis"]'::jsonb, 0, 'Step 1: pH 7.29 shows acidaemia (pH < 7.35). Step 2: PaCO2 42 mmHg is normal (35–45). Step 3: HCO3⁻ 17 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated metabolic acidosis. The other value is still normal, so there is no compensation yet.'),
(6, 63, 'Acid–Base Balance & ABG', 'Sodium bicarbonate during cardiac arrest is most appropriate for:', '["Replacing epinephrine when unavailable", "Routine use in every cardiac arrest to correct acidosis", "Ventricular fibrillation as a first-line agent", "Known severe hyperkalemia or tricyclic antidepressant overdose"]'::jsonb, 3, 'Bicarbonate is not routinely recommended in arrest but has specific indications such as pre-existing severe hyperkalemia or tricyclic antidepressant toxicity, where it can be lifesaving.'),
(6, 64, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient admitted minutes ago after a prolonged seizure pH 7.26, PaCO2 39 mmHg, HCO3⁻ 16 mmol/L. What is the correct interpretation?', '["Uncompensated metabolic acidosis", "Partially compensated respiratory alkalosis", "Partially compensated metabolic acidosis", "Uncompensated respiratory acidosis"]'::jsonb, 0, 'Step 1: pH 7.26 shows acidaemia (pH < 7.35). Step 2: PaCO2 39 mmHg is normal (35–45). Step 3: HCO3⁻ 16 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated metabolic acidosis. The other value is still normal, so there is no compensation yet.'),
(6, 65, 'Acid–Base Balance & ABG', 'A negative base excess (base deficit) on an ABG indicates:', '["Respiratory alkalosis specifically", "A relative excess of bicarbonate/buffer base, consistent with alkalosis", "A relative deficit of buffer base, consistent with a metabolic acidosis component", "Normal acid-base status"]'::jsonb, 2, 'A negative base excess (base deficit) reflects a relative shortage of buffering base in the blood, indicating a metabolic acidosis component.'),
(6, 66, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with COPD admitted with an infective exacerbation pH 7.34, PaCO2 70 mmHg, HCO3⁻ 34 mmol/L. What is the correct interpretation?', '["Uncompensated respiratory alkalosis", "Partially compensated respiratory acidosis", "Uncompensated respiratory acidosis", "Mixed respiratory and metabolic acidosis"]'::jsonb, 1, 'Step 1: pH 7.34 shows acidaemia (pH < 7.35). Step 2: PaCO2 70 mmHg is high (> 45). Step 3: HCO3⁻ 34 mmol/L is high (> 26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives partially compensated respiratory acidosis. The other system is moving in the compensating direction but the pH is still abnormal, so compensation is partial.'),
(6, 67, 'Acid–Base Balance & ABG', 'Results: Na⁺ 141, Cl⁻ 105, HCO3⁻ 14 mmol/L. What is the anion gap and its interpretation?', '["50 mmol/L — raised (high anion gap)", "36 mmol/L — raised (high anion gap)", "22 mmol/L — normal", "22 mmol/L — raised (high anion gap)"]'::jsonb, 3, 'Anion gap = Na⁺ − (Cl⁻ + HCO3⁻) = 141 − (105 + 14) = 22 mmol/L (normal about 8–12). A raised gap suggests MUDPILES causes such as lactic acidosis, ketoacidosis, renal failure or poisoning.'),
(6, 68, 'Acid–Base Balance & ABG', 'Arterial blood gas for an anxious young woman who is hyperventilating and has tingling around her mouth pH 7.51, PaCO2 22 mmHg, HCO3⁻ 24 mmol/L. What is the correct interpretation?', '["Uncompensated respiratory alkalosis", "Partially compensated respiratory acidosis", "Partially compensated metabolic alkalosis", "Partially compensated respiratory alkalosis"]'::jsonb, 0, 'Step 1: pH 7.51 shows alkalaemia (pH > 7.45). Step 2: PaCO2 22 mmHg is low (< 35). Step 3: HCO3⁻ 24 mmol/L is normal (22–26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated respiratory alkalosis. The other value is still normal, so there is no compensation yet.'),
(6, 69, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient admitted minutes ago after a prolonged seizure pH 7.27, PaCO2 39 mmHg, HCO3⁻ 14 mmol/L. What is the correct interpretation?', '["Uncompensated metabolic acidosis", "Fully compensated metabolic acidosis", "Partially compensated respiratory alkalosis", "Uncompensated metabolic alkalosis"]'::jsonb, 0, 'Step 1: pH 7.27 shows acidaemia (pH < 7.35). Step 2: PaCO2 39 mmHg is normal (35–45). Step 3: HCO3⁻ 14 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated metabolic acidosis. The other value is still normal, so there is no compensation yet.'),
(6, 70, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with chronic kidney disease on the renal ward pH 7.36, PaCO2 30 mmHg, HCO3⁻ 14 mmol/L. What is the correct interpretation?', '["Fully compensated metabolic acidosis", "Fully compensated respiratory acidosis", "Uncompensated metabolic alkalosis", "Mixed respiratory and metabolic acidosis"]'::jsonb, 0, 'Step 1: pH 7.36 shows a pH within the normal range (7.35–7.45). Step 2: PaCO2 30 mmHg is low (< 35). Step 3: HCO3⁻ 14 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives fully compensated metabolic acidosis. Both values are abnormal but the pH is back within range, so compensation is full.'),
(6, 71, 'Acid–Base Balance & ABG', 'Arterial blood gas for an anxious young woman who is hyperventilating and has tingling around her mouth pH 7.53, PaCO2 22 mmHg, HCO3⁻ 23 mmol/L. What is the correct interpretation?', '["Partially compensated respiratory alkalosis", "Uncompensated metabolic alkalosis", "Fully compensated respiratory acidosis", "Uncompensated respiratory alkalosis"]'::jsonb, 3, 'Step 1: pH 7.53 shows alkalaemia (pH > 7.45). Step 2: PaCO2 22 mmHg is low (< 35). Step 3: HCO3⁻ 23 mmol/L is normal (22–26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated respiratory alkalosis. The other value is still normal, so there is no compensation yet.'),
(6, 72, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with severe diarrhoea who has just arrived pH 7.26, PaCO2 44 mmHg, HCO3⁻ 14 mmol/L. What is the correct interpretation?', '["Partially compensated respiratory acidosis", "Uncompensated metabolic acidosis", "Fully compensated metabolic acidosis", "Partially compensated respiratory alkalosis"]'::jsonb, 1, 'Step 1: pH 7.26 shows acidaemia (pH < 7.35). Step 2: PaCO2 44 mmHg is normal (35–45). Step 3: HCO3⁻ 14 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated metabolic acidosis. The other value is still normal, so there is no compensation yet.'),
(6, 73, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient on continuous nasogastric suction for 3 days pH 7.56, PaCO2 43 mmHg, HCO3⁻ 36 mmol/L. What is the correct interpretation?', '["Mixed respiratory and metabolic acidosis", "Uncompensated metabolic alkalosis", "Partially compensated metabolic alkalosis", "Fully compensated respiratory acidosis"]'::jsonb, 1, 'Step 1: pH 7.56 shows alkalaemia (pH > 7.45). Step 2: PaCO2 43 mmHg is normal (35–45). Step 3: HCO3⁻ 36 mmol/L is high (> 26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated metabolic alkalosis. The other value is still normal, so there is no compensation yet.'),
(6, 74, 'Acid–Base Balance & ABG', 'A patient with metabolic acidosis has HCO3⁻ 8 mmol/L and PaCO2 20 mmHg. Using Winter''s formula, what does this show?', '["PaCO2 is higher than expected — an added respiratory acidosis", "PaCO2 is lower than expected — an added respiratory alkalosis", "The kidneys are compensating for a respiratory acidosis", "Appropriate respiratory compensation — a pure metabolic acidosis"]'::jsonb, 3, 'Winter''s formula: expected PaCO2 = (1.5 × HCO3⁻) + 8 ± 2 = (1.5 × 8) + 8 = 20 (range 18–22). The measured PaCO2 is 20, so: appropriate respiratory compensation — a pure metabolic acidosis.'),
(6, 75, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with severe pain after a fracture breathing at 32/min pH 7.50, PaCO2 30 mmHg, HCO3⁻ 26 mmol/L. What is the correct interpretation?', '["Uncompensated metabolic acidosis", "Fully compensated respiratory acidosis", "Partially compensated respiratory alkalosis", "Uncompensated respiratory alkalosis"]'::jsonb, 3, 'Step 1: pH 7.50 shows alkalaemia (pH > 7.45). Step 2: PaCO2 30 mmHg is low (< 35). Step 3: HCO3⁻ 26 mmol/L is normal (22–26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated respiratory alkalosis. The other value is still normal, so there is no compensation yet.'),
(6, 76, 'Acid–Base Balance & ABG', 'Arterial blood gas for a post-operative patient still drowsy from anaesthesia with shallow breathing pH 7.29, PaCO2 54 mmHg, HCO3⁻ 25 mmol/L. What is the correct interpretation?', '["Uncompensated metabolic acidosis", "Uncompensated respiratory acidosis", "Fully compensated metabolic acidosis", "Fully compensated respiratory acidosis"]'::jsonb, 1, 'Step 1: pH 7.29 shows acidaemia (pH < 7.35). Step 2: PaCO2 54 mmHg is high (> 45). Step 3: HCO3⁻ 25 mmol/L is normal (22–26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated respiratory acidosis. The other value is still normal, so there is no compensation yet.'),
(6, 77, 'Acid–Base Balance & ABG', 'Results: Na⁺ 138, Cl⁻ 98, HCO3⁻ 10 mmol/L. What is the anion gap and its interpretation?', '["30 mmol/L — raised (high anion gap)", "30 mmol/L — normal", "40 mmol/L — raised (high anion gap)", "50 mmol/L — raised (high anion gap)"]'::jsonb, 0, 'Anion gap = Na⁺ − (Cl⁻ + HCO3⁻) = 138 − (98 + 10) = 30 mmol/L (normal about 8–12). A raised gap suggests MUDPILES causes such as lactic acidosis, ketoacidosis, renal failure or poisoning.'),
(6, 78, 'Acid–Base Balance & ABG', 'Arterial blood gas for an obese patient with obesity hypoventilation syndrome and a chest infection pH 7.34, PaCO2 63 mmHg, HCO3⁻ 33 mmol/L. What is the correct interpretation?', '["Uncompensated respiratory alkalosis", "Uncompensated respiratory acidosis", "Uncompensated metabolic acidosis", "Partially compensated respiratory acidosis"]'::jsonb, 3, 'Step 1: pH 7.34 shows acidaemia (pH < 7.35). Step 2: PaCO2 63 mmHg is high (> 45). Step 3: HCO3⁻ 33 mmol/L is high (> 26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives partially compensated respiratory acidosis. The other system is moving in the compensating direction but the pH is still abnormal, so compensation is partial.'),
(6, 79, 'Acid–Base Balance & ABG', 'Arterial blood gases (ABGs) show respiratory alkalosis, and CO2 is very low that is 25 mm of Hg while on ventilator setting respiratory rate is set at 22b/m. What would you do with respiratory rate?', '["Do not change the rate", "None of them", "Decrease respiratory rate", "Increase respiratory rate"]'::jsonb, 2, 'With CO2 already too low (alkalosis), reducing the respiratory rate lets CO2 rise back toward normal.'),
(6, 80, 'Acid–Base Balance & ABG', 'Arterial blood gas for an anxious young woman who is hyperventilating and has tingling around her mouth pH 7.51, PaCO2 31 mmHg, HCO3⁻ 26 mmol/L. What is the correct interpretation?', '["Partially compensated metabolic alkalosis", "Partially compensated respiratory alkalosis", "Fully compensated metabolic acidosis", "Uncompensated respiratory alkalosis"]'::jsonb, 3, 'Step 1: pH 7.51 shows alkalaemia (pH > 7.45). Step 2: PaCO2 31 mmHg is low (< 35). Step 3: HCO3⁻ 26 mmol/L is normal (22–26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated respiratory alkalosis. The other value is still normal, so there is no compensation yet.'),
(6, 81, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient on continuous nasogastric suction for 3 days pH 7.51, PaCO2 37 mmHg, HCO3⁻ 36 mmol/L. What is the correct interpretation?', '["Partially compensated respiratory acidosis", "Partially compensated metabolic alkalosis", "Uncompensated metabolic acidosis", "Uncompensated metabolic alkalosis"]'::jsonb, 3, 'Step 1: pH 7.51 shows alkalaemia (pH > 7.45). Step 2: PaCO2 37 mmHg is normal (35–45). Step 3: HCO3⁻ 36 mmol/L is high (> 26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated metabolic alkalosis. The other value is still normal, so there is no compensation yet.'),
(6, 82, 'Acid–Base Balance & ABG', 'Arterial blood gas for a ventilated patient whose set rate is too high pH 7.55, PaCO2 26 mmHg, HCO3⁻ 23 mmol/L. What is the correct interpretation?', '["Partially compensated respiratory alkalosis", "Uncompensated respiratory alkalosis", "Uncompensated respiratory acidosis", "Partially compensated metabolic acidosis"]'::jsonb, 1, 'Step 1: pH 7.55 shows alkalaemia (pH > 7.45). Step 2: PaCO2 26 mmHg is low (< 35). Step 3: HCO3⁻ 23 mmol/L is normal (22–26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated respiratory alkalosis. The other value is still normal, so there is no compensation yet.'),
(6, 83, 'Acid–Base Balance & ABG', 'Arterial blood gas for a ventilated patient whose set rate is too high pH 7.53, PaCO2 26 mmHg, HCO3⁻ 25 mmol/L. What is the correct interpretation?', '["Partially compensated respiratory alkalosis", "Mixed respiratory and metabolic acidosis", "Partially compensated metabolic alkalosis", "Uncompensated respiratory alkalosis"]'::jsonb, 3, 'Step 1: pH 7.53 shows alkalaemia (pH > 7.45). Step 2: PaCO2 26 mmHg is low (< 35). Step 3: HCO3⁻ 25 mmol/L is normal (22–26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated respiratory alkalosis. The other value is still normal, so there is no compensation yet.'),
(6, 84, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with chronic kyphoscoliosis who feels well pH 7.36, PaCO2 62 mmHg, HCO3⁻ 34 mmol/L. What is the correct interpretation?', '["Uncompensated respiratory acidosis", "Fully compensated respiratory acidosis", "Fully compensated metabolic acidosis", "Uncompensated respiratory alkalosis"]'::jsonb, 1, 'Step 1: pH 7.36 shows a pH within the normal range (7.35–7.45). Step 2: PaCO2 62 mmHg is high (> 45). Step 3: HCO3⁻ 34 mmol/L is high (> 26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives fully compensated respiratory acidosis. Both values are abnormal but the pH is back within range, so compensation is full.'),
(6, 85, 'Acid–Base Balance & ABG', 'A patient with poorly controlled diabetes presents with fruity breath odor, Kussmaul respirations, and severe hyperglycemia. Kussmaul respirations occur as a compensatory response to which acid-base disturbance?', '["Metabolic alkalosis", "Metabolic acidosis, with deep rapid breathing to blow off CO2 and raise pH", "Respiratory alkalosis", "Respiratory acidosis"]'::jsonb, 1, 'In DKA, accumulation of ketoacids causes a high anion gap metabolic acidosis; Kussmaul respirations (deep, rapid breathing) are the respiratory system''s compensatory attempt to lower PaCO2 and partially correct the acidemia.'),
(6, 86, 'Acid–Base Balance & ABG', 'Results: Na⁺ 140, Cl⁻ 109, HCO3⁻ 10 mmol/L. What is the anion gap and its interpretation?', '["31 mmol/L — raised (high anion gap)", "21 mmol/L — raised (high anion gap)", "21 mmol/L — normal", "41 mmol/L — raised (high anion gap)"]'::jsonb, 1, 'Anion gap = Na⁺ − (Cl⁻ + HCO3⁻) = 140 − (109 + 10) = 21 mmol/L (normal about 8–12). A raised gap suggests MUDPILES causes such as lactic acidosis, ketoacidosis, renal failure or poisoning.'),
(6, 87, 'Acid–Base Balance & ABG', 'A stable patient with severe COPD is likely to show which arterial blood gas pattern at baseline?', '["Marked hypocapnia with elevated pH", "Normal PaCO2 with severe metabolic acidosis", "Acute respiratory alkalosis with low bicarbonate", "Chronic hypercapnia with compensatory elevation of bicarbonate and near-normal pH"]'::jsonb, 3, 'Chronic CO2 retention in advanced COPD is renally compensated over time by bicarbonate retention, producing a near-normal pH despite elevated PaCO2 (compensated respiratory acidosis).'),
(6, 88, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient on high-dose furosemide with a low potassium pH 7.48, PaCO2 51 mmHg, HCO3⁻ 36 mmol/L. What is the correct interpretation?', '["Mixed respiratory and metabolic acidosis", "Partially compensated metabolic alkalosis", "Fully compensated respiratory acidosis", "Uncompensated metabolic alkalosis"]'::jsonb, 1, 'Step 1: pH 7.48 shows alkalaemia (pH > 7.45). Step 2: PaCO2 51 mmHg is high (> 45). Step 3: HCO3⁻ 36 mmol/L is high (> 26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives partially compensated metabolic alkalosis. The other system is moving in the compensating direction but the pH is still abnormal, so compensation is partial.'),
(6, 89, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient just resuscitated from a cardiac arrest pH 7.07, PaCO2 61 mmHg, HCO3⁻ 16 mmol/L. What is the correct interpretation?', '["Partially compensated metabolic acidosis", "Mixed respiratory and metabolic acidosis", "Uncompensated respiratory alkalosis", "Partially compensated metabolic alkalosis"]'::jsonb, 1, 'Step 1: pH 7.07 shows acidaemia (pH < 7.35). Step 2: PaCO2 61 mmHg is high (> 45). Step 3: HCO3⁻ 16 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives mixed respiratory and metabolic acidosis. Both PaCO2 (high) and HCO3⁻ (low) push the pH down together, so it is a mixed acidosis, not compensation.'),
(6, 90, 'Acid–Base Balance & ABG', 'Hypokalemia tends to promote metabolic alkalosis in part because it:', '["Promotes an intracellular shift of hydrogen ions and enhances renal hydrogen ion secretion and ammoniagenesis", "Directly raises plasma bicarbonate through increased dietary intake", "Suppresses aldosterone secretion", "Increases respiratory rate, lowering PaCO2 and directly raising pH"]'::jsonb, 0, 'In hypokalemia, hydrogen ions shift into cells to help maintain electroneutrality, and the kidney increases hydrogen ion secretion and ammoniagenesis, both of which favor development of metabolic alkalosis.'),
(6, 91, 'Acid–Base Balance & ABG', 'Arterial blood gas for a ventilated patient whose set rate is too high pH 7.57, PaCO2 24 mmHg, HCO3⁻ 22 mmol/L. What is the correct interpretation?', '["Partially compensated respiratory alkalosis", "Mixed respiratory and metabolic acidosis", "Uncompensated respiratory alkalosis", "Uncompensated metabolic acidosis"]'::jsonb, 2, 'Step 1: pH 7.57 shows alkalaemia (pH > 7.45). Step 2: PaCO2 24 mmHg is low (< 35). Step 3: HCO3⁻ 22 mmol/L is normal (22–26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated respiratory alkalosis. The other value is still normal, so there is no compensation yet.'),
(6, 92, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient admitted minutes ago after a prolonged seizure pH 7.25, PaCO2 40 mmHg, HCO3⁻ 17 mmol/L. What is the correct interpretation?', '["Fully compensated metabolic acidosis", "Uncompensated metabolic acidosis", "Partially compensated respiratory acidosis", "Partially compensated respiratory alkalosis"]'::jsonb, 1, 'Step 1: pH 7.25 shows acidaemia (pH < 7.35). Step 2: PaCO2 40 mmHg is normal (35–45). Step 3: HCO3⁻ 17 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated metabolic acidosis. The other value is still normal, so there is no compensation yet.'),
(6, 93, 'Acid–Base Balance & ABG', 'Arterial blood gas for an obese patient with obesity hypoventilation syndrome and a chest infection pH 7.30, PaCO2 62 mmHg, HCO3⁻ 31 mmol/L. What is the correct interpretation?', '["Fully compensated respiratory acidosis", "Uncompensated respiratory alkalosis", "Partially compensated metabolic alkalosis", "Partially compensated respiratory acidosis"]'::jsonb, 3, 'Step 1: pH 7.30 shows acidaemia (pH < 7.35). Step 2: PaCO2 62 mmHg is high (> 45). Step 3: HCO3⁻ 31 mmol/L is high (> 26). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives partially compensated respiratory acidosis. The other system is moving in the compensating direction but the pH is still abnormal, so compensation is partial.'),
(6, 94, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient with severe diarrhoea who has just arrived pH 7.30, PaCO2 41 mmHg, HCO3⁻ 18 mmol/L. What is the correct interpretation?', '["Uncompensated metabolic acidosis", "Partially compensated metabolic acidosis", "Uncompensated respiratory acidosis", "Partially compensated respiratory alkalosis"]'::jsonb, 0, 'Step 1: pH 7.30 shows acidaemia (pH < 7.35). Step 2: PaCO2 41 mmHg is normal (35–45). Step 3: HCO3⁻ 18 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated metabolic acidosis. The other value is still normal, so there is no compensation yet.'),
(6, 95, 'Acid–Base Balance & ABG', 'The expected respiratory compensation for metabolic alkalosis is:', '["Hypoventilation, retaining CO2 to help lower pH toward normal", "Immediate renal correction only", "Hyperventilation to blow off more CO2", "No respiratory change occurs"]'::jsonb, 0, 'In metabolic alkalosis, the respiratory system compensates by hypoventilating, retaining CO2 to counterbalance the elevated pH — though this compensation is limited by the resulting hypoxaemia drive.'),
(6, 96, 'Acid–Base Balance & ABG', 'Arterial blood gas for a patient admitted minutes ago after a prolonged seizure pH 7.21, PaCO2 43 mmHg, HCO3⁻ 13 mmol/L. What is the correct interpretation?', '["Uncompensated respiratory alkalosis", "Partially compensated respiratory acidosis", "Uncompensated metabolic acidosis", "Mixed respiratory and metabolic acidosis"]'::jsonb, 2, 'Step 1: pH 7.21 shows acidaemia (pH < 7.35). Step 2: PaCO2 43 mmHg is normal (35–45). Step 3: HCO3⁻ 13 mmol/L is low (< 22). Matching the pH change to the abnormal value(s) (ROME: Respiratory Opposite, Metabolic Equal) gives uncompensated metabolic acidosis. The other value is still normal, so there is no compensation yet.'),
(6, 97, 'Acid–Base Balance & ABG', 'Which condition would result in an elevated anion gap in ABG results?', '["Renal tubular acidosis", "Drug-induced metabolic alkalosis", "Hyperkalemia", "Diabetic ketoacidosis"]'::jsonb, 3, 'Diabetic ketoacidosis adds unmeasured anions (ketoacids), so the anion gap rises. Renal tubular acidosis causes a normal-gap (hyperchloraemic) acidosis.'),
(6, 98, 'Acid–Base Balance & ABG', 'Which acid–base disturbance is most likely to result from the following? Opioid overdose with respiratory depression.', '["Metabolic alkalosis", "Respiratory alkalosis", "Metabolic acidosis", "Respiratory acidosis"]'::jsonb, 3, 'Opioid overdose with respiratory depression: respiratory acidosis. Hypoventilation retains CO2.'),
(6, 99, 'Acid–Base Balance & ABG', 'Results: Na⁺ 140, Cl⁻ 103, HCO3⁻ 14 mmol/L. What is the anion gap and its interpretation?', '["51 mmol/L — raised (high anion gap)", "23 mmol/L — normal", "37 mmol/L — raised (high anion gap)", "23 mmol/L — raised (high anion gap)"]'::jsonb, 3, 'Anion gap = Na⁺ − (Cl⁻ + HCO3⁻) = 140 − (103 + 14) = 23 mmol/L (normal about 8–12). A raised gap suggests MUDPILES causes such as lactic acidosis, ketoacidosis, renal failure or poisoning.'),
(6, 100, 'Mechanical Ventilation', 'A patient with ARDS on mechanical ventilation has a plateau pressure consistently above 30cmH2O. The nurse understands this is concerning because:', '["It has no clinical significance", "It indicates the patient is ready for extubation", "It indicates optimal lung compliance", "It increases the risk of ventilator-induced lung injury (barotrauma), and settings should be adjusted to keep plateau pressure below this threshold"]'::jsonb, 3, 'Sustained plateau pressures above 30cmH2O increase the risk of barotrauma/volutrauma in ARDS — lung-protective ventilation targets keeping plateau pressure below this threshold.'),
(6, 101, 'Mechanical Ventilation', 'A sustained rise in peak and plateau airway pressures unresponsive to suctioning and repositioning should prompt the nurse to:', '["Wait until the next shift to report it", "Simply increase sedation and not report it", "Notify the physician promptly, as this may indicate worsening lung compliance, pneumothorax, or other significant pathology", "Decrease the tidal volume without an order"]'::jsonb, 2, 'Persistent, unexplained rising airway pressures despite basic troubleshooting suggest a significant change in condition requiring prompt physician evaluation.'),
(6, 102, 'Mechanical Ventilation', 'In a mechanically ventilated ICU patient, delivering salbutamol via a metered-dose inhaler with an inline spacer/adapter is generally preferred over a small-volume nebulizer because it:', '["Requires disconnecting the ventilator circuit for each dose", "Delivers a substantially higher total dose of medication", "Is equally effective when administered correctly, with less risk of ventilator circuit contamination", "Cannot be used safely in ventilated patients"]'::jsonb, 2, 'When actuated correctly with proper technique and timing, MDIs with an in-line adapter deliver comparable clinical effect to nebulizers in ventilated patients while reducing circuit disconnections and contamination risk.'),
(6, 103, 'Mechanical Ventilation', 'A female patient with ARDS is 175 cm tall and weighs 101 kg. Using lung-protective ventilation at 8 mL/kg predicted body weight, what tidal volume should be set?', '["About 529 mL", "About 661 mL", "About 396 mL", "About 808 mL"]'::jsonb, 0, 'Predicted (ideal) body weight for a female: 45.5 + 0.91 × (height − 152.4) = 45.5 + 0.91 × 22.6 = 66.1 kg. Tidal volume = 8 mL/kg × 66.1 = 529 mL. Use PREDICTED, not actual (101 kg), weight — lung size depends on height.'),
(6, 104, 'Mechanical Ventilation', 'Which patient characteristic is most predictive of difficult bag-mask ventilation, independent of intubation difficulty?', '["Normal Mallampati score", "Short neck circumference only", "Full dentition", "Obesity (BMI significantly elevated), presence of a beard, or edentulous state"]'::jsonb, 3, 'Predictors of difficult mask ventilation include obesity, a beard (poor mask seal), edentulism (loss of facial/airway support), age, snoring history, and a limited jaw protrusion — features distinct from, though sometimes overlapping with, predictors of difficult laryngoscopy.'),
(6, 105, 'Mechanical Ventilation', 'During a spontaneous breathing trial a patient breathes at 16/min with a tidal volume of 350 mL. What is the rapid shallow breathing index (RSBI)?', '["46 — likely to fail weaning", "46 — likely to wean successfully", "5.6 — likely to fail weaning", "22 — likely to wean successfully"]'::jsonb, 1, 'RSBI = respiratory rate ÷ tidal volume in litres = 16 ÷ 0.35 = 46 breaths/min/L. Below 105 predicts successful weaning; above 105 suggests rapid shallow breathing and likely failure.'),
(6, 106, 'Mechanical Ventilation', 'A ventilated ARDS patient has a plateau pressure of 26 cmH2O and PEEP of 10 cmH2O. What is the driving pressure?', '["26 cmH2O — too high (> 15), increasing the risk of lung injury", "16 cmH2O — within the safe target (≤ 15)", "36 cmH2O — too high (> 15), increasing the risk of lung injury", "16 cmH2O — too high (> 15), increasing the risk of lung injury"]'::jsonb, 3, 'Driving pressure = plateau pressure − PEEP = 26 − 10 = 16 cmH2O. Aim for ≤ 15 cmH2O (and plateau ≤ 30) to protect the lungs.'),
(6, 107, 'Mechanical Ventilation', 'The goal of using LOW tidal volume, LOW rate, and LOW PEEP together in ventilated asthma can be summarised as:', '["Maximising lung volumes at all costs", "Ensuring the patient breathes exactly like a healthy person", "''Less trapping'' — minimising further air trapping and barotrauma", "Achieving the highest possible peak pressures"]'::jsonb, 2, 'Every one of these settings is chosen with the same underlying goal: protecting the already over-inflated lungs from further trapped air and pressure damage.'),
(6, 108, 'Mechanical Ventilation', 'In mechanically ventilated patients, monitoring of peak and plateau airway pressures is important because:', '["Airway pressures have no relationship to lung mechanics", "A rising peak pressure with a normal plateau pressure suggests increased airway resistance, while a rise in both suggests decreased lung/chest wall compliance", "High airway pressures always indicate ventilator malfunction and never reflect patient pathology", "These pressures only need to be checked once per week"]'::jsonb, 1, 'Differentiating a rise in peak pressure alone (suggesting airway resistance issues such as bronchospasm, secretions, or a kinked tube) from a rise in both peak and plateau pressure (suggesting reduced compliance, such as pneumothorax, ARDS, or worsening pulmonary oedema) helps localise the underlying problem.'),
(6, 109, 'Mechanical Ventilation', 'A capnography waveform showing a gradual upsloping/prolonged expiratory phase (shark-fin pattern) in a ventilated patient suggests:', '["Bronchospasm/airway narrowing causing delayed expiratory airflow", "Normal airway function", "Complete ETT obstruction", "Esophageal intubation"]'::jsonb, 0, 'A shark-fin capnography waveform with a prolonged upsloping expiratory phase reflects delayed, uneven expiratory airflow typical of bronchospasm or airway narrowing.'),
(6, 110, 'Mechanical Ventilation', 'The peak pressure alarm is sounding on the ventilator of a client with a recent tracheostomy. What intervention should be done first?', '["Decrease the sensitivity of the alarm", "Suction the client", "Ensure that the connecting tubing is not kinked", "Assess the client''s respiratory status"]'::jsonb, 3, 'Always assess the patient first: a high peak-pressure alarm may mean secretions, biting, bronchospasm, a kinked tube or pneumothorax. If the patient is in distress, ventilate manually while finding the cause.'),
(6, 111, 'Mechanical Ventilation', 'A ventilated patient with bilateral infiltrates on PEEP 10 cmH2O has PaO2 55 mmHg on FiO2 0.4. Using the P/F ratio, how is this classified?', '["Normal oxygenation (no ARDS)", "Severe ARDS", "Mild ARDS", "Moderate ARDS"]'::jsonb, 3, 'P/F ratio = PaO2 ÷ FiO2 = 55 ÷ 0.4 = 138. Berlin definition (with PEEP ≥ 5): mild 201–300, moderate 101–200, severe ≤ 100. So this is Moderate ARDS.'),
(6, 112, 'Mechanical Ventilation', 'Which complication should the ICU nurse monitor for in a mechanically ventilated patient with severe emphysema due to air trapping?', '["Reduced airway resistance", "Hyperkalemia from hyperventilation", "Auto-PEEP (intrinsic PEEP) and breath stacking", "Immediate pulmonary oedema"]'::jsonb, 2, 'Emphysema patients are prone to incomplete exhalation on the ventilator, causing air trapping and auto-PEEP, which can lead to barotrauma and hemodynamic compromise if not recognized.'),
(6, 113, 'Mechanical Ventilation', 'A rising PaCO₂ in an asthmatic patient not yet ventilated is a sign of:', '["Approaching respiratory muscle exhaustion and failure", "A normal, reassuring finding", "Improving ventilation", "Overtreatment with oxygen"]'::jsonb, 0, 'As the respiratory muscles tire from the increased work of breathing, CO2 starts to build up — a late and dangerous sign that ventilatory failure is approaching.'),
(6, 114, 'Mechanical Ventilation', 'A gradual, progressive decrease in EtCO2 over time in a stable-appearing ventilated patient may indicate:', '["Rebreathing", "Hyperthermia", "Bronchospasm", "Hypothermia, hyperventilation, or a developing hypoperfusion state"]'::jsonb, 3, 'Gradual EtCO2 decline can reflect decreased CO2 production from hypothermia, increased minute ventilation from hyperventilation, or a slowly developing perfusion problem.'),
(6, 115, 'Mechanical Ventilation', 'A ventilator is set at 15 breaths/min with an inspiratory time of 0.8 seconds. What is the I:E ratio?', '["1:4", "1:0.8", "4:1", "1:6"]'::jsonb, 0, 'Each breath lasts 60 ÷ 15 = 4 s. Expiratory time = 4 − 0.8 = 3.2 s. I:E = 0.8 : 3.2 = 1:4.'),
(6, 116, 'Mechanical Ventilation', 'A capnography waveform that shows normal morphology but a low, flattened plateau with reduced EtCO2 amplitude in a patient with a large air leak around the tube cuff is explained by:', '["Dilution of exhaled CO2 sample by entrained room air through the leak, falsely lowering the measured EtCO2", "Rebreathing", "Increased CO2 production", "Esophageal intubation"]'::jsonb, 0, 'A significant cuff leak allows room air to mix with exhaled gas at the sampling site, diluting the CO2 concentration and producing a falsely low EtCO2 reading despite adequate underlying ventilation.'),
(6, 117, 'Mechanical Ventilation', 'A ventilated patient has tidal volume 450 mL, plateau pressure 32 cmH2O and PEEP 12 cmH2O. What is the static lung compliance?', '["10.2 mL/cmH2O", "22.5 mL/cmH2O", "14.1 mL/cmH2O", "44.4 mL/cmH2O"]'::jsonb, 1, 'Static compliance = tidal volume ÷ (plateau pressure − PEEP) = 450 ÷ (32 − 12) = 22.5 mL/cmH2O. Normal is about 50–100; low compliance means stiff lungs (e.g. ARDS, pulmonary oedema).'),
(6, 118, 'Mechanical Ventilation', 'A short course of continuous cisatracurium infusion may be used in a patient with severe ARDS and ventilator dyssynchrony because it can:', '["Reduce oxygen consumption and improve ventilator synchrony/lung compliance in carefully selected patients", "Be safely continued indefinitely with no monitoring", "Cure the underlying lung injury", "Eliminate the need for any sedation"]'::jsonb, 0, 'In select patients with severe ARDS, brief neuromuscular blockade can reduce patient-ventilator dyssynchrony and oxygen consumption, potentially improving oxygenation, though it requires close monitoring given the risks of prolonged paralysis.'),
(6, 119, 'Mechanical Ventilation', 'Biting on the endotracheal tube by an inadequately sedated patient can cause acute obstruction. An appropriate intervention includes:', '["Deflating the ETT cuff", "Immediately extubating the patient", "Increasing the ventilator rate", "Inserting a bite block and reassessing sedation/analgesia level"]'::jsonb, 3, 'A bite block protects the tube lumen from occlusion, and reassessing sedation/analgesia addresses the underlying cause of the biting behavior.'),
(6, 120, 'Mechanical Ventilation', 'A female patient with ARDS is 170 cm tall and weighs 97 kg. Using lung-protective ventilation at 6 mL/kg predicted body weight, what tidal volume should be set?', '["About 582 mL", "About 615 mL", "About 369 mL", "About 492 mL"]'::jsonb, 2, 'Predicted (ideal) body weight for a female: 45.5 + 0.91 × (height − 152.4) = 45.5 + 0.91 × 17.6 = 61.5 kg. Tidal volume = 6 mL/kg × 61.5 = 369 mL. Use PREDICTED, not actual (97 kg), weight — lung size depends on height.'),
(6, 121, 'Mechanical Ventilation', 'Which laboratory/clinical finding suggests early ventilator-associated pneumonia in an intubated patient?', '["New or worsening infiltrate on chest x-ray with fever, leukocytosis, and purulent secretions", "Clear chest x-ray with normal WBC", "Decreased secretions and improved oxygenation", "Bradycardia with hypothermia only"]'::jsonb, 0, 'VAP is suggested clinically by a new/worsening infiltrate accompanied by fever, leukocytosis, and purulent tracheal secretions, prompting further diagnostic evaluation.'),
(6, 122, 'Mechanical Ventilation', 'A patient on mechanical ventilation develops sudden increased work of breathing, tachycardia, and diaphoresis but the ventilator is not alarming. The nurse should:', '["Immediately assess the patient directly rather than relying solely on the ventilator display, since clinical status can deteriorate before alarms trigger", "Increase the FiO2 without further assessment", "Assume the ventilator is malfunctioning and disconnect it", "Wait for an alarm to sound before intervening"]'::jsonb, 0, 'Ventilator alarms do not capture every form of clinical deterioration; direct patient assessment takes priority over reliance on machine alarms alone.'),
(6, 123, 'Mechanical Ventilation', 'One of the following modes of ventilation has the risk of the patient getting respiratory alkalosis.', '["Pressure Control Mode", "Assist Control Mode", "Controlled Mandatory Ventilation", "Synchronous Intermittent Mandatory Ventilation"]'::jsonb, 1, 'In Assist-Control every breath the patient triggers gets the full set tidal volume, so a tachypnoeic (anxious, in pain) patient can be over-ventilated, causing respiratory alkalosis.'),
(6, 124, 'Mechanical Ventilation', 'A ventilated patient has a tidal volume of 420 mL and a rate of 24 breaths/min. What is the minute ventilation?', '["17.5 L/min", "12.48 L/min", "10.08 L/min", "100.8 L/min"]'::jsonb, 2, 'Minute ventilation = tidal volume × rate = 420 mL × 24 = 10,080 mL/min = 10.08 L/min (normal about 5–8 L/min).'),
(6, 125, 'Mechanical Ventilation', 'A ventilated patient has tidal volume 480 mL, plateau pressure 22 cmH2O and PEEP 8 cmH2O. What is the static lung compliance?', '["34.3 mL/cmH2O", "21.8 mL/cmH2O", "16 mL/cmH2O", "29.2 mL/cmH2O"]'::jsonb, 0, 'Static compliance = tidal volume ÷ (plateau pressure − PEEP) = 480 ÷ (22 − 8) = 34.3 mL/cmH2O. Normal is about 50–100; low compliance means stiff lungs (e.g. ARDS, pulmonary oedema).'),
(6, 126, 'Mechanical Ventilation', 'A patient with acute respiratory failure is started on noninvasive positive pressure ventilation. Which finding indicates the trial is failing and intubation should be considered?', '["Improved oxygen saturation", "A decreasing respiratory rate toward normal", "Improving mental status", "Worsening acidosis, a rising PaCO2, or hemodynamic instability despite noninvasive ventilation"]'::jsonb, 3, 'Failure to improve gas exchange, worsening acidosis, or hemodynamic/mental status deterioration despite an adequate trial indicates the need to proceed to invasive mechanical ventilation.'),
(6, 127, 'Mechanical Ventilation', 'A ventilated patient who has been sedated and immobile for 10 days is being considered for early mobilisation. The primary rationale is to:', '["Increase the risk of complications", "Reduce ICU-acquired weakness, shorten ventilator days, and speed functional recovery", "Replace the need for any physiotherapy input", "Have no measurable effect on outcomes"]'::jsonb, 1, 'Early mobilisation, when safe, reduces ICU-acquired weakness, can shorten mechanical ventilation duration, and improves longer-term functional recovery.'),
(6, 128, 'Mechanical Ventilation', 'The nurse is assessing an intubated patient''s response to increasing FiO2 from 40% to 60% for a SpO2 of 89%. After 10-15 minutes, SpO2 remains 89%. What should the nurse do next?', '["Discontinue PEEP", "Continue increasing FiO2 indefinitely without further assessment", "Decrease FiO2 back to 40%", "Reassess the patient thoroughly, including breath sounds, secretions, tube position, and hemodynamics, and notify the physician if hypoxemia persists"]'::jsonb, 3, 'Persistent hypoxemia despite increased FiO2 warrants a full reassessment for reversible causes and timely physician notification, since it indicates a significant clinical change.'),
(6, 129, 'Mechanical Ventilation', 'The head of bed for a mechanically ventilated patient should be maintained at what elevation to reduce aspiration and VAP risk, absent contraindications?', '["0-10 degrees", "30-45 degrees", "Flat (supine) at all times", "Trendelenburg position"]'::jsonb, 1, 'Semi-recumbent positioning at 30-45 degrees reduces gastric reflux and aspiration risk, a core element of VAP prevention bundles.'),
(6, 130, 'Mechanical Ventilation', 'What is the most effective strategy to prevent oxygen toxicity in a mechanically ventilated patient?', '["Increase FiO2 progressively regardless of oxygen saturation trends", "Titrate to the lowest FiO2 that maintains an acceptable target oxygen saturation, weaning as tolerated", "Maintain FiO2 at 100% throughout the admission to ensure adequate oxygenation", "Avoid all pulse oximetry and ABG monitoring to reduce patient disturbance"]'::jsonb, 1, 'Using the lowest FiO2 necessary to achieve adequate oxygenation, guided by pulse oximetry and ABG monitoring, and weaning promptly as the patient''s condition allows, minimises the risk of oxygen toxicity while still preventing hypoxaemia.'),
(6, 131, 'Mechanical Ventilation', 'A ventilated patient has a tidal volume of 420 mL and a rate of 16 breaths/min. What is the minute ventilation?', '["6.72 L/min", "67.2 L/min", "8.32 L/min", "26.25 L/min"]'::jsonb, 0, 'Minute ventilation = tidal volume × rate = 420 mL × 16 = 6,720 mL/min = 6.72 L/min (normal about 5–8 L/min).'),
(6, 132, 'Mechanical Ventilation', 'In an intubated patient, an increase in peak inspiratory pressure with an unchanged plateau pressure most likely indicates a problem with:', '["Lung compliance, such as worsening ARDS", "The set FiO2", "The set PEEP", "Airway resistance, such as secretions, bronchospasm, or a kinked tube"]'::jsonb, 3, 'Peak pressure reflects both airway resistance and compliance, while plateau pressure reflects compliance alone; a rise in peak with a stable plateau isolates the problem to increased airway resistance.'),
(6, 133, 'Mechanical Ventilation', 'A ventilator mode where the patient controls their own respiratory rate and tidal volume with only pressure support and PEEP applied is best described as:', '["Pressure Support Ventilation, often combined with CPAP", "Assist-Control", "SIMV with 100% mandatory rate", "Pressure Control Ventilation with a fixed rate"]'::jsonb, 0, 'Pressure Support Ventilation provides only inspiratory pressure assistance to spontaneous breaths, with the patient determining their own rate and, to an extent, tidal volume.'),
(6, 134, 'Mechanical Ventilation', 'A curare cleft, a small notch or dip during the alveolar plateau of the capnogram in a mechanically ventilated patient, typically represents:', '["The patient''s spontaneous inspiratory effort occurring during a mandatory ventilator breath, suggesting inadequate paralysis or ventilator asynchrony", "Complete airway obstruction", "A ventilator malfunction requiring immediate circuit replacement", "Esophageal intubation"]'::jsonb, 0, 'A curare cleft appears when a partially paralyzed or spontaneously breathing patient makes an inspiratory effort during the mandatory breath''s alveolar plateau, indicating incomplete neuromuscular blockade.'),
(6, 135, 'Mechanical Ventilation', 'A male patient with ARDS is 160 cm tall and weighs 82 kg. Using lung-protective ventilation at 8 mL/kg predicted body weight, what tidal volume should be set?', '["About 455 mL", "About 341 mL", "About 656 mL", "About 569 mL"]'::jsonb, 0, 'Predicted (ideal) body weight for a male: 50 + 0.91 × (height − 152.4) = 50 + 0.91 × 7.6 = 56.9 kg. Tidal volume = 8 mL/kg × 56.9 = 455 mL. Use PREDICTED, not actual (82 kg), weight — lung size depends on height.'),
(6, 136, 'Mechanical Ventilation', 'Hypoxaemia caused by true intrapulmonary shunt (blood perfusing completely unventilated alveoli) typically:', '["Corrects readily with modest increases in FiO2", "Occurs only with hypoventilation", "Responds poorly to supplemental oxygen because shunted blood never contacts ventilated alveoli", "Is unaffected by PEEP"]'::jsonb, 2, 'Because shunted blood bypasses ventilated alveoli entirely, increasing FiO2 does little to raise its oxygen content, distinguishing shunt from V/Q mismatch, which does improve with supplemental oxygen.'),
(6, 137, 'Mechanical Ventilation', 'Initial management of hypoxia in a critically ill anaesthetized or ventilated patient should begin with:', '["Sedation to reduce oxygen demand", "Diuretic administration", "Immediate intubation regardless of the cause", "Ensuring airway patency and delivering a high fraction of inspired oxygen while identifying the underlying cause"]'::jsonb, 3, 'The first priority in hypoxia is to secure the airway and maximize oxygen delivery (e.g., 100% oxygen) while rapidly assessing for and treating the underlying cause, such as obstruction, hypoventilation, or shunt.'),
(6, 138, 'Mechanical Ventilation', 'A sudden, sustained loss of the capnography waveform in an intubated, mechanically ventilated patient most urgently suggests:', '["A need to increase sedation only", "Accidental extubation, tube dislodgement, or complete airway/circuit disconnection requiring immediate assessment", "A benign, expected finding requiring no action", "Improvement in the patient''s respiratory status"]'::jsonb, 1, 'Sudden loss of the CO2 waveform is a medical emergency suggesting the tube is no longer in the trachea, is completely obstructed, or the circuit is disconnected, and demands immediate assessment and intervention.'),
(6, 139, 'Mechanical Ventilation', 'When assessing a mechanically ventilated patient''s readiness for a spontaneous breathing trial, the nurse should confirm:', '["The patient requires increasing FiO2", "The patient is deeply sedated", "Hemodynamic stability, adequate oxygenation on minimal support, and the ability to initiate spontaneous breaths", "The patient has a fever"]'::jsonb, 2, 'Spontaneous breathing trial readiness criteria typically include hemodynamic stability, adequate oxygenation on low FiO2 and PEEP, and adequate mentation without excessive sedation.'),
(6, 140, 'Mechanical Ventilation', 'In Volume Control ventilation, a form of AC, if a patient''s airway resistance suddenly increases from bronchospasm, what happens to peak airway pressure?', '["It decreases", "The ventilator stops delivering volume", "It increases, since the set volume is delivered regardless of resistance", "It remains constant"]'::jsonb, 2, 'In volume-controlled ventilation, the ventilator delivers the preset tidal volume regardless of resistance changes, so increased resistance results in higher peak and plateau pressures.'),
(6, 141, 'Mechanical Ventilation', 'A low-pressure or low-exhaled-volume alarm on the ventilator most often signals:', '["A leak or disconnection in the ventilator circuit or cuff", "Breath stacking", "Bronchospasm", "Mucus plugging"]'::jsonb, 0, 'Low-pressure alarms typically indicate a leak, such as circuit disconnection, a cuff leak, or partial extubation, resulting in loss of delivered volume or pressure.'),
(6, 142, 'Mechanical Ventilation', 'A ventilated patient with bilateral infiltrates on PEEP 10 cmH2O has PaO2 75 mmHg on FiO2 0.3. Using the P/F ratio, how is this classified?', '["Moderate ARDS", "Normal oxygenation (no ARDS)", "Mild ARDS", "Severe ARDS"]'::jsonb, 2, 'P/F ratio = PaO2 ÷ FiO2 = 75 ÷ 0.3 = 250. Berlin definition (with PEEP ≥ 5): mild 201–300, moderate 101–200, severe ≤ 100. So this is Mild ARDS.'),
(6, 143, 'Mechanical Ventilation', 'A patient on mechanical ventilation for ARDS is being managed with low tidal volumes (around 6ml/kg predicted body weight). The rationale for this strategy is primarily to:', '["Maximise oxygen delivery regardless of pressure", "Increase patient comfort only", "Reduce the work of the ventilator motor", "Minimise ventilator-induced lung injury (volutrauma/barotrauma) in already-injured lungs"]'::jsonb, 3, 'Lung-protective ventilation with low tidal volumes reduces overdistension and ventilator-induced lung injury in the already-damaged lungs of ARDS patients.'),
(6, 144, 'Mechanical Ventilation', 'EtCO2 monitoring benefits nursing assessment of a ventilated patient''s dead space and ventilation efficiency because:', '["It is only useful for confirming tube placement", "It directly measures anatomic dead space volume", "A widened gradient between PaCO2 and EtCO2 can indicate increased alveolar dead space, such as from pulmonary embolism, hypoperfusion, or hyperinflation", "It has no relationship to dead space"]'::jsonb, 2, 'An abnormally widened PaCO2-EtCO2 gradient suggests increased alveolar dead space, seen in pulmonary embolism, low cardiac output states, or hyperinflation with high PEEP.'),
(6, 145, 'Critical Care Scenarios', 'A patient with long-standing hypertension and diabetes has an eGFR of 25 mL/min/1.73m2 sustained for over three months. This is classified as:', '["Nephrotic syndrome", "Chronic kidney disease stage 4", "Acute kidney injury", "Chronic kidney disease stage 2"]'::jsonb, 1, 'An eGFR of 15-29 mL/min/1.73m2 sustained for more than three months meets criteria for CKD stage 4, severely decreased kidney function.'),
(6, 146, 'Critical Care Scenarios', 'A critically ill patient presents with severe tachycardia, fever, agitation, and altered mental status after recent thyroid surgery. Which life-threatening endocrine emergency should be suspected?', '["Addisonian crisis", "Myxedema coma", "Thyroid storm (thyrotoxic crisis)", "Hypoparathyroid tetany"]'::jsonb, 2, 'Thyroid storm is a life-threatening exacerbation of hyperthyroidism, often precipitated by surgery, infection, or trauma, presenting with hyperthermia, tachyarrhythmia, agitation/delirium, and can progress to cardiovascular collapse.'),
(6, 147, 'Critical Care Scenarios', 'A patient presents with a decreased level of consciousness, and the treating team suspects a mixed sedative overdose. Which initial assessment priority takes precedence over identifying the specific substance ingested?', '["Obtaining a detailed history of exactly what was ingested and when", "Sending blood for a full toxicology screen before any intervention", "Airway, breathing, and circulation (ABCs) with immediate stabilisation of any compromise", "Contacting the patient''s next of kin for consent"]'::jsonb, 2, 'In any overdose or poisoning, securing and supporting the airway, breathing, and circulation always takes priority over identifying the specific toxin, as untreated ABC compromise is the most immediate threat to life.'),
(6, 148, 'Critical Care Scenarios', 'A patient with chronic kidney disease receiving erythropoietin therapy for anaemia should also have which nutrient supplemented to ensure the therapy is effective?', '["Calcium only", "Vitamin A", "Iron, since adequate iron stores are needed for erythropoietin to be effective", "Vitamin C only"]'::jsonb, 2, 'Erythropoietin stimulates red cell production, but adequate iron stores are required to support this — iron deficiency can blunt the response to erythropoietin therapy.'),
(6, 149, 'Critical Care Scenarios', 'A patient with severe sepsis has a central venous oxygen saturation (ScvO2) that is persistently low despite fluid resuscitation. This finding suggests:', '["Complete resolution of shock", "No clinical significance", "An imbalance between oxygen delivery and tissue oxygen demand/consumption, prompting further optimisation of resuscitation", "Excellent tissue oxygen delivery relative to demand"]'::jsonb, 2, 'A persistently low ScvO2 suggests inadequate oxygen delivery relative to tissue demand, prompting reassessment and further optimisation of the resuscitation strategy (fluids, haemoglobin, cardiac output).'),
(6, 150, 'Critical Care Scenarios', 'A patient with suspected active pulmonary tuberculosis is admitted to a general ward by mistake. The priority nursing action is to:', '["Simply close the patient''s door with no other change", "Leave the patient where they are with no changes", "Discharge the patient immediately", "Move the patient to a negative-pressure isolation room and initiate airborne precautions with N95 respirators for staff"]'::jsonb, 3, 'Suspected active TB requires prompt transfer to airborne (negative-pressure) isolation with fit-tested N95 respirator use by staff, given its airborne transmission route.'),
(6, 151, 'Critical Care Scenarios', 'A patient on long-term oral amiodarone should be monitored for which combination of toxicities?', '["Ototoxicity, nephrotoxicity, and red man syndrome", "Serotonin syndrome, tendon rupture, and QT shortening", "Pulmonary fibrosis, thyroid dysfunction, and hepatotoxicity", "Adrenal suppression, hypoglycemia, and priapism"]'::jsonb, 2, 'Amiodarone''s iodine-containing structure and long half-life predispose to pulmonary fibrosis, thyroid dysfunction, hepatotoxicity, and corneal microdeposits with chronic use.'),
(6, 152, 'Critical Care Scenarios', 'A patient with severe hypokalaemia (potassium 2.5mmol/L) is prescribed IV potassium replacement. The nurse''s priority safety consideration is to:', '["Give it as a rapid IV push for fastest correction", "Ensure it is properly diluted, infused slowly via pump, with continuous cardiac monitoring", "Skip cardiac monitoring since potassium replacement is always safe", "Give it intramuscularly instead"]'::jsonb, 1, 'IV potassium must always be diluted and infused slowly with cardiac monitoring, since rapid/undiluted administration risks fatal arrhythmias.'),
(6, 153, 'Critical Care Scenarios', 'A patient recovering from DKA treatment develops cerebral oedema, a rare but serious complication most associated with:', '["No relationship to treatment rate", "Overly rapid correction of hyperglycaemia and fluid shifts, particularly in paediatric patients", "Undertreatment of DKA", "Slow, careful correction of fluids and glucose"]'::jsonb, 1, 'Cerebral oedema, a rare but serious DKA treatment complication (especially in children), is associated with overly rapid correction of hyperglycaemia and osmotic shifts — gradual correction is recommended.'),
(6, 154, 'Critical Care Scenarios', 'A patient''s oxygen saturation probe consistently reads falsely low despite the patient appearing clinically well. The nurse should first consider:', '["Ignoring the reading entirely with no clinical correlation", "Immediately intubating the patient", "Technical causes such as poor peripheral perfusion, nail polish, motion artefact, or probe malposition before assuming true hypoxaemia", "Assuming the reading is always accurate with no further check"]'::jsonb, 2, 'Pulse oximetry can be affected by technical factors like poor perfusion, nail polish, or motion — these should be considered and corrected before assuming the reading reflects true hypoxaemia, though clinical correlation is always needed.'),
(6, 155, 'Critical Care Scenarios', 'A patient''s surgical wound shows increasing redness, warmth, and purulent discharge on post-operative day 4, with a fever of 38.6°C. The nurse should suspect:', '["Surgical site infection, requiring assessment, wound culture, and physician notification", "A drug reaction", "No clinical significance", "Normal wound healing"]'::jsonb, 0, 'Increasing redness, warmth, purulent discharge and fever are classic signs of surgical site infection requiring prompt assessment and reporting.'),
(6, 156, 'Critical Care Scenarios', 'A patient receiving unfractionated heparin for PE has an aPTT of 110 seconds. What is the priority nursing action?', '["Continue the infusion unchanged, as this is therapeutic", "Administer protamine sulfate immediately without an order", "Increase the heparin infusion rate", "Hold or slow the infusion per protocol and notify the physician"]'::jsonb, 3, 'An aPTT of 110 seconds is supratherapeutic and increases bleeding risk; the infusion should be held/adjusted per protocol and the physician notified.'),
(6, 157, 'Critical Care Scenarios', 'A patient post-thyroidectomy develops perioral tingling and a positive Chvostek''s sign. This suggests:', '["A wound infection", "Hypocalcaemia from parathyroid gland disturbance during surgery", "Hyperkalaemia", "Normal recovery with no concern"]'::jsonb, 1, 'Perioral tingling and a positive Chvostek''s sign suggest hypocalcaemia, a recognised complication when the parathyroid glands are disturbed during thyroid surgery.'),
(6, 158, 'Critical Care Scenarios', 'A patient with a head injury has a Glasgow Coma Scale score of 10. This is classified as which severity of traumatic brain injury?', '["Severe", "Vegetative state", "Moderate", "Mild"]'::jsonb, 2, 'A GCS of 9-12 is classified as moderate traumatic brain injury, between mild (13-15) and severe (3-8).'),
(6, 159, 'Critical Care Scenarios', 'A patient with severe upper GI bleeding is given a proton pump inhibitor (PPI) infusion. The rationale for this treatment is that PPIs:', '["Have no role in acute GI bleeding management", "Raise gastric pH, which stabilises clot formation and reduces rebleeding risk from peptic ulcers", "Are used only for long-term prevention, never in acute bleeding", "Directly stop active arterial bleeding without any other intervention"]'::jsonb, 1, 'PPIs raise gastric pH, which stabilises clots at the bleeding site and reduces the risk of rebleeding from peptic ulcer disease, complementing endoscopic treatment.'),
(6, 160, 'Critical Care Scenarios', 'A patient with myasthenia gravis in a myasthenic crisis presents with worsening muscle weakness and respiratory difficulty. The priority nursing concern is:', '["Nutritional intake only", "Close monitoring of respiratory status/vital capacity, with readiness for ventilatory support", "Skin integrity only", "Pain management only"]'::jsonb, 1, 'Myasthenic crisis can rapidly progress to respiratory failure from severe muscle weakness, making respiratory monitoring and readiness for ventilatory support the priority.'),
(6, 161, 'Critical Care Scenarios', 'A patient sustains a rotational acceleration-deceleration injury in a high-speed motor vehicle collision. The initial CT is normal, but the patient remains comatose for several days. Which type of head injury is most consistent with this presentation?', '["Concussion", "Depressed skull fracture", "Diffuse axonal injury", "Epidural hematoma"]'::jsonb, 2, 'Diffuse axonal injury results from shearing forces on axons during rapid rotational acceleration-deceleration; CT is often initially normal despite severe, prolonged unconsciousness.'),
(6, 162, 'Critical Care Scenarios', 'A patient with sepsis presenting with a CVP of 9mmHg (slightly elevated) should be interpreted with caution because:', '["CVP is irrelevant in sepsis", "Sepsis can present with low, normal, OR high CVP", "Sepsis always causes low CVP", "A CVP of 9 always confirms fluid overload"]'::jsonb, 1, 'Unlike straightforward hypovolaemia, sepsis is unpredictable and its CVP reading must be interpreted alongside the full clinical picture.'),
(6, 163, 'Critical Care Scenarios', 'A patient with severe Mendelson''s syndrome develops worsening bilateral infiltrates, refractory hypoxaemia, and reduced lung compliance over 24-48 hours. This most likely represents progression to which complication?', '["Bronchiectasis", "Acute respiratory distress syndrome (ARDS)", "Pulmonary embolism", "Chronic bronchitis"]'::jsonb, 1, 'Severe chemical lung injury from aspiration can progress to ARDS, characterised by bilateral infiltrates, refractory hypoxaemia, and decreased lung compliance from diffuse alveolar damage.'),
(6, 164, 'Critical Care Scenarios', 'A patient presents with poisoning after ingesting rodenticide containing a long-acting anticoagulant (superwarfarin). What is the appropriate treatment if bleeding or a significantly elevated INR develops?', '["A single dose of naloxone", "Immediate whole blood transfusion regardless of INR", "Activated charcoal alone, with no other treatment", "Vitamin K1, with prolonged (potentially weeks-long) therapy due to the long half-life of superwarfarins"]'::jsonb, 3, 'Superwarfarin rodenticides have a very long half-life and can cause prolonged coagulopathy; vitamin K1 is the antidote, often required for weeks with close INR monitoring after significant ingestion.'),
(6, 165, 'Critical Care Scenarios', 'A patient with an inferior wall MI should be monitored closely for which complication, due to the shared blood supply from the right coronary artery?', '["Pulmonary embolism", "Right ventricular infarction and bradyarrhythmias/heart block", "Isolated left bundle branch block", "Anterior wall extension"]'::jsonb, 1, 'The right coronary artery supplies both the inferior wall and, commonly, the AV node and RV, explaining the association with RV infarction and conduction blocks.'),
(6, 166, 'Critical Care Scenarios', 'A patient with severe hyperglycaemia and altered mental status but minimal ketosis and a blood glucose of 45mmol/L is most likely experiencing:', '["Diabetic ketoacidosis (DKA)", "Hypoglycaemia", "Normal glucose variation", "Hyperglycaemic Hyperosmolar State (HHS)"]'::jsonb, 3, 'Very high glucose with altered mental status but minimal ketosis is characteristic of HHS, typically seen in type 2 diabetes, distinct from the significant ketosis of DKA.'),
(6, 167, 'Critical Care Scenarios', 'A patient 3 days post-MI develops a new holosystolic murmur, hypotension, and acute pulmonary edema. This presentation is most consistent with:', '["Papillary muscle rupture causing acute mitral regurgitation", "Deep vein thrombosis", "Stable angina", "Pericarditis"]'::jsonb, 0, 'Papillary muscle rupture is a mechanical complication of MI producing acute severe mitral regurgitation, a new murmur, and sudden hemodynamic collapse.'),
(6, 168, 'Critical Care Scenarios', 'A patient develops a temperature of 39.5 degrees C with tachycardia and jaw muscle rigidity shortly after induction with succinylcholine. What should the nurse suspect first?', '["A routine post-operative fever, so paracetamol alone should be given", "Nothing abnormal; reassess again in 4 hours", "Malignant hyperthermia, and the MH protocol should be initiated immediately", "The jaw rigidity means more succinylcholine is needed to relax the muscle"]'::jsonb, 2, 'Tachycardia, rising temperature, and masseter/jaw rigidity occurring soon after a triggering agent is a hallmark presentation of malignant hyperthermia and demands immediate recognition and protocol activation, not more succinylcholine.'),
(6, 169, 'Critical Care Scenarios', 'A patient with acute pancreatitis develops Grey Turner''s sign (flank bruising). This finding suggests:', '["Retroperitoneal haemorrhage, associated with severe pancreatitis", "A benign, unrelated skin condition", "A localised allergic reaction", "Improved prognosis"]'::jsonb, 0, 'Grey Turner''s sign (flank ecchymosis) reflects retroperitoneal bleeding and is associated with severe, haemorrhagic pancreatitis, a poor prognostic sign.'),
(6, 170, 'Critical Care Scenarios', 'A patient with end-stage renal disease who missed a scheduled dialysis session presents with tall peaked T waves on ECG and a serum potassium of 7.2 mEq/L. In addition to emergent pharmacologic treatment, which nursing action is highest priority?', '["Encourage oral intake of a high-potassium meal", "Continuous cardiac monitoring and preparation for emergent dialysis", "Administer a potassium supplement", "Delay treatment until the next routinely scheduled dialysis session"]'::jsonb, 1, 'Severe hyperkalemia with ECG changes is a medical emergency requiring continuous cardiac monitoring, immediate temporizing pharmacologic treatment, and expedited emergent dialysis to remove the excess potassium definitively.'),
(6, 171, 'Critical Care Scenarios', 'A patient with flash pulmonary oedema secondary to a hypertensive emergency should receive which class of medication as a primary intervention?', '["IV vasodilators (e.g., nitroglycerin, nitroprusside) to rapidly reduce afterload", "IV antibiotics", "Oral ACE inhibitors", "Beta-blockers to slow heart rate"]'::jsonb, 0, 'Flash pulmonary oedema from a hypertensive crisis is treated with rapid-acting IV vasodilators to reduce afterload and pulmonary venous pressure quickly.'),
(6, 172, 'Critical Care Scenarios', 'A patient with significant renal impairment receiving morphine is at increased risk of prolonged sedation and respiratory depression due to:', '["Reduced protein binding of morphine", "Enhanced renal clearance of morphine", "Increased hepatic first-pass metabolism", "Accumulation of the active metabolite morphine-6-glucuronide"]'::jsonb, 3, 'Morphine''s active metabolite morphine-6-glucuronide is renally eliminated and can accumulate in renal impairment, prolonging opioid effects including sedation and respiratory depression.'),
(6, 173, 'Critical Care Scenarios', 'A patient on haemodialysis develops hypotension, cramping, and nausea during the session. The nurse''s priority action is to:', '["Ignore symptoms since they are expected", "Increase the ultrafiltration rate to relieve symptoms faster", "Slow or stop ultrafiltration, position the patient appropriately, and consider a fluid bolus per protocol", "Immediately terminate dialysis access permanently"]'::jsonb, 2, 'Intradialytic hypotension is managed by reducing/stopping ultrafiltration, repositioning, and often giving a small fluid bolus, rather than escalating fluid removal.'),
(6, 174, 'Critical Care Scenarios', 'A patient with a chronic spinal cord injury at T4 develops a sudden pounding headache, severe hypertension, profuse sweating and flushing above the injury level, and bradycardia after their urinary catheter becomes blocked. This presentation is most consistent with', '["spinal shock", "a simple tension headache", "Cushing''s triad from raised intracranial pressure", "autonomic dysreflexia"]'::jsonb, 3, 'Autonomic dysreflexia occurs in patients with SCI at or above T6, triggered by a noxious stimulus below the injury level (commonly bladder distention); it causes an unopposed sympathetic surge below the lesion, producing severe hypertension, reflex bradycardia, and flushing/sweating above the lesion, and is a medical emergency.'),
(6, 175, 'Critical Care Scenarios', 'A patient''s ECG shows ST-segment depression in the anterior leads during an episode of chest pain, which resolves when the pain resolves. This pattern most likely represents:', '["Normal variant with no clinical significance", "Old, resolved myocardial infarction with no current significance", "Ventricular hypertrophy only", "Myocardial ischaemia"]'::jsonb, 3, 'Transient ST depression correlating with chest pain onset and resolution is a hallmark of myocardial ischaemia.'),
(6, 176, 'Critical Care Scenarios', 'A post-nephrectomy patient''s hourly urine output drops significantly with a rising heart rate and falling blood pressure. The nurse should first suspect:', '["Hypovolaemia/bleeding, requiring urgent assessment and fluid resuscitation", "A urinary tract infection", "Normal recovery with no action needed", "Overhydration"]'::jsonb, 0, 'Falling urine output with rising heart rate and falling blood pressure post-nephrectomy suggests hypovolaemia, potentially from bleeding, requiring urgent assessment.'),
(6, 177, 'Critical Care Scenarios', 'A postoperative patient experiences sudden onset of severe chest pain and shortness of breath. The nurse suspects:', '["Infection", "Pneumonia", "Heart failure", "Pulmonary embolism"]'::jsonb, 3, 'Sudden pleuritic chest pain with breathlessness after surgery is pulmonary embolism until proved otherwise — immobility and surgery are major risk factors.'),
(6, 178, 'Critical Care Scenarios', 'A patient is witnessed to regurgitate and aspirate during induction of anaesthesia. What is the immediate first step?', '["Administer a full dose of intravenous antibiotics before any airway intervention", "Delay any intervention until a chest X-ray confirms aspiration", "Place the patient head-down in the lateral position and suction the airway immediately", "Perform saline lavage of the trachea to dilute the acid"]'::jsonb, 2, 'Immediate head-down lateral positioning and suctioning helps clear the airway and limits further tracheobronchial soiling; antibiotics and imaging are not the first priority and saline lavage can worsen spread of acid into the lung.'),
(6, 179, 'Critical Care Scenarios', 'A patient two hours post-laparoscopic nephrectomy reports shoulder tip pain. The nurse should recognize this as most likely related to:', '["Myocardial infarction", "Renal colic", "Residual carbon dioxide gas used for pneumoperitoneum during laparoscopy, irritating the diaphragm", "Wound infection"]'::jsonb, 2, 'Referred shoulder pain after laparoscopic surgery is a common, expected finding caused by retained CO2 gas irritating the diaphragm and phrenic nerve; it typically resolves within 24-48 hours with ambulation and mild analgesia.'),
(6, 180, 'Critical Care Scenarios', 'A patient with acute kidney injury develops a serum potassium of 6.8mmol/L with peaked T-waves on ECG. The priority nursing action is to:', '["Administer a potassium supplement", "Encourage the patient to eat a banana", "Wait for the next scheduled blood draw to confirm", "Alert the physician immediately and prepare for urgent treatment (e.g. calcium gluconate, insulin/dextrose)"]'::jsonb, 3, 'Severe hyperkalaemia with ECG changes is a medical emergency requiring immediate treatment to stabilise the myocardium and shift potassium intracellularly.'),
(6, 181, 'Critical Care Scenarios', 'A patient develops fever, tachycardia, tachypnoea, and hypotension not responding to an initial fluid bolus, with a known urinary tract infection. This presentation is most consistent with:', '["Septic shock", "Cardiogenic shock", "Simple dehydration", "Anxiety attack"]'::jsonb, 0, 'Fever with hypotension refractory to fluids in the setting of a known infection source is consistent with septic shock, requiring urgent sepsis bundle management.'),
(6, 182, 'Critical Care Scenarios', 'A patient with sedative-hypnotic (e.g., barbiturate or benzodiazepine) overdose typically presents with which combination of findings?', '["Hypertension and tachyarrhythmia", "Excessive salivation and muscle fasciculations", "Agitation, hyperthermia, and dilated pupils", "CNS depression, respiratory depression, and hypotension, often with normal or slightly constricted pupils"]'::jsonb, 3, 'Sedative-hypnotic toxicity causes generalized CNS and respiratory depression, hypotension, and often normal-to-small pupils, distinguishing it from stimulant or anticholinergic toxidromes.'),
(6, 183, 'Critical Care Scenarios', 'A patient''s chest X-ray shows a ''ground glass'' appearance bilaterally with worsening hypoxaemia following a recent large-volume blood transfusion. The nurse should consider:', '["No further evaluation necessary", "Simple volume overload with no other cause needed", "Transfusion-Related Acute Lung Injury (TRALI), a serious transfusion complication", "Normal expected finding after transfusion"]'::jsonb, 2, 'New bilateral pulmonary infiltrates with hypoxaemia within hours of transfusion should raise suspicion for TRALI, a serious and potentially fatal transfusion reaction requiring prompt recognition and supportive care.'),
(6, 184, 'Critical Care Scenarios', 'A patient on long-term diuretic therapy develops muscle weakness, cramping, and an irregular pulse. The nurse should suspect an electrolyte disturbance, most likely:', '["Hypernatraemia", "Hypokalaemia", "Hypercalcaemia", "Hyperglycaemia"]'::jsonb, 1, 'Muscle weakness, cramping and arrhythmia in a patient on diuretics (especially loop/thiazide) are classic signs of hypokalaemia, a common diuretic side effect.'),
(6, 185, 'Critical Care Scenarios', 'A patient with suspected PE has a low Wells score. Which test is the appropriate next step?', '["D-dimer testing to help rule out PE", "Pulmonary angiography", "V/Q scan only", "Immediate CT pulmonary angiography regardless of score"]'::jsonb, 0, 'In low pretest probability, a negative D-dimer has high negative predictive value and can safely rule out PE without further imaging.'),
(6, 186, 'Critical Care Scenarios', 'A patient in cardiogenic shock with low cardiac output and high SVR would most benefit from an agent that:', '["Decreases contractility", "Further increases SVR/afterload, such as phenylephrine", "Causes pure vasoconstriction without inotropic support", "Increases contractility and reduces afterload, such as dobutamine"]'::jsonb, 3, 'In cardiogenic shock with elevated afterload, an inodilator like dobutamine improves contractility while unloading the failing ventricle by reducing SVR.'),
(6, 187, 'Critical Care Scenarios', 'A patient presents with agitation, dilated pupils, tachycardia, hypertension, hyperthermia, and diaphoresis after suspected cocaine or amphetamine use. Which toxidrome is this?', '["Sympathomimetic toxidrome", "Opioid toxidrome", "Anticholinergic toxidrome", "Cholinergic toxidrome"]'::jsonb, 0, 'Sympathomimetic toxicity produces CNS and cardiovascular stimulation: agitation, mydriasis, tachycardia, hypertension, hyperthermia, and sweating (diaphoresis distinguishes it from anticholinergic toxicity, which causes dry skin).'),
(6, 188, 'Critical Care Scenarios', 'A patient develops signs of sepsis with an unknown source. Blood cultures are drawn from two different sites before starting antibiotics. This practice is done primarily to:', '["Save laboratory costs", "Reduce patient discomfort", "Delay treatment unnecessarily", "Improve the diagnostic yield and help distinguish true bacteraemia from contamination"]'::jsonb, 3, 'Drawing blood cultures from two separate sites before antibiotics improves the chance of identifying the causative organism and helps differentiate a true pathogen from a skin contaminant.'),
(6, 189, 'Critical Care Scenarios', 'A patient post-PE thrombolysis develops a sudden severe headache and decreased level of consciousness. The nurse should suspect:', '["Intracranial hemorrhage", "An expected medication side effect requiring no action", "Hypoglycemia", "A migraine caused by stress"]'::jsonb, 0, 'Thrombolytics carry a significant risk of intracranial hemorrhage; new neurological changes after thrombolysis are a medical emergency requiring immediate evaluation.'),
(6, 190, 'Critical Care Scenarios', 'A patient aspirates gastric contents during induction of anaesthesia. Which clinical picture is most typical in the following minutes?', '["Isolated bradycardia with normal oxygen saturation", "Gradual onset of unilateral leg swelling over several days", "Sudden dyspnoea, wheeze, tachycardia, and falling oxygen saturation", "Painless jaundice developing over the next week"]'::jsonb, 2, 'Acute aspiration classically presents with sudden dyspnoea, bronchospasm/wheeze, tachycardia, and hypoxaemia due to chemical injury and reflex bronchoconstriction.'),
(6, 191, 'Critical Care Scenarios', 'A patient with severe insensible fluid losses from high fever who produces a small volume of urine with high specific gravity best demonstrates:', '["Diabetes insipidus", "Acute tubular necrosis", "Appropriate physiological water conservation via ADH-mediated concentration of urine", "A state of overhydration"]'::jsonb, 2, 'Reduced urine volume with elevated specific gravity in the setting of insensible losses reflects a normally functioning concentrating mechanism responding to rising ADH levels.'),
(6, 192, 'Critical Care Scenarios', 'A patient with acute hepatic failure requires monitoring for coagulopathy primarily because:', '["The liver has no role in clotting factor production", "Coagulopathy never occurs in liver disease", "Only platelets are affected, never clotting factors", "The liver synthesises most clotting factors, so failure impairs coagulation and increases bleeding risk"]'::jsonb, 3, 'The liver produces most clotting factors; hepatic failure impairs this synthesis, causing coagulopathy and increased bleeding risk requiring close monitoring.'),
(6, 193, 'Critical Care Scenarios', 'A patient receiving a noradrenaline infusion via a peripheral IV develops swelling, pain, and blanching at the insertion site. The nurse should suspect:', '["Normal, expected finding requiring no action", "Extravasation, requiring the infusion to be stopped, the physician notified, and antidote/local treatment considered per protocol", "An allergic reaction requiring more noradrenaline", "Simply that the IV needs a faster flow rate"]'::jsonb, 1, 'Extravasation of a potent vasoconstrictor like noradrenaline can cause severe local tissue injury/necrosis — it must be recognised promptly and managed per protocol (often including phentolamine as an antidote).'),
(6, 194, 'Critical Care Scenarios', 'A patient with long-standing type 1 diabetes develops recurrent severe hypoglycemia with reduced awareness of warning symptoms. Which pathophysiologic change most likely underlies this ''hypoglycemia unawareness''?', '["Increased cortisol secretion masking symptoms", "Increased glucagon secretion causing symptom suppression", "Excess residual insulin secretion from the pancreas", "Impaired counter-regulatory glucagon and epinephrine responses from recurrent hypoglycemic episodes blunting the autonomic warning response"]'::jsonb, 3, 'Recurrent hypoglycemia progressively blunts both the glucagon and epinephrine counter-regulatory responses and lowers the glycemic threshold for autonomic (adrenergic) warning symptoms, creating a vicious cycle of impaired awareness and increased risk of severe hypoglycemia.'),
(6, 195, 'Critical Care Scenarios', 'A patient with chronic lithium therapy presents with coarse tremor, ataxia, confusion, and hyperreflexia. Serum lithium is significantly elevated. What is the definitive treatment for severe lithium toxicity?', '["Flumazenil", "Haemodialysis", "N-acetylcysteine", "Activated charcoal"]'::jsonb, 1, 'Lithium is not bound by activated charcoal and has a small molecular size and volume of distribution favourable for dialysis; haemodialysis is the definitive treatment for severe or renal-impaired lithium toxicity.'),
(6, 196, 'Critical Care Scenarios', 'A patient with decompensated heart failure and hypotension (cardiogenic shock physiology) may benefit from which inotropic agent to improve contractility and cardiac output?', '["Dobutamine", "Verapamil", "Metoprolol", "Furosemide"]'::jsonb, 0, 'Dobutamine is a positive inotrope that improves contractility and cardiac output in decompensated heart failure with hypoperfusion.'),
(6, 197, 'Critical Care Scenarios', 'A patient''s blood culture grows a common skin organism (coagulase-negative Staphylococcus) from only one of two culture sets drawn. The nurse understands this pattern often suggests:', '["Always indicates central line infection", "A laboratory error with no clinical relevance", "Possible contamination, requiring clinical correlation rather than automatic treatment", "Definite true bacteraemia requiring immediate aggressive treatment with no further consideration"]'::jsonb, 2, 'A single positive culture for a common skin contaminant (like coagulase-negative Staph) out of multiple sets often suggests contamination rather than true infection, requiring clinical correlation before treatment decisions.'),
(6, 198, 'Critical Care Scenarios', 'A patient with COPD receiving oxygen therapy develops worsening drowsiness and a rising respiratory rate that then slows dramatically. The nurse should suspect:', '["CO2 narcosis from excessive oxygen therapy suppressing hypoxic respiratory drive", "Normal sleep pattern", "A simple anxiety reaction", "Improved oxygenation with no concern"]'::jsonb, 0, 'In some chronic CO2-retaining COPD patients, excessive oxygen can blunt hypoxic respiratory drive, leading to hypoventilation, rising CO2, and eventual CO2 narcosis with drowsiness.'),
(6, 199, 'Critical Care Scenarios', 'A patient with a stroke presents with contralateral homonymous hemianopia and no motor weakness. Which cerebral artery territory is most likely affected?', '["Posterior cerebral artery", "Anterior cerebral artery", "Anterior spinal artery", "Middle cerebral artery"]'::jsonb, 0, 'The posterior cerebral artery supplies the occipital lobe (primary visual cortex); its occlusion classically produces contralateral homonymous hemianopia, often with macular sparing.'),
(6, 200, 'Critical Care Scenarios', 'A patient shivering on emergence from general anaesthesia most commonly has this symptom because of:', '["Hypoglycaemia", "Anxiety", "Local anaesthetic toxicity", "Perioperative hypothermia and altered thermoregulatory set point"]'::jsonb, 3, 'Anaesthetic agents impair central thermoregulation and promote heat loss, so postoperative shivering is most often related to intraoperative hypothermia as the body attempts to generate heat.');
insert into public.questions (id, topic, source, q, opts, ans_idx, exp, category, category_icon, is_active)
